# PyTorch publishes CUDA wheels on a per-CUDA-version index. A machine may use
# an index only if its NVIDIA driver supports that CUDA version (or newer).
# Ordered newest-first so the first compatible entry is the "best" choice.
_PYTORCH_CUDA_INDEXES = [
    (12.8, "cu128"),
    (12.6, "cu126"),
    (12.4, "cu124"),
    (12.1, "cu121"),
    (11.8, "cu118"),
]


def _nvidia_cuda_version():
    """Return the CUDA version (float) the installed NVIDIA driver supports,
    or None when no NVIDIA driver is found. Queries ``nvidia-smi``."""
    import shutil
    import subprocess

    exe = shutil.which("nvidia-smi") or "nvidia-smi"
    try:
        out = subprocess.run(
            [exe],
            capture_output=True,
            text=True,
            timeout=10,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        ).stdout
    except Exception:  # noqa: BLE001
        return None
    for line in out.splitlines():
        if "CUDA Version:" in line:
            try:
                return float(line.split("CUDA Version:")[1].split()[0])
            except (ValueError, IndexError):
                return None
    return None


def _pick_cuda_index(driver_cuda):
    """Return the best cuXXX index dir for a driver's CUDA version, or None."""
    if driver_cuda is None:
        return None
    for minor, dirname in _PYTORCH_CUDA_INDEXES:
        if minor <= driver_cuda:
            return dirname
    return None


def _otsu_threshold(values) -> float:
    """Return an Otsu threshold for a finite 1-D array (0.0 when undecidable)."""
    import numpy as np

    v = np.asarray(values, dtype="float64")
    v = v[np.isfinite(v)]
    if v.size == 0:
        return 0.0
    vmin, vmax = float(v.min()), float(v.max())
    if not vmax > vmin:
        return vmin
    hist, edges = np.histogram(v, bins=256, range=(vmin, vmax))
    hist = hist.astype("float64")
    centers = (edges[:-1] + edges[1:]) / 2.0
    weight = np.cumsum(hist)
    total = weight[-1]
    if total <= 0:
        return vmin
    mean_bg = np.cumsum(hist * centers)
    mean_total = mean_bg[-1]
    # Between-class variance for every split (ignore empty sides).
    w0 = weight[:-1]
    w1 = total - w0
    valid = (w0 > 0) & (w1 > 0)
    if not valid.any():
        return vmin
    m0 = np.zeros_like(w0)
    m0[valid] = mean_bg[:-1][valid] / w0[valid]
    m1 = np.zeros_like(w1)
    m1[valid] = (mean_total - mean_bg[:-1][valid]) / w1[valid]
    between = np.zeros_like(w0)
    between[valid] = w0[valid] * w1[valid] * (m0[valid] - m1[valid]) ** 2
    return float(centers[int(np.argmax(between))])


def _relabel_sequential(labels, min_area=1):
    """Drop labels smaller than `min_area` and renumber them 1..N (0 = background)."""
    import numpy as np
    from scipy import ndimage

    if labels.size == 0:
        return labels
    counts = np.bincount(labels.ravel())
    keep = np.zeros(counts.size, dtype=bool)
    if counts.size > 1:
        keep[1:] = counts[1:] >= max(1, int(min_area))
    if not keep.any():
        return np.zeros_like(labels)
    # Map old ids to 1..N in ascending order.
    remap = np.zeros(counts.size, dtype=np.int32)
    remap[keep] = np.arange(1, int(keep.sum()) + 1, dtype=np.int32)
    out = remap[labels]
    # `ndimage.label` already yields contiguous ids, but filtering can leave gaps.
    return out.astype(np.int32)



def _apply_scale_transform(x, config):
    """Apply a scaling transform (linear/log10/arcsinh) to a numeric array.

    log10 and arcsinh are applied to the magnitude with the sign restored, so
    negatives stay negative and zero stays zero.
    """
    import numpy as np
    if config is None:
        return x
    method = config.get("method", "linear")
    if method == "log10":
        abs_x = np.abs(x)
        with np.errstate(divide="ignore", invalid="ignore"):
            y = np.log10(abs_x)
        y = np.where(abs_x == 0, 0.0, y)  # zero stays zero
        return np.sign(x) * y
    if method == "arcsinh":
        cofactor = config.get("param")
        try:
            cofactor = float(cofactor) if cofactor else 5.0
        except (TypeError, ValueError):
            cofactor = 5.0
        abs_x = np.abs(x)
        y = np.arcsinh(abs_x / cofactor)
        return np.sign(x) * y
    return x


def _apply_scale_transforms(x, configs):
    """Apply a chain of scaling transforms (in order) to a numeric array."""
    for config in (configs or []):
        x = _apply_scale_transform(x, config)
    return x


def _inverse_scale_value(value: float, configs) -> float:
    """Map a transformed value back to the original data value."""
    import math

    out = float(value)
    for config in reversed(list(configs or [])):
        method = (config or {}).get("method", "linear")
        if method == "log10":
            out = math.copysign(10.0 ** abs(out), out) if out else 0.0
        elif method == "arcsinh":
            try:
                cofactor = float((config or {}).get("param") or 5.0)
            except (TypeError, ValueError):
                cofactor = 5.0
            out = math.copysign(math.sinh(abs(out)) * cofactor, out) if out else 0.0
    return out


def _round_value_candidates(low: float, high: float) -> list:
    """Round data values (…, 1, 2, 5, 10, 20, 50, …) inside [low, high]."""
    import math

    if not math.isfinite(low) or not math.isfinite(high) or high <= low:
        return []
    out = [0.0] if low <= 0.0 <= high else []
    top = max(abs(low), abs(high))
    bottom = min(abs(low), abs(high))
    if top <= 0:
        return sorted(out)
    start = math.floor(math.log10(bottom)) if bottom > 0 else 0
    end = math.ceil(math.log10(top))
    if end - start > 12:
        start = end - 12
    for exponent in range(start, end + 1):
        for mantissa in (1.0, 2.0, 5.0):
            value = mantissa * (10.0 ** exponent)
            for signed in (value, -value):
                if low <= signed <= high and signed not in out:
                    out.append(signed)
    return sorted(out)


def _nice_ticks(low: float, high: float, count: int = 6) -> list:
    """Round tick values (1/2/5 steps) covering [low, high]."""
    import math

    span = high - low
    if not math.isfinite(span) or span <= 0:
        return []
    raw = span / max(1, count - 1)
    exponent = math.floor(math.log10(raw))
    base = raw / (10 ** exponent)
    step = (1.0 if base <= 1 else 2.0 if base <= 2 else 5.0 if base <= 5 else 10.0)
    step *= 10 ** exponent
    if not math.isfinite(step) or step <= 0:
        return []
    value = math.ceil(low / step) * step
    out = []
    while value <= high + step * 1e-9 and len(out) < 60:
        out.append(round(value, 12))
        value += step
    return out


# --- Ordered map-module pipeline (Scale / Compensation / Unmix) -----------

def _rename_applies(stage, parquet_path) -> bool:
    """Whether a rename stage applies to this file (a None/empty scope = all)."""
    files = stage.get("files")
    if not files:
        return True
    return parquet_path is None or parquet_path in files


def _rename_stage(params) -> dict | None:
    """The column-rename stage declared by a Rename module's params, or None.

    Only column-mode renames produce a stage; file-mode renames are applied to
    display names elsewhere. Invalid rows are already excluded from `rename`.
    """
    if (params or {}).get("mode", "file") != "column":
        return None
    column_cfg = params.get("column") or {}
    files = {str(p) for p in (column_cfg.get("files") or [])}
    mapping = {
        str(k): str(v)
        for k, v in (column_cfg.get("rename") or {}).items()
        if k and v and str(k) != str(v)
    }
    if not files or not mapping:
        return None
    return {"files": files, "map": mapping}


def _pipeline_touches(stages, name) -> bool:
    """Whether any map stage changes or produces `name`."""
    for kind, stage in stages:
        if kind == "scale" and name in stage["columns"]:
            return True
        if kind in ("compensation", "unmix") and name in stage["names"]:
            return True
        if kind == "illumination":
            for sub in stage.get("submodules", []):
                if sub.get("channel") == name:
                    return True
        if kind == "rename":
            if name in stage["map"] or name in stage["map"].values():
                return True
    return False


def _pipeline_dependencies(stages, names, parquet_path=None) -> set:
    """Columns needed before the stages to obtain `names` after them.

    Rename stages map a downstream name back to the source column that feeds
    it (only for the files the rename is scoped to).
    """
    needed = set(names)
    for kind, stage in reversed(stages):
        if kind == "compensation":
            if needed & set(stage["names"]):
                needed |= set(stage["names"])
        elif kind == "batch_align":
            # The correction is per cell and needs every aligned channel to
            # decide which cluster the cell belongs to.
            if needed & set(stage.get("columns") or []):
                needed |= set(stage["columns"])
        elif kind == "unmix":
            if needed & set(stage["names"]):
                needed |= set(stage["columns"])
        elif kind == "illumination":
            for sub in stage.get("submodules", []):
                if sub.get("channel") in needed:
                    if sub.get("x"):
                        needed.add(sub["x"])
                    if sub.get("y"):
                        needed.add(sub["y"])
        elif kind == "rename":
            if not _rename_applies(stage, parquet_path):
                continue
            reverse = {v: k for k, v in stage["map"].items()}
            needed = {reverse.get(n, n) for n in needed}
    needed.discard(None)
    return needed


def _linear_combine(sources, weights):
    """Combine arrays with a (outputs × sources) weight matrix.

    Works for 1D arrays and for 2D arrays (image rasters).
    """
    import numpy as np

    if not sources:
        return []
    if sources[0].ndim == 1:
        matrix = np.column_stack(sources)
        return [matrix @ weights[i] for i in range(weights.shape[0])]
    stacked = np.stack(sources, axis=0)
    combined = np.tensordot(weights, stacked, axes=(1, 0))
    return [combined[i] for i in range(combined.shape[0])]


def _evaluate_stages(stages, values, names, parquet_path=None, cache=None,
                     origin=None):
    """Apply map-module stages in order to a {column: array} mapping."""
    import numpy as np

    values = dict(values)
    for kind, stage in stages:
        if kind == "scale":
            for column, config in stage["columns"].items():
                if column in values:
                    values[column] = _apply_scale_transform(
                        values[column], config
                    )
            continue
        if kind == "compensation":
            if parquet_path is not None and parquet_path not in stage["files"]:
                continue
            sources = stage["names"]
            if not all(name in values for name in sources):
                continue
            key = ("comp", stage.get("id"), parquet_path)
            out = cache.get(key) if cache is not None else None
            if out is None:
                combined = _linear_combine(
                    [values[name] for name in sources], stage["matrix"]
                )
                out = dict(zip(sources, combined))
                if cache is not None:
                    cache[key] = out
            values.update(out)
            continue
        if kind == "unmix":
            if parquet_path is not None and parquet_path not in stage["samples"]:
                continue
            sources = stage["columns"]
            if not all(name in values for name in sources):
                continue
            key = ("unmix", stage.get("task_id"), parquet_path)
            out = cache.get(key) if cache is not None else None
            if out is None:
                pinv = stage.get("_pinv")
                if pinv is None:
                    pinv = np.linalg.pinv(stage["matrix"])
                    stage["_pinv"] = pinv
                # C = X · pinv(M): output k = Σ_i X_i · pinv[i, k]
                combined = _linear_combine(
                    [values[name] for name in sources], pinv.T
                )
                out = dict(zip(stage["names"], combined))
                if cache is not None:
                    cache[key] = out
            values.update(out)
            continue
        if kind == "illumination":
            for sub in stage.get("submodules", []):
                if parquet_path is not None and parquet_path not in sub["files"]:
                    continue
                channel = sub.get("channel")
                if channel not in values:
                    continue
                x_values = values.get(sub.get("x"))
                y_values = values.get(sub.get("y"))
                mask = sub.get("mask")
                if x_values is None or y_values is None or mask is None:
                    continue
                if origin is not None:
                    x_origin, y_origin = origin
                else:
                    try:
                        x_origin = float(np.nanmin(x_values))
                        y_origin = float(np.nanmin(y_values))
                    except (TypeError, ValueError):
                        continue
                xi = np.mod(
                    np.rint(np.asarray(x_values, dtype="float64") - x_origin)
                    .astype(np.int64),
                    int(sub["tile_w"]),
                )
                yi = np.mod(
                    np.rint(np.asarray(y_values, dtype="float64") - y_origin)
                    .astype(np.int64),
                    int(sub["tile_h"]),
                )
                factor_map = mask[yi, xi]
                threshold = float(sub.get("T") or 0.0)
                factor = np.where(
                    factor_map > 0,
                    threshold / np.where(factor_map > 0, factor_map, 1.0),
                    1.0,
                )
                values[channel] = values[channel] * factor
            continue
        if kind == "batch_align":
            aligned = list(stage.get("columns") or [])
            if aligned and all(column in values for column in aligned):
                values.update(
                    _apply_batch_align(stage, values, parquet_path, cache)
                )
            continue
        if kind == "rename":
            if not _rename_applies(stage, parquet_path):
                continue
            for old, new in stage["map"].items():
                if old in values and old != new:
                    # On a name collision the renamed value wins (the user was
                    # warned in the module and chose to proceed).
                    values[new] = values.pop(old)
    return {name: values[name] for name in names if name in values}


def _assign_batch_clusters(model, matrix, cache, key):
    """Cluster id of every row, from the trained SOM codebook.

    The nearest code vector is found in chunks with the BLAS expansion of the
    squared distance, so a million cells take well under a second. The result
    is cached per (model, file) because the same rows are re-read by every
    downstream module.
    """
    import numpy as np

    if cache is not None and key in cache:
        return cache[key]
    codes = np.asarray(model["codes"], dtype="float64")
    node_cluster = np.asarray(model["node_cluster"])
    code_norm = np.einsum("ij,ij->i", codes, codes)
    out = np.empty(matrix.shape[0], dtype=np.int16)
    chunk = 200_000
    for start in range(0, matrix.shape[0], chunk):
        block = matrix[start:start + chunk]
        distances = (
            np.einsum("ij,ij->i", block, block)[:, None]
            - 2.0 * (block @ codes.T)
            + code_norm[None, :]
        )
        out[start:start + chunk] = node_cluster[distances.argmin(axis=1)]
    if cache is not None:
        if len(cache) > 8:
            cache.clear()
        cache[key] = out
    return out


def _apply_batch_align(stage, values, parquet_path, cache=None) -> dict:
    """Correct the aligned columns of one file (see the Batch Alignment module)."""
    import numpy as np

    path = str(parquet_path) if parquet_path is not None else ""
    batch = (stage.get("files") or {}).get(path)
    if batch is None:
        return {}
    columns = list(stage.get("columns") or [])
    arrays = [np.asarray(values[column], dtype="float64") for column in columns]
    n_rows = arrays[0].size
    if any(a.size != n_rows for a in arrays):
        return {}
    finite = np.ones(n_rows, dtype=bool)
    for array in arrays:
        finite &= np.isfinite(array)
    if not finite.any():
        return {}

    if stage.get("method") == "combat":
        affine = np.asarray(stage["affine"])
        out = {}
        for j, column in enumerate(columns):
            scale = float(affine[batch, j, 0])
            shift = float(affine[batch, j, 1])
            result = np.array(values[column], dtype="float64", copy=True)
            result[finite] = result[finite] * scale + shift
            out[column] = result
        return out

    if stage.get("codes") is None:
        return {}
    rows = np.flatnonzero(finite)
    matrix = np.column_stack([array[finite] for array in arrays])
    # The row subset can change (an upstream Subsample), so the key carries a
    # cheap fingerprint of the actual values, not just the row count.
    fingerprint = round(float(matrix.sum()), 3) if matrix.size else 0.0
    key = ("ba_nodes", stage.get("id"), stage.get("model_id"), path,
           matrix.shape[0], fingerprint)
    clusters = _assign_batch_clusters(stage, matrix, cache, key)
    knots_x = np.asarray(stage["knots_x"])
    knots_y = np.asarray(stage["knots_y"])
    has_spline = np.asarray(stage["has_spline"])
    out = {}
    for j, column in enumerate(columns):
        out[column] = np.array(values[column], dtype="float64", copy=True)
    n_clusters = knots_y.shape[1]
    global_x = stage.get("global_x")
    global_y = stage.get("global_y")
    has_global = stage.get("has_global")
    for cluster in np.unique(clusters):
        cluster = int(cluster)
        if cluster < 0 or cluster >= n_clusters:
            continue
        target = rows[clusters == cluster]
        if target.size == 0:
            continue
        if bool(has_spline[batch, cluster]):
            for j, column in enumerate(columns):
                out[column][target] = np.interp(
                    out[column][target], knots_x[batch, cluster, j],
                    knots_y[batch, cluster, j],
                )
        elif has_global is not None and bool(has_global[batch]):
            for j, column in enumerate(columns):
                out[column][target] = np.interp(
                    out[column][target], global_x[batch, j], global_y[batch, j]
                )
    return out


def _point_in_polygon(x, y, points):
    """Vectorized ray-casting point-in-polygon test (boolean mask)."""
    import numpy as np
    px = np.asarray([p[0] for p in points], dtype=float)
    py = np.asarray([p[1] for p in points], dtype=float)
    n = len(px)
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    inside = np.zeros(x.shape, dtype=bool)
    for i in range(n):
        xi, yi = px[i], py[i]
        xj, yj = px[(i + 1) % n], py[(i + 1) % n]
        cond = (yi > y) != (yj > y)
        with np.errstate(divide="ignore", invalid="ignore"):
            x_cross = (xj - xi) * (y - yi) / (yj - yi) + xi
        inside ^= cond & (x < x_cross)
    return inside


def _gate_mask(x, y, gate):
    """Return a boolean mask for the points inside `gate` (in data space)."""
    import numpy as np
    t = gate.get("type")
    if t == "rect":
        x0, y0 = gate["pos"]
        w, h = gate["size"]
        return (x >= x0) & (x <= x0 + w) & (y >= y0) & (y <= y0 + h)
    if t == "ellipse":
        x0, y0 = gate["pos"]
        w, h = gate["size"]
        cx = x0 + w / 2.0
        cy = y0 + h / 2.0
        rx = w / 2.0
        ry = h / 2.0
        with np.errstate(divide="ignore", invalid="ignore"):
            return ((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2 <= 1.0
    if t == "polygon":
        return _point_in_polygon(x, y, gate["points"])
    if t == "quadrant":
        vx = gate.get("vx", 0.0)
        hy = gate.get("hy", 0.0)
        q = gate.get("quadrant", 1)
        if q == 1:
            return (x >= vx) & (y >= hy)
        if q == 2:
            return (x < vx) & (y >= hy)
        if q == 3:
            return (x < vx) & (y < hy)
        if q == 4:
            return (x >= vx) & (y < hy)
    if t == "range":
        x1 = min(gate["x1"], gate["x2"])
        x2 = max(gate["x1"], gate["x2"])
        return (x >= x1) & (x <= x2)
    if t == "split":
        vx = gate.get("vx", 0.0)
        if gate.get("side") == "left":
            return x < vx
        return x >= vx
    if t == "skewed_quadrant":
        cx, cy = gate["center"]
        vx = x - cx
        vy = y - cy
        dirs = []
        for key in ("p_right", "p_up", "p_left", "p_down"):
            px, py = gate[key]
            dirs.append((px - cx, py - cy))
        d_r, d_u, d_l, d_dn = dirs

        def wedge(a, b):
            # a point is in the wedge from arm a to arm b (counter-clockwise)
            return (a[0] * vy - a[1] * vx >= 0) & (vx * b[1] - vy * b[0] >= 0)

        q = gate.get("quadrant", 1)
        if q == 1:
            return wedge(d_r, d_u)
        if q == 2:
            return wedge(d_u, d_l)
        if q == 3:
            return wedge(d_l, d_dn)
        if q == 4:
            return wedge(d_dn, d_r)
    return np.ones(x.shape, dtype=bool)


def _gate_source_ids(gate):
    """Return the ids of the source gates a boolean gate depends on."""
    if gate.get("type") == "not":
        s = gate.get("source")
        return [s] if s else []
    if gate.get("type") in ("and", "or"):
        return list(gate.get("sources", []))
    return []


# Geometry fields that can differ per file (never the gate type or axes).
_GATE_GEOMETRY_KEYS = {
    "rect": ("pos", "size"),
    "ellipse": ("pos", "size"),
    "polygon": ("points",),
    "quadrant": ("vx", "hy"),
    "split": ("vx",),
    "range": ("x1", "x2"),
    "skewed_quadrant": ("center", "p_right", "p_up", "p_left", "p_down"),
}

# Display state captured on a gate when it is drawn, so clicking the gate later
# restores the plot type, colour mode and colour parameters it was drawn with.
_GATING_DISPLAY_KEYS = (
    "color_mode", "color_param", "palette", "solid_color",
    "point_size", "fixed_point_size",
    "image_channel", "image_min", "image_max",
    "bins", "hist_mode", "hist_color", "curve_color",
)


def _gating_display_snapshot(preview):
    """Capture the display state (plot colouring) currently shown in the preview."""
    return {
        key: copy.deepcopy(preview.get(key))
        for key in _GATING_DISPLAY_KEYS
        if preview.get(key) is not None
    }


def _gate_group_id(gate):
    """The id whose geometry is shared across a group of gates.

    Quadrant / split / skewed-quadrant gates come in groups bound to one
    crosshair / line / ray set; their geometry is shared, so per-file
    overrides are stored once per group instead of once per sub-gate.
    """
    for key in ("crosshair_id", "split_id", "skewed_id"):
        if gate.get(key):
            return gate[key]
    return gate.get("id")


def _gate_geometry(gate):
    """The editable geometry fields of a gate (shape + position only)."""
    keys = _GATE_GEOMETRY_KEYS.get(gate.get("type"), ())
    out = {}
    for key in keys:
        value = gate.get(key)
        if value is not None:
            out[key] = copy.deepcopy(value)
    return out


def _merge_gate_geometry(gate, geometry):
    """Return a shallow copy of `gate` with `geometry` fields overlaid."""
    out = dict(gate)
    for key, value in (geometry or {}).items():
        out[key] = copy.deepcopy(value)
    return out


def _resolve_gates_for_file(gates, per_file, file_key):
    """Return a copy of `gates` with the given file's overrides merged in.

    `per_file` maps a group id to ``{file_key: geometry}``. Files without an
    override fall back to the shared geometry, so only divergent files are
    stored.
    """
    if not per_file or not file_key:
        return list(gates)
    resolved = []
    for gate in gates:
        group = _gate_group_id(gate)
        override = (per_file.get(group) or {}).get(file_key)
        resolved.append(_merge_gate_geometry(gate, override) if override else dict(gate))
    return resolved


def _gate_needed_columns(gate, by_id):
    """Return the x/y column names needed to compute a gate's own mask."""
    cols = set()
    for key in ("x", "y"):
        v = gate.get(key)
        if v:
            cols.add(v)
    for sid in _gate_source_ids(gate):
        src = by_id.get(sid)
        if src is not None:
            for key in ("x", "y"):
                v = src.get(key)
                if v:
                    cols.add(v)
    return cols


def _gate_own_mask(gate, by_id, get_col, transforms, existing):
    """Return a gate's own boolean mask (transformed data), handling boolean
    gates (NOT / AND / OR)."""
    if gate.get("type") == "not":
        src = by_id.get(gate.get("source"))
        if src is None:
            return None
        sx, sy = src.get("x"), src.get("y")
        if not sx or sx not in existing or (sy and sy not in existing):
            return None
        x = _apply_scale_transforms(get_col(sx), transforms.get(sx))
        y = _apply_scale_transforms(get_col(sy), transforms.get(sy)) if sy else None
        return ~_gate_mask(x, y, src)
    if gate.get("type") in ("and", "or"):
        combine_and = gate.get("type") == "and"
        result = None
        for sid in gate.get("sources", []):
            src = by_id.get(sid)
            if src is None:
                continue
            sx, sy = src.get("x"), src.get("y")
            if not sx or sx not in existing or (sy and sy not in existing):
                continue
            x = _apply_scale_transforms(get_col(sx), transforms.get(sx))
            y = _apply_scale_transforms(get_col(sy), transforms.get(sy)) if sy else None
            sm = _gate_mask(x, y, src)
            if result is None:
                result = sm
            elif combine_and:
                result = result & sm
            else:
                result = result | sm
        return result
    x_name, y_name = gate.get("x"), gate.get("y")
    if not x_name or x_name not in existing or (y_name and y_name not in existing):
        return None
    x = _apply_scale_transforms(get_col(x_name), transforms.get(x_name))
    y = _apply_scale_transforms(get_col(y_name), transforms.get(y_name)) if y_name else None
    return _gate_mask(x, y, gate)


def _compute_gate_filter_mask(gates, gate_id, parquet_path, transforms,
                              existing=None, extra=None):
    """Return the AND mask of a gate and all its ancestors (transformed data).

    `existing` lists the usable column names and `extra` supplies values for
    columns that are computed on the fly (unmixed parameters). Returns None if
    the gate cannot be computed (no x/y columns). Raises KeyError if a needed
    column is missing.
    """
    import numpy as np
    import pandas as pd
    by_id = {g["id"]: g for g in gates}
    chain = []
    cur = by_id.get(gate_id)
    while cur is not None:
        chain.append(cur)
        cur = by_id.get(cur.get("parent"))
    chain.reverse()
    if not chain:
        return None
    needed = set()
    for g in chain:
        needed |= _gate_needed_columns(g, by_id)
    if not needed:
        return None
    extra = extra or {}
    if existing is None:
        base_cols = [c for c in sorted(needed) if c not in extra]
        df = pd.read_parquet(parquet_path, columns=base_cols)
        existing = set(df.columns) | set(extra)
    else:
        existing = set(existing)
        base_cols = [
            c for c in sorted(needed) if c in existing and c not in extra
        ]
        df = (
            pd.read_parquet(parquet_path, columns=base_cols)
            if base_cols else pd.DataFrame()
        )
    cache = {}

    def get_col(name):
        if name not in cache:
            if name in extra:
                cache[name] = np.asarray(extra[name], dtype="float64")
            else:
                cache[name] = pd.to_numeric(
                    df[name], errors="coerce"
                ).to_numpy(dtype="float64")
        return cache[name]

    mask = None
    for g in chain:
        gm = _gate_own_mask(g, by_id, get_col, transforms, existing)
        if gm is None:
            continue
        mask = gm if mask is None else (mask & gm)
    return mask


def _gate_chain(gates, gate_id):
    """Return the gates from root down to `gate_id` (inclusive), in order."""
    by_id = {g["id"]: g for g in gates}
    chain = []
    cur = by_id.get(gate_id)
    while cur is not None:
        chain.append(cur)
        cur = by_id.get(cur.get("parent"))
    chain.reverse()
    return chain


def _gate_label_position(gate):
    """Return an (x, y) point inside `gate` for placing its name label."""
    t = gate.get("type")
    xr = (gate.get("xmin", 0.0), gate.get("xmax", 1.0))
    yr = (gate.get("ymin", 0.0), gate.get("ymax", 1.0))
    dx = (xr[1] - xr[0]) * 0.12
    dy = (yr[1] - yr[0]) * 0.12
    if t in ("rect", "ellipse"):
        x0, y0 = gate["pos"]
        w, h = gate["size"]
        return (x0 + w / 2.0, y0 + h / 2.0)
    if t == "polygon":
        pts = gate["points"]
        return (
            sum(p[0] for p in pts) / len(pts),
            sum(p[1] for p in pts) / len(pts),
        )
    if t == "quadrant":
        vx, hy = gate.get("vx", 0.0), gate.get("hy", 0.0)
        q = gate.get("quadrant", 1)
        sx = 1 if q in (1, 4) else -1
        sy = 1 if q in (1, 2) else -1
        return (vx + sx * dx, hy + sy * dy)
    if t == "range":
        x1 = min(gate["x1"], gate["x2"])
        x2 = max(gate["x1"], gate["x2"])
        return ((x1 + x2) / 2.0, (yr[0] + yr[1]) / 2.0)
    if t == "split":
        vx = gate.get("vx", 0.0)
        sx = -1 if gate.get("side") == "left" else 1
        return (vx + sx * dx, (yr[0] + yr[1]) / 2.0)
    if t == "skewed_quadrant":
        cx, cy = gate["center"]
        arms = []
        for key in ("p_right", "p_up", "p_left", "p_down"):
            px, py = gate[key]
            arms.append((px - cx, py - cy))
        q = gate.get("quadrant", 1)
        if q == 1:
            a, b = arms[0], arms[1]
        elif q == 2:
            a, b = arms[1], arms[2]
        elif q == 3:
            a, b = arms[2], arms[3]
        else:
            a, b = arms[3], arms[0]
        la = (a[0] ** 2 + a[1] ** 2) ** 0.5 or 1.0
        lb = (b[0] ** 2 + b[1] ** 2) ** 0.5 or 1.0
        bx = a[0] / la + b[0] / lb
        by = a[1] / la + b[1] / lb
        lb2 = (bx ** 2 + by ** 2) ** 0.5 or 1.0
        d = max(dx, dy) * 1.5
        return (cx + bx / lb2 * d, cy + by / lb2 * d)
    return ((xr[0] + xr[1]) / 2.0, (yr[0] + yr[1]) / 2.0)


def _default_gating_preview(rec, cols) -> dict:
    """A fresh scatter preview config for the gating tree (first file + axes)."""
    return {
        "type": "scatter",
        "file": rec.get("parquet") if rec else None,
        "file_name": rec.get("name") if rec else None,
        "x": cols[0] if cols else None,
        "y": cols[1] if len(cols) > 1 else (cols[0] if cols else None),
        "last_x": cols[0] if cols else None,
        "last_y": cols[1] if len(cols) > 1 else (cols[0] if cols else None),
        "color_mode": "density",
        "color_param": None,
        "palette": _default_palette(),
        "xmin": None,
        "xmax": None,
        "ymin": None,
        "ymax": None,
        "point_size": 4,
        "fixed_point_size": False,
        "solid_color": (0, 0, 200),
        "show_axes": True,
        "show_axis_names": True,
        "show_indices": True,
        "show_sample_name": True,
        "label_font_size": 20,
        "label_bold": False,
        "label_bg_opacity": 50,
        "show_gate_labels": True,
        "label_show_percent": True,
    }


class _GatingState:
    """Attribute bag holding one gate tree's state.

    Every gating method addresses its state as ``page._gating_*`` and only uses
    the page for those attributes, so passing one of these instead of the page
    lets the Unmix module embed several independent gate trees that reuse the
    same drawing, tree and settings code.
    """

    def __init__(self) -> None:
        self._gating_dirty = False


class _GateLabel(pg.TextItem):
    """A gate name label that the user can drag to offset from its gate."""

    def __init__(self, on_drag_finished=None, **kwargs):
        super().__init__(**kwargs)
        self._on_drag_finished = on_drag_finished
        self._dragging = False
        self._start_data = None
        self._down_data = None

    def hoverEvent(self, ev):
        # Claim the drag so the label stays grabbable even when it sits on top
        # of a gate ROI (which also accepts drags over its whole shape).
        if not ev.isExit() and self.isVisible():
            ev.acceptDrags(Qt.MouseButton.LeftButton)

    def mouseDragEvent(self, ev):
        if ev.button() != Qt.MouseButton.LeftButton:
            ev.ignore()
            return
        if ev.isStart():
            self._dragging = True
            vb = self.getViewBox()
            self._start_data = self.pos()
            self._down_data = (
                vb.mapSceneToView(ev.buttonDownScenePos()) if vb is not None else None
            )
            ev.accept()
            return
        if not self._dragging:
            ev.ignore()
            return
        if ev.isFinish():
            self._dragging = False
            if self._on_drag_finished is not None:
                self._on_drag_finished(self)
        else:
            vb = self.getViewBox()
            if vb is not None and self._down_data is not None:
                cur = vb.mapSceneToView(ev.scenePos())
                self.setPos(self._start_data + (cur - self._down_data))
        ev.accept()


class _GatingStatsWorker:
    """Background worker that computes gate statistics with column/mask caches.

    The worker owns its caches so no shared mutable state is touched by the
    main thread. Requests are queued FIFO; each carries a generation number so
    the main thread can discard stale results.
    """

    def __init__(self):
        self._req_q = queue.Queue()
        self._res_q = queue.Queue()
        self._stop = threading.Event()
        self._columns = {}   # {parquet_path: {col: float64 ndarray}}
        self._current_path = None
        self._masks = {}     # {gate_id: population bool ndarray}
        self._counts = {}    # {gate_id: int}
        self._thread = threading.Thread(target=self._run, daemon=True)
        self._thread.start()

    def request(self, generation, parquet_path, gates, stages, base_columns,
                affected, virtual=None, row_index=None):
        self._req_q.put(
            (generation, parquet_path, gates, stages, set(base_columns),
             affected, dict(virtual or {}), row_index)
        )

    def poll(self):
        """Return any finished (generation, stats) results."""
        out = []
        while True:
            try:
                out.append(self._res_q.get_nowait())
            except queue.Empty:
                break
        return out

    def stop(self):
        self._stop.set()

    def _run(self):
        while not self._stop.is_set():
            try:
                req = self._req_q.get(timeout=0.2)
            except queue.Empty:
                continue
            try:
                res = self._compute(*req)
            except Exception:
                res = None
            self._res_q.put(res)

    def _compute(self, generation, parquet_path, gates, stages, base_columns,
                 affected, virtual=None, row_index=None):
        import numpy as np
        import pandas as pd
        if not parquet_path or not gates:
            return (generation, {})
        if self._current_path != parquet_path:
            self._columns = {}
            self._masks = {}
            self._counts = {}
            self._current_path = parquet_path
        if affected is None:
            # Full recompute: the gate set may have changed, so reset caches.
            self._masks = {}
            self._counts = {}
        by_id = {g["id"]: g for g in gates}
        needed = set()
        for g in gates:
            needed |= _gate_needed_columns(g, by_id)
        if not needed:
            return (generation, {})
        dependencies = _pipeline_dependencies(stages, needed, parquet_path)
        base_needed = [c for c in dependencies if c in base_columns]
        cols = self._columns
        missing = set(base_needed) - set(cols)
        if missing:
            try:
                df = pd.read_parquet(parquet_path, columns=sorted(missing))
            except Exception:
                return (generation, {})
            for name in missing:
                cols[name] = pd.to_numeric(
                    df[name], errors="coerce"
                ).to_numpy(dtype="float64")
            self._columns = cols
        arrays = {name: cols[name] for name in base_needed if name in cols}
        for name, values_arr in (virtual or {}).items():
            arrays.setdefault(name, values_arr)
        if row_index is not None and arrays:
            # An upstream Subsample module limits the visible rows.
            n_rows = len(next(iter(arrays.values())))
            arrays = {
                name: (arr[row_index] if len(arr) == n_rows else arr)
                for name, arr in arrays.items()
            }
        arrays = _evaluate_stages(stages, arrays, needed, parquet_path)
        existing = set(arrays)
        if not arrays:
            return (generation, {})
        n_total = len(next(iter(arrays.values())))
        by_parent = {}
        for g in gates:
            by_parent.setdefault(g.get("parent"), []).append(g)

        def own_mask(g):
            return _gate_own_mask(
                g, by_id, lambda name: arrays[name], {}, existing
            )

        def compute_subtree(gid):
            stack = [gid]
            while stack:
                cur = stack.pop()
                g = by_id.get(cur)
                if g is None:
                    continue
                om = own_mask(g)
                if om is None:
                    self._masks[cur] = None
                    self._counts[cur] = None
                    continue
                parent_id = g.get("parent")
                pm = self._masks.get(parent_id) if parent_id else None
                m = om if pm is None else (pm & om)
                self._masks[cur] = m
                self._counts[cur] = int(np.sum(m))
                for child in by_parent.get(cur, []):
                    stack.append(child["id"])

        if affected is None:
            for top in by_parent.get(None, []):
                compute_subtree(top["id"])
        else:
            affected_set = set(affected)
            tops = [
                gid for gid in affected_set
                if by_id.get(gid, {}).get("parent") not in affected_set
            ]
            for gid in tops:
                compute_subtree(gid)

        result = {}
        for g in gates:
            c = self._counts.get(g["id"])
            if c is None:
                continue
            pid = g.get("parent")
            if pid:
                pc = self._counts.get(pid)
                if pc is None:
                    pc = n_total
            else:
                pc = n_total
            pct = (c / pc * 100.0) if pc else 0.0
            result[g["id"]] = (c, pct)
        return (generation, result)


# ----- global (user-level) settings -----------------------------------
# Stored next to extensions.json in %APPDATA%\Smage: preferences follow the
# user, not the project.
_SETTINGS_FILENAME = "settings.json"

GLOBAL_DEFAULT_SETTINGS = {
    "appearance": {
        "font_size": 9,
        "density": "normal",
        "plot_background": "white",
        "remember_geometry": True,
    },
    "plot": {
        # Points drawn per scatter plot (larger files are sampled).
        "max_points": 50000,
        # Placeholder for the future N-by-N plot grid: many small scatters at
        # once, so it keeps fewer points. Kept at 1/10 of `max_points` unless
        # the user edits it.
        "nxn_max_points": 5000,
        # Bins per axis used to estimate point density for colouring.
        "density_grid": 200,
        "default_colormap": "viridis",
    },
    "colormaps": [],
    "window_geometry": "",
}

_GLOBAL_SETTINGS = None

# Old palette names that no longer resolve, mapped to their replacement.
_COLORMAP_ALIASES = {"grayscale": "gray"}


def _settings_dir() -> Path:
    import os

    base = os.environ.get("APPDATA") or str(Path.home())
    return Path(base) / "Smage"


def _settings_path() -> Path:
    return _settings_dir() / _SETTINGS_FILENAME


def _debug_log(message: str) -> None:
    """Append a line to %APPDATA%\\Smage\\debug.log (diagnostics only)."""
    try:
        _settings_dir().mkdir(parents=True, exist_ok=True)
        with (_settings_dir() / "debug.log").open("a", encoding="utf-8") as fh:
            fh.write(f"[{datetime.now():%Y-%m-%d %H:%M:%S}] {message}\n")
    except OSError:
        pass


def _log_exception(exc: BaseException) -> None:
    """Append a traceback to %APPDATA%\\Smage\\error.log (pythonw has no console)."""
    import traceback

    try:
        _settings_dir().mkdir(parents=True, exist_ok=True)
        with (_settings_dir() / "error.log").open("a", encoding="utf-8") as fh:
            fh.write(f"\n[{datetime.now():%Y-%m-%d %H:%M:%S}]\n")
            fh.write("".join(traceback.format_exception(type(exc), exc, exc.__traceback__)))
    except OSError:
        pass


def _install_excepthook() -> None:
    """Log uncaught exceptions instead of losing them in a windowless app."""

    def hook(exc_type, exc, tb):
        try:
            _settings_dir().mkdir(parents=True, exist_ok=True)
            import traceback

            with (_settings_dir() / "error.log").open("a", encoding="utf-8") as fh:
                fh.write(f"\n[{datetime.now():%Y-%m-%d %H:%M:%S}]\n")
                fh.write("".join(traceback.format_exception(exc_type, exc, tb)))
        except OSError:
            pass

    sys.excepthook = hook


def _merge_settings(defaults, loaded):
    out = copy.deepcopy(defaults)
    if not isinstance(loaded, dict):
        return out
    for key, value in loaded.items():
        if isinstance(out.get(key), dict) and isinstance(value, dict):
            out[key] = _merge_settings(out[key], value)
        else:
            out[key] = value
    return out


def _global_settings() -> dict:
    """The live settings dict (loads settings.json on first use)."""
    global _GLOBAL_SETTINGS
    if _GLOBAL_SETTINGS is None:
        try:
            loaded = json.loads(_settings_path().read_text(encoding="utf-8"))
        except (OSError, ValueError):
            loaded = {}
        _GLOBAL_SETTINGS = _merge_settings(GLOBAL_DEFAULT_SETTINGS, loaded)
    return _GLOBAL_SETTINGS


def _save_global_settings(settings: dict) -> None:
    global _GLOBAL_SETTINGS
    _GLOBAL_SETTINGS = settings
    try:
        _settings_dir().mkdir(parents=True, exist_ok=True)
        _settings_path().write_text(
            json.dumps(settings, indent=2), encoding="utf-8"
        )
    except OSError:
        pass


def _setting(section: str, key: str, default=None):
    return (_global_settings().get(section) or {}).get(key, default)


def _default_palette() -> str:
    name = _setting("plot", "default_colormap", "viridis")
    return name if isinstance(name, str) and name else "viridis"


def _plot_background() -> str:
    """Plot canvas colour (white or a light grey that is easier on the eyes)."""
    return "#f2f4f6" if _setting("appearance", "plot_background", "white") == "grey" else "w"


def _app_stylesheet() -> str:
    """APP_STYLE plus the optional compact-density rules."""
    if _setting("appearance", "density", "normal") != "compact":
        return APP_STYLE
    return APP_STYLE + """
/* compact UI density */
QTreeView::item { padding: 0px; min-height: 18px; }
QTableView::item { padding: 0px; min-height: 18px; }
QHeaderView::section { padding: 1px 4px; }
"""


def _custom_colormaps() -> list:
    """User-defined colormaps (only the well-formed ones)."""
    maps = _global_settings().get("colormaps")
    if not isinstance(maps, list):
        return []
    out = []
    for entry in maps:
        if (
            isinstance(entry, dict)
            and isinstance(entry.get("name"), str)
            and entry.get("name")
            and isinstance(entry.get("stops"), list)
        ):
            out.append(entry)
    return out


def _normalize_stops(stops) -> list:
    """Validated ``[(position, (r, g, b)), ...]`` sorted by position."""
    out = []
    for item in stops or []:
        try:
            pos = float(item[0])
            rgb = tuple(int(max(0, min(255, int(c)))) for c in item[1][:3])
        except (TypeError, ValueError, IndexError):
            continue
        if len(rgb) != 3:
            continue
        out.append((min(1.0, max(0.0, pos)), rgb))
    out.sort(key=lambda stop: stop[0])
    return out


def _colormap_from_stops(stops):
    import pyqtgraph as pg

    points = _normalize_stops(stops)
    if len(points) < 2:
        raise ValueError("a colormap needs at least two stops")
    return pg.ColorMap(
        [pos for pos, _ in points], [list(rgb) for _, rgb in points]
    )


_COLORMAP_GROUPS_CACHE = None
_GRADIENT_CACHE = {}


def _colormap_groups() -> list:
    """``[(group_title, [name, ...]), ...]`` for every selectable colormap."""
    import pyqtgraph as pg

    global _COLORMAP_GROUPS_CACHE
    if _COLORMAP_GROUPS_CACHE is None:
        try:
            mpl = sorted(pg.colormap.listMaps("matplotlib"))
        except Exception:
            mpl = []
        try:
            cet = sorted(n for n in pg.colormap.listMaps() if n not in mpl)
        except Exception:
            cet = []
        _COLORMAP_GROUPS_CACHE = [
            ("Standard", list(FIGURE_PALETTES)),
            ("Custom", []),
            ("Matplotlib", mpl),
            ("ColorCET", cet),
        ]
    groups = [(title, list(names)) for title, names in _COLORMAP_GROUPS_CACHE]
    groups[1] = ("Custom", [m["name"] for m in _custom_colormaps()])
    return groups


def _gradient_pixmap(lut, width: int, height: int):
    """Paint a horizontal colour bar from a lookup table."""
    import numpy as _np

    pixmap = QPixmap(width, height)
    pixmap.fill(QColor("#d8dee6"))
    if lut is not None and len(lut):
        lut = _np.asarray(lut)
        painter = QPainter(pixmap)
        for i in range(width):
            value = lut[min(i, len(lut) - 1)]
            painter.setPen(QColor(int(value[0]), int(value[1]), int(value[2])))
            painter.drawLine(i, 0, i, height - 1)
        painter.end()
    return pixmap


def _colormap_gradient_pixmap(name: str, width: int = 110, height: int = 14):
    """A small bar showing the colormap's colours, for list/preview widgets."""
    key = (name, width, height)
    cached = _GRADIENT_CACHE.get(key)
    if cached is not None:
        return cached
    try:
        lut = _figure_colormap(name).getLookupTable(0.0, 1.0, max(2, width))
    except Exception:
        lut = None
    pixmap = _gradient_pixmap(lut, width, height)
    _GRADIENT_CACHE[key] = pixmap
    return pixmap


def _colormap_name_taken(name: str) -> bool:
    if not name:
        return False
    for _title, names in _colormap_groups():
        if name in names:
            return True
    return False


def _palette_names() -> list:
    """Standard colormaps followed by the user's custom ones."""
    names = list(FIGURE_PALETTES)
    for entry in _custom_colormaps():
        if entry["name"] not in names:
            names.append(entry["name"])
    return names


def _figure_colormap(name: str):
    """Return a pyqtgraph ColorMap for a palette name, with a fallback."""
    import pyqtgraph as pg
    if not isinstance(name, str) or not name:
        name = "viridis"
    name = _COLORMAP_ALIASES.get(name, name)
    for entry in _custom_colormaps():
        if entry.get("name") == name:
            try:
                return _colormap_from_stops(entry.get("stops"))
            except Exception:
                break
    # Matplotlib maps must be requested from their own source: the default
    # lookup raises FileNotFoundError for them.
    for kwargs in ({}, {"source": "matplotlib"}):
        try:
            return pg.colormap.get(name, **kwargs)
        except Exception:
            continue
    return pg.ColorMap([0.0, 1.0], [(0, 0, 255), (255, 0, 0)])


def _row_priorities(indices, seed: int = 42):
    """A deterministic pseudo-random priority in [0, 1) per row index."""
    import numpy as np

    x = np.asarray(indices, dtype=np.uint64) + np.uint64(int(seed) & 0xFFFFFFFF)
    with np.errstate(over="ignore"):
        x = (x ^ (x >> np.uint64(30))) * np.uint64(0xBF58476D1CE4E5B9)
        x = (x ^ (x >> np.uint64(27))) * np.uint64(0x94D049BB133111EB)
        x = x ^ (x >> np.uint64(31))
    return (x >> np.uint64(11)).astype(np.float64) * (1.0 / 9007199254740992.0)


def _figure_default_size(ptype: str | None) -> list:
    """Default card size: scatter/histogram are square, image is wider.

    All three share the same height (400), so a row of new plots lines up.
    """
    if ptype in ("scatter", "histogram"):
        return [400, 400]
    return [440, 400]


def _stable_sample_selection(keep, max_points: int, seed: int = 42):
    """Boolean mask (over ``values[keep]``) of the rows to draw.

    Every row gets a priority from its *absolute* row index, so a gate that
    lets different rows through only adds/removes the rows near the cut-off
    instead of re-drawing the whole cloud (what ``rng.choice`` does). Returns
    ``None`` when every visible row fits.

    Priorities are computed in chunks, so a file with tens of millions of
    rows never needs a full-size float array.
    """
    import numpy as np

    count = int(np.count_nonzero(keep))
    if count <= max_points:
        return None
    selection = np.zeros(count, dtype=bool)
    chunk = max(1_000_000, int(max_points) * 8)
    best_priority = np.empty(0, dtype=np.uint64)
    best_position = np.empty(0, dtype=np.int64)
    position = 0
    for start in range(0, keep.size, chunk):
        block = keep[start:start + chunk]
        inside = np.flatnonzero(block)
        if inside.size == 0:
            continue
        priority = _row_priorities(inside + start, seed)
        # Visible rows are contiguous in the compressed array.
        compressed = np.arange(position, position + inside.size)
        position += inside.size
        if best_priority.size:
            priority = np.concatenate([best_priority, priority])
            compressed = np.concatenate([best_position, compressed])
        if priority.size > max_points:
            cut = np.argpartition(priority, max_points - 1)[:max_points]
            priority, compressed = priority[cut], compressed[cut]
        best_priority, best_position = priority, compressed
    if best_position.size > max_points:
        cut = np.argpartition(best_priority, max_points - 1)[:max_points]
        best_position = best_position[cut]
    selection[best_position] = True
    return selection


_SCATTER_BRUSH_CACHE: dict = {}


def _scatter_brush(r: int, g: int, b: int, alpha: int = 200):
    """A shared QBrush for one colour (pyqtgraph caches one sprite per brush)."""
    key = (r, g, b, alpha)
    brush = _SCATTER_BRUSH_CACHE.get(key)
    if brush is None:
        import pyqtgraph as pg

        if len(_SCATTER_BRUSH_CACHE) > 4096:
            _SCATTER_BRUSH_CACHE.clear()
        brush = pg.mkBrush(r, g, b, alpha)
        _SCATTER_BRUSH_CACHE[key] = brush
    return brush


def _figure_image_layers(plot_dict: dict) -> list:
    """Return the normalized image colour layers of a plot dict.

    Each layer is ``{"parameter": str, "color": (r, g, b), "name": str}``.
    Legacy single-parameter image plots (``color_param``) are migrated in place.
    """
    layers = plot_dict.get("layers")
    if layers:
        out = []
        for layer in layers:
            if not layer or not layer.get("parameter"):
                continue
            param = layer.get("parameter")
            out.append({
                "parameter": param,
                "color": tuple(layer.get("color", (255, 255, 255))),
                "name": str(layer.get("name") or param),
                "visible": bool(layer.get("visible", True)),
                "min": layer.get("min"),
                "max": layer.get("max"),
            })
        return out
    param = plot_dict.get("color_param")
    if not param:
        return []
    color = plot_dict.get("image_color", (255, 255, 255))
    return [{
        "parameter": param,
        "color": tuple(color),
        "name": str(param),
        "visible": True,
        "min": plot_dict.get("image_min"),
        "max": plot_dict.get("image_max"),
    }]


def _is_scatter_plot(ptype: str) -> bool:
    """Whether a Figure plot type is scatter-like (plots x/y data points)."""
    return ptype in ("scatter", "image")


# --- Image plot: level-of-detail sample index (disk-cached) ----------------

_IMAGE_FINEST_CAP = 2_000_000   # most points in the finest precomputed level
_IMAGE_COARSEST = 4096          # stop coarsening once a level is this small
_IMAGE_POINT_CAP = 200_000      # most points drawn per frame


def _image_index_dir(parquet_path) -> Path:
    return Path(str(parquet_path) + ".imgidx")


def _image_geometry(parquet_path):
    """Return (xmin, xmax, ymin, ymax, total_rows, columns) for an image Parquet.

    x/y extents come from row-group statistics when present (no data is read);
    otherwise the x/y columns are streamed once to compute min/max.
    """
    import numpy as np
    import pyarrow.parquet as pq

    pf = pq.ParquetFile(parquet_path)
    names = list(pf.schema_arrow.names)
    total = int(pf.metadata.num_rows)

    def col_stat(col):
        idx = names.index(col)
        cmin = float("inf")
        cmax = float("-inf")
        found = False
        for rg in range(pf.metadata.num_row_groups):
            st = pf.metadata.row_group(rg).column(idx).statistics
            if (
                st is not None
                and getattr(st, "min", None) is not None
                and getattr(st, "max", None) is not None
            ):
                cmin = min(cmin, float(st.min))
                cmax = max(cmax, float(st.max))
                found = True
        if found:
            return cmin, cmax
        return None

    xs = col_stat("x")
    ys = col_stat("y")
    if xs is not None and ys is not None and total > 0:
        return xs[0], xs[1], ys[0], ys[1], total, names

    xmin = ymin = float("inf")
    xmax = ymax = float("-inf")
    for batch in pf.iter_batches(batch_size=1_000_000, columns=["x", "y"]):
        x = batch.column("x").to_numpy()
        y = batch.column("y").to_numpy()
        if x.size:
            xmin = min(xmin, float(np.nanmin(x)))
            xmax = max(xmax, float(np.nanmax(x)))
            ymin = min(ymin, float(np.nanmin(y)))
            ymax = max(ymax, float(np.nanmax(y)))
    if not np.isfinite(xmin):
        raise ValueError("image file has no x/y coordinates")
    return xmin, xmax, ymin, ymax, total, names


def _image_write_level(idx_dir, block, means2d):
    import numpy as np
    fname = f"level_{block}.npy"
    np.save(idx_dir / fname, means2d.astype(np.float32))
    return {"block": int(block), "file": fname}


def _build_image_index_files(parquet_path, progress_cb=None):
    """Build the multi-level raster pyramid for one image file (disk-cached).

    Each level is a 2D array `(H/b, W/b, C)` of per-block channel means (a
    downsampled image). The finest level's block size `b0` is chosen so the
    level fits _IMAGE_FINEST_CAP; coarser levels double the block via 2x2
    pooling. Only one level is materialised in memory at a time.
    """
    import json
    import math
    import numpy as np
    import pandas as pd
    import pyarrow.parquet as pq

    xmin, xmax, ymin, ymax, total, names = _image_geometry(parquet_path)
    # Store per-block means for every column (including x/y, so the user may
    # color the image by a coordinate too). The default color parameter is
    # still the first non-x/y column, chosen in _figure_add_plot.
    color_cols = list(names)
    width = xmax - xmin + 1.0
    height = ymax - ymin + 1.0
    if width < 1 or height < 1 or total == 0:
        raise ValueError("image file has no pixels")

    block = 1
    while True:
        nbx = int(math.ceil(width / block))
        nby = int(math.ceil(height / block))
        if nbx * nby <= _IMAGE_FINEST_CAP:
            break
        block *= 2
    b0 = block

    idx_dir = _image_index_dir(parquet_path)
    idx_dir.mkdir(parents=True, exist_ok=True)

    pf = pq.ParquetFile(parquet_path)
    ncol = len(color_cols)

    # Finest level: aggregate raw pixels into b0-sized blocks (single pass).
    nbx = int(math.ceil(width / b0))
    nby = int(math.ceil(height / b0))
    nblocks = nbx * nby
    cnt = np.zeros(nblocks, dtype=np.int64)
    sm = np.zeros((nblocks, ncol), dtype=np.float64)
    ch_min = np.full(ncol, np.inf)
    ch_max = np.full(ncol, -np.inf)
    processed = 0
    for batch in pf.iter_batches(batch_size=1_000_000, columns=names):
        tbl = batch.to_pandas()
        x = tbl["x"].to_numpy(dtype="float64")
        y = tbl["y"].to_numpy(dtype="float64")
        bi = ((x - xmin) // b0).astype(np.int64) + ((y - ymin) // b0).astype(np.int64) * nbx
        np.clip(bi, 0, nblocks - 1, out=bi)
        cnt += np.bincount(bi, minlength=nblocks)
        for j, cc in enumerate(color_cols):
            v = pd.to_numeric(tbl[cc], errors="coerce").to_numpy(dtype="float64")
            sm[:, j] += np.bincount(bi, weights=np.nan_to_num(v), minlength=nblocks)
            fin = np.isfinite(v)
            if fin.any():
                ch_min[j] = min(ch_min[j], float(v[fin].min()))
                ch_max[j] = max(ch_max[j], float(v[fin].max()))
        processed += x.size
        if progress_cb is not None:
            progress_cb(min(1.0, processed / total))

    means = (sm / np.maximum(cnt, 1)[:, None]).reshape(nby, nbx, ncol)
    levels = [_image_write_level(idx_dir, b0, means)]

    # Coarser levels by 2x2 count-weighted pooling of the previous level.
    prev = means
    prev_cnt = cnt.reshape(nby, nbx)
    prev_b = b0
    while prev_b < max(width, height):
        nb = prev_b * 2
        h, w = prev.shape[0], prev.shape[1]
        nbx2 = int(math.ceil(w / 2.0))
        nby2 = int(math.ceil(h / 2.0))
        ph, pw = nby2 * 2, nbx2 * 2
        pad_m = np.zeros((ph, pw, ncol), dtype=np.float64)
        pad_c = np.zeros((ph, pw), dtype=np.float64)
        pad_m[:h, :w] = prev * prev_cnt[:, :, None]
        pad_c[:h, :w] = prev_cnt
        sum_m = pad_m.reshape(nby2, 2, nbx2, 2, ncol).sum(axis=(1, 3))
        sum_c = pad_c.reshape(nby2, 2, nbx2, 2).sum(axis=(1, 3))
        prev = sum_m / np.maximum(sum_c, 1)[:, :, None]
        prev_cnt = sum_c
        levels.append(_image_write_level(idx_dir, nb, prev))
        prev_b = nb
        if nby2 * nbx2 <= _IMAGE_COARSEST:
            break

    color_ranges = {}
    for j, cc in enumerate(color_cols):
        color_ranges[cc] = [
            float(ch_min[j]) if np.isfinite(ch_min[j]) else 0.0,
            float(ch_max[j]) if np.isfinite(ch_max[j]) else 1.0,
        ]

    manifest = {
        "version": 2,
        "file_size": int(Path(parquet_path).stat().st_size),
        "file_mtime": float(Path(parquet_path).stat().st_mtime),
        "xmin": float(xmin),
        "xmax": float(xmax),
        "ymin": float(ymin),
        "ymax": float(ymax),
        "total": int(total),
        "color_cols": color_cols,
        "color_ranges": color_ranges,
        "levels": levels,
    }
    with open(idx_dir / "manifest.json", "w", encoding="utf-8") as fh:
        json.dump(manifest, fh)
    if progress_cb is not None:
        progress_cb(1.0)
    return manifest


def _row_mode(blocks):
    """Mode (most frequent value) of each row of an ``(N, k)`` integer array.

    Ties are broken toward the smallest value (a stable result independent of
    input order). Used to downsample a label image by taking each block's
    dominant label instead of its mean.
    """
    import warnings

    import numpy as np
    from scipy.stats import mode as _scipy_mode

    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        modes, _counts = _scipy_mode(blocks, axis=1, keepdims=False)
    return np.asarray(modes, dtype=blocks.dtype).reshape(blocks.shape[0])


def _mode_pool(arr2d, block):
    """Downsample a 2-D integer array by ``block``, returning the mode per block."""
    import math

    import numpy as np

    height, width = arr2d.shape
    nby = int(math.ceil(height / block))
    nbx = int(math.ceil(width / block))
    ph = nby * block
    pw = nbx * block
    padded = np.zeros((ph, pw), dtype=arr2d.dtype)
    padded[:height, :width] = arr2d
    blocks = (
        padded.reshape(nby, block, nbx, block)
        .transpose(0, 2, 1, 3)
        .reshape(nby * nbx, block * block)
    )
    return _row_mode(blocks).reshape(nby, nbx)


def _build_label_index(parquet_path, mask_2d, xmin, xmax, ymin, ymax):
    """Build a label (mode) raster pyramid for a mask parquet.

    Each level stores the per-block dominant label, so a zoomed-out view shows
    the most frequent cell in each block. The mask is a self-contained
    ``[x, y, mask]`` parquet; the pyramid lives in ``<parquet>.imgidx/`` with
    the same geometry as the source image.
    """
    import json
    import math

    import numpy as np

    idx_dir = _image_index_dir(parquet_path)
    idx_dir.mkdir(parents=True, exist_ok=True)
    height, width = mask_2d.shape
    geo_w = xmax - xmin + 1.0
    geo_h = ymax - ymin + 1.0

    block = 1
    while True:
        nbx = int(math.ceil(geo_w / block))
        nby = int(math.ceil(geo_h / block))
        if nbx * nby <= _IMAGE_FINEST_CAP:
            break
        block *= 2
    b0 = block

    levels = []
    level = _mode_pool(mask_2d, b0)
    fname = f"level_{b0}.npy"
    np.save(idx_dir / fname, level[..., None].astype(np.int32))
    levels.append({"block": int(b0), "file": fname})

    prev = level
    prev_b = b0
    while prev_b < max(geo_w, geo_h):
        nb = prev_b * 2
        nxt = _mode_pool(prev, 2)
        fname = f"level_{nb}.npy"
        np.save(idx_dir / fname, nxt[..., None].astype(np.int32))
        levels.append({"block": int(nb), "file": fname})
        prev = nxt
        prev_b = nb
        if (nxt.shape[0] * nxt.shape[1]) <= _IMAGE_COARSEST:
            break

    max_label = int(mask_2d.max()) if mask_2d.size else 0
    st = Path(parquet_path).stat()
    manifest = {
        "version": 2,
        "file_size": int(st.st_size),
        "file_mtime": float(st.st_mtime),
        "xmin": float(xmin),
        "xmax": float(xmax),
        "ymin": float(ymin),
        "ymax": float(ymax),
        "total": int(mask_2d.size),
        "color_cols": ["mask"],
        "color_ranges": {"mask": [0.0, float(max_label)]},
        "levels": levels,
        "kind": "label",
    }
    with open(idx_dir / "manifest.json", "w", encoding="utf-8") as fh:
        json.dump(manifest, fh)
    return manifest


def _image_load_level(parquet_path, info):
    import numpy as np
    return np.load(_image_index_dir(parquet_path) / info["file"])


def _pool_mask(mask, target_blocks):
    """Pool a (H, W) uint8 mask into {block: (nby, nbx) float32 pass-fraction}."""
    import numpy as np
    targets = sorted(int(b) for b in target_blocks)
    if not targets:
        return {}
    out = {}
    m = mask.astype(np.float64)
    c = np.ones(m.shape, dtype=np.float64)
    block = 1
    tset = set(targets)
    if block in tset:
        out[block] = (m / np.maximum(c, 1.0)).astype(np.float32)
    while block < targets[-1]:
        block *= 2
        h, w = m.shape
        nby = (h + 1) // 2
        nbx = (w + 1) // 2
        ph, pw = nby * 2, nbx * 2
        pm = np.zeros((ph, pw), dtype=np.float64)
        pc = np.zeros((ph, pw), dtype=np.float64)
        pm[:h, :w] = m
        pc[:h, :w] = c
        m = pm.reshape(nby, 2, nbx, 2).sum(axis=(1, 3))
        c = pc.reshape(nby, 2, nbx, 2).sum(axis=(1, 3))
        if block in tset:
            out[block] = (m / np.maximum(c, 1.0)).astype(np.float32)
    return out


def _illumination_stage_item(sub):
    """Convert one Illumination submodule into a pipeline stage entry."""
    import numpy as np

    channel = sub.get("channel")
    mask_data = sub.get("mask")
    if not channel or not mask_data:
        return None
    try:
        mask = np.asarray(mask_data, dtype="float64")
    except (TypeError, ValueError):
        return None
    if mask.ndim != 2 or mask.size == 0:
        return None
    finite = mask[np.isfinite(mask)]
    if finite.size == 0:
        return None
    method = sub.get("method", "median")
    if method == "down":
        threshold = float(finite.min())
    elif method == "up":
        threshold = float(finite.max())
    else:
        threshold = float(np.median(finite))
    return {
        "channel": channel,
        "x": sub.get("x"),
        "y": sub.get("y"),
        "files": set(sub.get("files") or []),
        "tile_w": int(sub.get("tile_w", 256)),
        "tile_h": int(sub.get("tile_h", 256)),
        "mask": mask,
        "T": threshold,
    }


class _FlowArrowBand(QWidget):
    """Narrow vertical strip with downward arrows (data-flow hint)."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setFixedWidth(22)

    def paintEvent(self, event) -> None:
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        pen = QPen(QColor("#9aa4b2"))
        pen.setWidthF(1.4)
        painter.setPen(pen)
        center = self.width() / 2.0
        y = 10
        while y + 13 < self.height():
            painter.drawLine(int(center), y, int(center), y + 9)
            painter.drawPolyline(QPolygonF([
                QPointF(center - 4, y + 8),
                QPointF(center, y + 13),
                QPointF(center + 4, y + 8),
            ]))
            y += 30
        painter.end()


class _ProcessWorker:
    """Background worker that runs one subprocess command to completion.

    Used to run external Python commands (venv creation, pip install, model
    download, verification and segmentation) without blocking the UI.
    """

    def __init__(self):
        self._req_q = queue.Queue()
        self._res_q = queue.Queue()
        self._stop = threading.Event()
        self._proc = None
        self._thread = threading.Thread(target=self._run, daemon=True)
        self._thread.start()

    def run(self, key, argv, cwd=None):
        self._req_q.put((key, list(argv), cwd))

    def poll(self):
        """Return finished events: ``(key, "line", text)`` for streaming output
        and ``(key, "done", returncode, text)`` when the command completes."""
        out = []
        while True:
            try:
                out.append(self._res_q.get_nowait())
            except queue.Empty:
                break
        return out

    def stop(self):
        self._stop.set()

    def clear(self):
        """Drop any unread results (e.g. from a previous, finished operation)."""
        while True:
            try:
                self._res_q.get_nowait()
            except queue.Empty:
                break

    def kill(self):
        """Terminate the in-flight subprocess (if any)."""
        proc = self._proc
        if proc is not None and proc.poll() is None:
            try:
                proc.kill()
            except Exception:  # noqa: BLE001
                pass

    def _run(self):
        import subprocess

        while not self._stop.is_set():
            try:
                key, argv, cwd = self._req_q.get(timeout=0.2)
            except queue.Empty:
                continue
            try:
                proc = subprocess.Popen(
                    argv,
                    cwd=cwd,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT,
                    text=True,
                    encoding="utf-8",
                    errors="replace",
                    bufsize=1,
                    # Run without a console window (the external python is a
                    # console app; this hides the flash that would otherwise
                    # pop up on Windows).
                    creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                )
                self._proc = proc
                chunks = []
                for line in proc.stdout:
                    line = line.rstrip("\r\n")
                    if line:
                        chunks.append(line)
                        self._res_q.put((key, "line", line))
                proc.wait()
                self._res_q.put(
                    (key, "done", int(proc.returncode), "\n".join(chunks))
                )
            except Exception as exc:  # noqa: BLE001
                self._res_q.put((key, "done", -1, str(exc)))
            finally:
                self._proc = None


class _ExtManagerDialog(QDialog):
    """Extension Manager dialog that warns before closing mid-operation."""

    def __init__(self, parent, busy_check) -> None:
        super().__init__(parent)
        self._busy_check = busy_check

    def closeEvent(self, event) -> None:
        if self._busy_check():
            reply = QMessageBox.question(
                self,
                "Operation in progress",
                "An installation is still running.\n"
                "Closing now will interrupt it and may leave the environment "
                "incomplete. Really close?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                event.ignore()
                return
        # Reject (not just accept) so the `finished` signal fires, which stops
        # the poll timer. Otherwise the timer keeps draining the shared worker
        # queue and steals results from other consumers (e.g. segmentation).
        self.reject()
        event.accept()


class _IlluminationWorker:
    """Background worker that estimates an illumination mask from tiles."""

    def __init__(self):
        self._req_q = queue.Queue()
        self._res_q = queue.Queue()
        self._stop = threading.Event()
        self._thread = threading.Thread(target=self._run, daemon=True)
        self._thread.start()

    def request(self, key, stages, base_columns, files, channel, x_name,
                y_name, tile_w, tile_h, bins, resolution):
        self._req_q.put((
            key, stages, base_columns, list(files), channel, x_name, y_name,
            int(tile_w), int(tile_h), int(bins), int(resolution),
        ))

    def poll(self):
        out = []
        while True:
            try:
                out.append(self._res_q.get_nowait())
            except queue.Empty:
                break
        return out

    def stop(self):
        self._stop.set()

    def _run(self):
        while not self._stop.is_set():
            try:
                req = self._req_q.get(timeout=0.2)
            except queue.Empty:
                continue
            try:
                res = self._compute(*req)
            except Exception as exc:  # noqa: BLE001
                res = (req[0], None, f"Could not calculate the mask: {exc}")
            self._res_q.put(res)

    def _compute(self, key, stages, base_columns, files, channel, x_name,
                 y_name, tile_w, tile_h, bins, resolution):
        import numpy as np
        import pandas as pd
        from scipy.interpolate import RectBivariateSpline, griddata

        if not files:
            return (key, None, "No files selected for the calculation.")
        n_blocks = bins * bins
        sums = np.zeros(n_blocks, dtype="float64")
        counts = np.zeros(n_blocks, dtype="float64")
        used_files = 0
        for path in files:
            needed = {x_name, y_name, channel}
            dependencies = _pipeline_dependencies(stages, needed, path)
            base = base_columns.get(path) or set()
            if not base:
                try:
                    import pyarrow.parquet as pq
                    base = set(pq.ParquetFile(path).schema.names)
                except Exception:  # noqa: BLE001
                    continue
            base = [c for c in dependencies if c in base]
            values = {}
            if base:
                try:
                    df = pd.read_parquet(path, columns=base)
                except Exception:  # noqa: BLE001
                    continue
                for name in base:
                    values[name] = pd.to_numeric(
                        df[name], errors="coerce"
                    ).to_numpy(dtype="float64")
            values = _evaluate_stages(stages, values, needed, path)
            if not all(name in values for name in needed):
                continue
            x = np.asarray(values[x_name], dtype="float64")
            y = np.asarray(values[y_name], dtype="float64")
            v = np.asarray(values[channel], dtype="float64")
            finite = np.isfinite(x) & np.isfinite(y) & np.isfinite(v)
            x, y, v = x[finite], y[finite], v[finite]
            if v.size == 0:
                continue
            x0 = float(x.min())
            y0 = float(y.min())
            width = float(x.max() - x0) + 1.0
            height = float(y.max() - y0) + 1.0
            ntx = int(width // tile_w)
            nty = int(height // tile_h)
            if ntx < 1 or nty < 1:
                continue
            ti = np.floor((x - x0) / tile_w).astype(np.int64)
            tj = np.floor((y - y0) / tile_h).astype(np.int64)
            keep = (ti >= 0) & (ti < ntx) & (tj >= 0) & (tj < nty)
            if not keep.any():
                continue
            x, y, v = x[keep], y[keep], v[keep]
            ti, tj = ti[keep], tj[keep]
            tile_id = tj * ntx + ti
            wx = (x - x0) - ti * tile_w
            wy = (y - y0) - tj * tile_h
            bx = np.clip((wx * bins / tile_w).astype(np.int64), 0, bins - 1)
            by = np.clip((wy * bins / tile_h).astype(np.int64), 0, bins - 1)
            block = by * bins + bx
            frame = pd.DataFrame({"tile": tile_id, "block": block, "v": v})
            # 10th percentile threshold per tile; darker points are background.
            thresholds = frame.groupby("tile")["v"].quantile(0.1)
            frame["thr"] = frame["tile"].map(thresholds)
            frame = frame[frame["v"] >= frame["thr"]]
            if frame.empty:
                continue
            # Median per block within each tile, then mean over tiles.
            medians = frame.groupby(["tile", "block"])["v"].median()
            per_block = medians.groupby(level="block").mean()
            indices = per_block.index.to_numpy(dtype=np.int64)
            sums[indices] += per_block.to_numpy()
            counts[indices] += 1.0
            used_files += 1

        if used_files == 0 or not (counts > 0).any():
            return (key, None, "No tile data was found for the selected parameters.")

        grid = np.full(n_blocks, np.nan)
        valid = counts > 0
        grid[valid] = sums[valid] / counts[valid]
        grid = grid.reshape(bins, bins)

        # Smooth the bin x bin fields to resolution x resolution, then to a
        # full tile-sized mask.
        gy, gx = np.mgrid[0:bins, 0:bins]
        flat_valid = valid.reshape(-1)
        points = np.column_stack([gx.ravel()[flat_valid],
                                  gy.ravel()[flat_valid]])
        values_grid = grid.reshape(-1)[flat_valid]
        target_x = np.linspace(0, bins - 1, resolution)
        target_y = np.linspace(0, bins - 1, resolution)
        tx, ty = np.meshgrid(target_x, target_y)
        smooth = griddata(points, values_grid, (tx, ty), method="linear")
        if np.isnan(smooth).any():
            nearest = griddata(points, values_grid, (tx, ty), method="nearest")
            smooth = np.where(np.isnan(smooth), nearest, smooth)
        spline = RectBivariateSpline(
            np.arange(resolution), np.arange(resolution), smooth, kx=1, ky=1
        )
        mask = spline(
            np.linspace(0, resolution - 1, tile_h),
            np.linspace(0, resolution - 1, tile_w),
        )
        mask = np.asarray(mask, dtype="float64")
        if mask.shape != (tile_h, tile_w):
            return (key, None, "Could not build the mask at the requested size.")
        return (key, {
            "mask": mask.tolist(),
            "tile_w": int(tile_w),
            "tile_h": int(tile_h),
            "bin": int(bins),
            "resolution": int(resolution),
            "files": list(files),
        }, None)


class _ImageFilterWorker:
    """Background worker that computes gate-filter masks for Image plots."""

    def __init__(self):
        self._req_q = queue.Queue()
        self._res_q = queue.Queue()
        self._stop = threading.Event()
        self._thread = threading.Thread(target=self._run, daemon=True)
        self._thread.start()

    def request(self, key, parquet_path, gates, gate_id, stages, base_columns,
                height, width, blocks):
        self._req_q.put((
            key, parquet_path, gates, gate_id, stages, set(base_columns),
            height, width, blocks,
        ))

    def poll(self):
        out = []
        while True:
            try:
                out.append(self._res_q.get_nowait())
            except queue.Empty:
                break
        return out

    def stop(self):
        self._stop.set()

    def _run(self):
        while not self._stop.is_set():
            try:
                req = self._req_q.get(timeout=0.2)
            except queue.Empty:
                continue
            try:
                res = self._compute(*req)
            except Exception as exc:  # noqa: BLE001
                res = (req[0], f"Filter could not be applied: {exc}")
            self._res_q.put(res)

    def _compute(self, key, parquet_path, gates, gate_id, stages, base_columns,
                 height, width, blocks):
        import numpy as np
        import pandas as pd
        by_id = {g["id"]: g for g in gates}
        needed = set()
        for g in gates:
            needed |= _gate_needed_columns(g, by_id)
        dependencies = _pipeline_dependencies(stages, needed, parquet_path)
        base = [c for c in dependencies if c in base_columns]
        values = {}
        if base:
            try:
                df = pd.read_parquet(parquet_path, columns=base)
            except Exception as exc:  # noqa: BLE001
                return (key, f"Filter could not be applied: {exc}")
            for name in base:
                values[name] = pd.to_numeric(
                    df[name], errors="coerce"
                ).to_numpy(dtype="float64")
        values = _evaluate_stages(stages, values, needed, parquet_path)
        try:
            mask = _compute_gate_filter_mask(
                gates, gate_id, parquet_path, {},
                existing=set(values), extra=values,
            )
        except KeyError as exc:
            return (key, f"Filter parameter not found: {exc}")
        except Exception as exc:  # noqa: BLE001
            return (key, f"Filter could not be applied: {exc}")
        if mask is None:
            return (key, "Filter could not be computed (gate has no usable parameters)")
        mask = np.asarray(mask, dtype=np.uint8)
        total = int(height) * int(width)
        if mask.size != total:
            return (key, f"Filter mask size mismatch ({mask.size} vs {total})")
        mask_2d = mask.reshape(int(height), int(width))
        levels = _pool_mask(mask_2d, blocks)
        return (key, {"mask_2d": mask_2d, "levels": levels})


_SUPERSCRIPT = str.maketrans("0123456789-", "⁰¹²³⁴⁵⁶⁷⁸⁹⁻")


def _format_sci(value: float) -> str:
    """Mantissa×10^exponent (superscript); a mantissa of 1 is left out.

    The mantissa is an integer when it is whole and otherwise has one decimal
    ("2×10³", "1.5×10³", "10³" for 1000).
    """
    import math

    try:
        value = float(value)
    except (TypeError, ValueError):
        return str(value)
    if not math.isfinite(value):
        return str(value)
    if value == 0:
        return "0"
    sign = "-" if value < 0 else ""
    magnitude = abs(value)
    exponent = int(math.floor(math.log10(magnitude)))
    mantissa = round(magnitude / (10 ** exponent), 1)
    if mantissa >= 10:  # 9.96 rounds to 10
        mantissa /= 10
        exponent += 1
    text = str(int(mantissa)) if float(mantissa).is_integer() else f"{mantissa:.1f}"
    superscript = str(exponent).translate(_SUPERSCRIPT)
    if text == "1":
        return f"{sign}10{superscript}"
    return f"{sign}{text}×10{superscript}"


def _make_sci_axis(orientation: str):
    """Return an axis item with scientific-notation, outward (non-crossing) ticks."""
    import pyqtgraph as pg

    class _SciAxis(pg.AxisItem):
        def tickStrings(self, values, scale, spacing):
            return [_format_sci(v * scale) for v in values]

        def generateDrawSpecs(self, p):
            specs = super().generateDrawSpecs(p)
            if specs is None:
                return specs
            axisSpec, tickSpecs, textSpecs = specs
            # Anchor each tick at the spine so it points outward without crossing,
            # and draw the ticks a little heavier than the axis line.
            tick_pen = pg.mkPen("#000000", width=2)
            if self.orientation in ("left", "right"):
                spine = axisSpec[1].x()
                tickSpecs = [(tick_pen, pg.Point(spine, p1.y()), p2)
                             for _pen, p1, p2 in tickSpecs]
            else:
                spine = axisSpec[1].y()
                tickSpecs = [(tick_pen, pg.Point(p1.x(), spine), p2)
                             for _pen, p1, p2 in tickSpecs]
            return axisSpec, tickSpecs, textSpecs

    ax = _SciAxis(orientation)
    ax.setStyle(tickLength=5)  # positive -> outward
    # Axis line, ticks and tick labels in black.
    ax.setPen(pg.mkPen("#000000", width=2))
    ax.setTextPen(pg.mkPen("#000000"))
    return ax


def _make_fixed_axis(orientation: str, decimals: int = 1):
    """Return an axis whose tick labels use plain decimals (no 1e+03 forms)."""
    import pyqtgraph as pg

    class _FixedAxis(pg.AxisItem):
        def tickStrings(self, values, scale, spacing):
            out = []
            for value in values:
                scaled = value * scale
                if scaled == 0:
                    scaled = 0.0  # avoid "-0.0"
                out.append(f"{scaled:.{decimals}f}")
            return out

        def generateDrawSpecs(self, p):
            specs = super().generateDrawSpecs(p)
            if specs is None:
                return specs
            axisSpec, tickSpecs, textSpecs = specs
            tick_pen = pg.mkPen("#000000", width=2)
            if self.orientation in ("left", "right"):
                spine = axisSpec[1].x()
                tickSpecs = [(tick_pen, pg.Point(spine, p1.y()), p2)
                             for _pen, p1, p2 in tickSpecs]
            else:
                spine = axisSpec[1].y()
                tickSpecs = [(tick_pen, pg.Point(p1.x(), spine), p2)
                             for _pen, p1, p2 in tickSpecs]
            return axisSpec, tickSpecs, textSpecs

    ax = _FixedAxis(orientation)
    ax.setStyle(tickLength=5)
    ax.setPen(pg.mkPen("#000000", width=2))
    ax.setTextPen(pg.mkPen("#000000"))
    return ax


def _make_rotated_axis(orientation: str = "bottom"):
    """Return an axis whose tick labels are rotated 90° (long names)."""
    import pyqtgraph as pg

    class _RotatedAxis(pg.AxisItem):
        def generateDrawSpecs(self, p):
            specs = super().generateDrawSpecs(p)
            if specs is None:
                return specs
            axisSpec, tickSpecs, textSpecs = specs
            tick_pen = pg.mkPen("#000000", width=2)
            tickSpecs = [(tick_pen, p1, p2) for _pen, p1, p2 in tickSpecs]
            return axisSpec, tickSpecs, textSpecs

        def drawPicture(self, p, axisSpec, tickSpecs, textSpecs):
            p.setRenderHint(p.RenderHint.Antialiasing, False)
            p.setRenderHint(p.RenderHint.TextAntialiasing, True)
            pen, p1, p2 = axisSpec
            p.setPen(pen)
            p.drawLine(p1, p2)
            for pen, p1, p2 in tickSpecs:
                p.setPen(pen)
                p.drawLine(p1, p2)
            if self.style['tickFont'] is not None:
                p.setFont(self.style['tickFont'])
            p.setPen(self.textPen())
            p.setClipRect(self.boundingRect().toAlignedRect())
            fm = p.fontMetrics()
            shift = (fm.ascent() - fm.descent()) / 2.0
            for rect, _flags, text in textSpecs:
                p.save()
                # Rotate counter-clockwise (-90°): the label reads bottom-to-top
                # and hangs below the axis, centred on its tick.
                p.translate(
                    rect.center().x() + shift,
                    rect.top() + rect.width(),
                )
                p.rotate(-90)
                p.drawText(QPointF(0, 0), text)
                p.restore()

    ax = _RotatedAxis(orientation)
    ax.setStyle(tickLength=5)
    ax.setPen(pg.mkPen("#000000", width=2))
    ax.setTextPen(pg.mkPen("#000000"))
    return ax


def _letter_pixmap(text: str, size: int = 14) -> QPixmap:
    """Build a small pixmap with a letter (for plot corner buttons)."""
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.GlobalColor.transparent)
    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    painter.setPen(QColor("#666666"))
    font = painter.font()
    font.setPixelSize(10)
    font.setBold(True)
    painter.setFont(font)
    painter.drawText(pixmap.rect(), Qt.AlignmentFlag.AlignCenter, text)
    painter.end()
    return pixmap


def _triangle_icon(direction: str) -> QIcon:
    """A filled triangle pointing 'up' or 'down'."""
    pm = QPixmap(16, 16)
    pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor("#37474f"))
    if direction == "up":
        pts = [QPointF(8, 3), QPointF(3, 13), QPointF(13, 13)]
    else:
        pts = [QPointF(8, 13), QPointF(3, 3), QPointF(13, 3)]
    p.drawPolygon(QPolygonF(pts))
    p.end()
    return QIcon(pm)


def _gate_tool_icon(key: str) -> QIcon:
    """Build a small shape icon for a gating tool button."""
    pm = QPixmap(22, 22)
    pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    pen = QPen(QColor("#37474f"))
    pen.setWidthF(1.7)
    p.setPen(pen)
    p.setBrush(Qt.BrushStyle.NoBrush)
    m = 3.0
    r = QRectF(m, m, 22 - 2 * m, 22 - 2 * m)
    cx, cy = 11.0, 11.0
    if key == "rect":
        p.drawRect(r)
    elif key == "ellipse":
        p.drawEllipse(r)
    elif key == "polygon":
        pts = [
            QPointF(5, 15), QPointF(8, 7), QPointF(15, 5),
            QPointF(18, 11), QPointF(14, 17), QPointF(9, 16),
        ]
        p.drawPolygon(QPolygonF(pts))
    elif key == "quadrant":
        p.drawLine(QPointF(cx, m), QPointF(cx, 22 - m))
        p.drawLine(QPointF(m, cy), QPointF(22 - m, cy))
    elif key == "skewed_quadrant":
        p.drawLine(QPointF(cx, cy), QPointF(m, cy))       # left
        p.drawLine(QPointF(cx, cy), QPointF(22 - m, cy))  # right
        p.drawLine(QPointF(cx, cy), QPointF(cx, 22 - m))  # down
        p.drawLine(QPointF(cx, cy), QPointF(cx + 5, m))   # up, tilted right
    elif key == "split":
        p.drawLine(QPointF(cx, m), QPointF(cx, 22 - m))
    elif key == "range":
        p.drawLine(QPointF(cx - 5, m), QPointF(cx - 5, 22 - m))
        p.drawLine(QPointF(cx + 5, m), QPointF(cx + 5, 22 - m))
    p.end()
    return QIcon(pm)


def _make_fit_plot_item(viewbox=None):
    """Return a PlotItem with an extra "F" button (fit to full data)."""
    import pyqtgraph as pg

    class _FitPlotItem(pg.PlotItem):
        def __init__(self):
            super().__init__(viewBox=viewbox)
            self._on_fit = None
            self.fitBtn = pg.ButtonItem(_letter_pixmap("F"), 14, self)
            self.fitBtn.clicked.connect(lambda _=None: self._fit_clicked())

        def _fit_clicked(self):
            if self._on_fit is not None:
                self._on_fit()

        def resizeEvent(self, ev):
            super().resizeEvent(ev)
            w = self.autoBtn.boundingRect().width()
            y = self.size().height() - self.fitBtn.boundingRect().height()
            self.fitBtn.setPos(w + 2, y)

    return _FitPlotItem()


_GATE_PEN = "#000000"
_GATE_HOVER_PEN = "#444444"
_GATE_COLOR_DEFAULT = "#000000"
_POLY_CLOSE_RADIUS = 12  # pixels: click this close to the first anchor to close


def _gate_color(preview) -> str:
    """The user's gate drawing colour (defaults to black)."""
    color = (preview or {}).get("gate_color")
    return color if isinstance(color, str) and color else _GATE_COLOR_DEFAULT


def _gate_hover_color(color: str) -> str:
    """A shifted shade of `color` used when the cursor is over a gate."""
    qcolor = QColor(color)
    if not qcolor.isValid():
        return _GATE_HOVER_PEN
    if qcolor.lightness() > 128:
        return qcolor.darker(150).name()
    return qcolor.lighter(170).name()


def _gate_roi_pens(color: str | None = None) -> dict:
    """Pens for a gate ROI: the gate colour, a shifted shade on hover."""
    base = color or _GATE_COLOR_DEFAULT
    hover = _gate_hover_color(base)
    return dict(
        pen=pg.mkPen(base, width=2),
        hoverPen=pg.mkPen(hover, width=3),
        handlePen=pg.mkPen(base, width=1),
        handleHoverPen=pg.mkPen(hover, width=2),
    )


class _NoClickScatter(pg.ScatterPlotItem):
    """Scatter points that never consume mouse clicks.

    pyqtgraph delivers clicks to the topmost item that handles them, so a
    scatter point under the cursor would otherwise swallow the click that
    starts single-click gating tools (quadrant, split, range, polygon).
    """

    def mouseClickEvent(self, ev) -> None:
        ev.ignore()


class _GateViewBox(pg.ViewBox):
    """Scatter ViewBox that draws gate ROIs (rectangle / ellipse / polygon)."""

    def __init__(self, on_gate_created, on_empty_click=None, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._on_gate_created = on_gate_created
        self._on_empty_click = on_empty_click
        # Colour used while drawing gates (kept in sync with the settings).
        self.gate_color = _GATE_COLOR_DEFAULT
        self._tool = None  # "rect" | "ellipse" | "polygon" | ...
        self._start = None
        self._preview = None
        self._rubber = None
        self._first_highlight = None
        self._polygon_pts = []
        self._range_x1 = None
        self._range_y1 = None
        self._range_anchor = None
        self._range_band = None
        self._range_arrow = None

    def set_gate_tool(self, tool) -> None:
        self._cancel_preview()
        self._tool = tool
        self._polygon_pts = []
        self._range_x1 = None

    def _cancel_preview(self) -> None:
        if self._preview is not None:
            self.removeItem(self._preview)
            self._preview = None
        if self._rubber is not None:
            self.removeItem(self._rubber)
            self._rubber = None
        if self._first_highlight is not None:
            self.removeItem(self._first_highlight)
            self._first_highlight = None
        if self._range_anchor is not None:
            self.removeItem(self._range_anchor)
            self._range_anchor = None
        if self._range_band is not None:
            self.removeItem(self._range_band)
            self._range_band = None
        if self._range_arrow is not None:
            self.removeItem(self._range_arrow)
            self._range_arrow = None
        self._start = None
        self._polygon_pts = []
        self._range_x1 = None
        self._range_y1 = None

    def _pt(self, ev):
        return self.mapSceneToView(ev.scenePos())

    # -- rectangle / ellipse (click-drag) -----------------------------------
    def mouseDragEvent(self, ev, axis=None) -> None:
        if self._tool in ("rect", "ellipse"):
            if self._preview is None:
                start = self.mapSceneToView(ev.buttonDownScenePos())
                self._start = start
                self._preview = self._make_shape(self._tool, (start.x(), start.y()), (0.0, 0.0))
                self.addItem(self._preview)
            p = self._pt(ev)
            x0, y0 = self._start.x(), self._start.y()
            x1, y1 = p.x(), p.y()
            pos = (min(x0, x1), min(y0, y1))
            size = (abs(x1 - x0), abs(y1 - y0))
            self._preview.setPos(pos)
            self._preview.setSize(size)
            if ev.isFinish():
                roi = self._preview
                self._preview = None
                self._start = None
                if roi.size().x() > 0 and roi.size().y() > 0:
                    self._on_gate_created(self._tool, roi)
                else:
                    self.removeItem(roi)
            ev.accept()
            return
        super().mouseDragEvent(ev, axis)

    # -- polygon / quadrant / split / range / skewed-quadrant ----------------
    def mouseClickEvent(self, ev) -> None:
        if self._tool == "polygon" and ev.button() == Qt.MouseButton.RightButton:
            self._finish_polygon()
            ev.accept()
            return
        if ev.button() != Qt.MouseButton.LeftButton:
            super().mouseClickEvent(ev)
            return
        p = self._pt(ev)
        if self._tool == "polygon":
            if len(self._polygon_pts) >= 3 and self._near_first_anchor(p):
                self._finish_polygon()
            else:
                self._polygon_pts.append((p.x(), p.y()))
                self._update_polygon_preview()
            ev.accept()
            return
        if self._tool == "quadrant":
            self._on_gate_created("quadrant", (p.x(), p.y()))
            ev.accept()
            return
        if self._tool == "split":
            self._on_gate_created("split", (p.x(), p.y()))
            ev.accept()
            return
        if self._tool == "range":
            if self._range_x1 is None:
                self._range_x1 = p.x()
                self._range_y1 = p.y()
                self._update_range_preview((p.x(), p.y()))
            else:
                self._on_gate_created("range", (self._range_x1, p.x()))
            ev.accept()
            return
        if self._tool == "skewed_quadrant":
            import math
            cx, cy = p.x(), p.y()
            xr, yr = self.viewRange()
            dx = (xr[1] - xr[0]) / 4.0
            dy = (yr[1] - yr[0]) / 4.0
            p_right = (cx + dx, cy)
            p_left = (cx - dx, cy)
            p_down = (cx, cy - dy)
            # The top point is tilted 30 degrees to the right of vertical.
            p_up = (cx + dy * math.sin(math.radians(30)), cy + dy * math.cos(math.radians(30)))
            self._on_gate_created(
                "skewed_quadrant",
                ((cx, cy), p_right, p_up, p_left, p_down),
            )
            ev.accept()
            return
        if self._on_empty_click is not None:
            self._on_empty_click()
        super().mouseClickEvent(ev)

    def _near_first_anchor(self, p) -> bool:
        """True when the cursor is within a few pixels of the polygon's first anchor."""
        if not self._polygon_pts:
            return False
        first = pg.Point(self._polygon_pts[0][0], self._polygon_pts[0][1])
        f_dev = self.mapViewToDevice(first)
        p_dev = self.mapViewToDevice(p)
        dx = p_dev.x() - f_dev.x()
        dy = p_dev.y() - f_dev.y()
        return dx * dx + dy * dy <= _POLY_CLOSE_RADIUS * _POLY_CLOSE_RADIUS

    def _update_range_preview(self, mouse_pos=None) -> None:
        if self._range_x1 is None:
            return
        if self._range_anchor is None:
            self._range_anchor = pg.InfiniteLine(
                pos=self._range_x1, angle=90, movable=False,
                pen=pg.mkPen(self.gate_color, width=2, style=Qt.PenStyle.DashLine),
            )
            self.addItem(self._range_anchor)
        if self._range_band is None:
            self._range_band = self._make_preview_item(
                pen=pg.mkPen(self.gate_color, width=2, style=Qt.PenStyle.DashLine),
            )
            self.addItem(self._range_band)
        if self._range_arrow is None:
            self._range_arrow = pg.ArrowItem(
                angle=0, headLen=10, tipAngle=30, tailLen=None,
                brush=pg.mkBrush(self.gate_color), pen=None, pxMode=True,
            )
            self.addItem(self._range_arrow)
        x0, y0 = self._range_x1, self._range_y1
        if mouse_pos is not None:
            self._range_band.setData([x0, mouse_pos[0]], [y0, mouse_pos[1]])
            s_dev = self.mapViewToDevice(pg.Point(x0, y0))
            m_dev = self.mapViewToDevice(pg.Point(mouse_pos[0], mouse_pos[1]))
            dx = m_dev.x() - s_dev.x()
            dy = m_dev.y() - s_dev.y()
            ang = math.degrees(math.atan2(dy, dx)) + 180.0
            self._range_arrow.setStyle(angle=ang)
            self._range_arrow.setPos(mouse_pos[0], mouse_pos[1])
            self._range_arrow.setVisible(True)
        else:
            self._range_band.setData([x0], [y0])
            self._range_arrow.setVisible(False)

    def _finish_polygon(self) -> None:
        pts = self._polygon_pts
        if len(pts) >= 3:
            self._polygon_pts = []
            if self._preview is not None:
                self.removeItem(self._preview)
                self._preview = None
            if self._rubber is not None:
                self.removeItem(self._rubber)
                self._rubber = None
            if self._first_highlight is not None:
                self.removeItem(self._first_highlight)
                self._first_highlight = None
            roi = _GatePolygonROI(
                pts, closed=True, **_gate_roi_pens(self.gate_color)
            )
            self.addItem(roi)
            self._on_gate_created("polygon", roi)
        else:
            self._cancel_preview()

    def hoverEvent(self, ev) -> None:
        if self._tool == "polygon":
            mouse_pos = None
            if not ev.isExit() and self._polygon_pts:
                p = self.mapSceneToView(ev.scenePos())
                mouse_pos = (p.x(), p.y())
            self._update_polygon_preview(mouse_pos)
        elif self._tool == "range":
            mouse_pos = None
            if not ev.isExit() and self._range_x1 is not None:
                p = self.mapSceneToView(ev.scenePos())
                mouse_pos = (p.x(), p.y())
            self._update_range_preview(mouse_pos)

    def _make_preview_item(self, **kwargs) -> pg.PlotDataItem:
        """A visual-only PlotDataItem that never swallows mouse events."""
        item = pg.PlotDataItem(**kwargs)
        item.setEnabled(False)
        item.setAcceptedMouseButtons(Qt.MouseButton.NoButton)
        item.scatter.setEnabled(False)
        item.curve.setEnabled(False)
        return item

    def _ensure_polygon_items(self) -> None:
        if self._preview is None:
            self._preview = self._make_preview_item(
                pen=pg.mkPen(self.gate_color, width=2),
                symbol="o", symbolSize=9, symbolBrush=self.gate_color,
            )
            self.addItem(self._preview)
        if self._rubber is None:
            self._rubber = self._make_preview_item(
                pen=pg.mkPen(self.gate_color, width=1, style=Qt.PenStyle.DashLine),
            )
            self.addItem(self._rubber)
        if self._first_highlight is None:
            self._first_highlight = self._make_preview_item(
                pen=None,
                symbol="o", symbolSize=15,
                symbolPen=pg.mkPen(_gate_hover_color(self.gate_color), width=2.5),
                symbolBrush=pg.mkBrush(None),
            )
            self.addItem(self._first_highlight)

    def _update_polygon_preview(self, mouse_pos=None) -> None:
        pts = self._polygon_pts
        if not pts:
            if self._preview is not None:
                self._preview.setData([], [])
            if self._rubber is not None:
                self._rubber.setData([], [])
            if self._first_highlight is not None:
                self._first_highlight.setData([], [])
            return
        self._ensure_polygon_items()
        self._preview.setData([p[0] for p in pts], [p[1] for p in pts])
        # Highlight the first anchor when the cursor is close enough to close.
        near_first = (
            len(pts) >= 3
            and mouse_pos is not None
            and self._near_first_anchor(pg.Point(mouse_pos[0], mouse_pos[1]))
        )
        if near_first:
            self._first_highlight.setData([pts[0][0]], [pts[0][1]])
        else:
            self._first_highlight.setData([], [])
        if mouse_pos is not None:
            last = pts[-1]
            self._rubber.setData([last[0], mouse_pos[0]], [last[1], mouse_pos[1]])
        else:
            self._rubber.setData([], [])

    def _make_shape(self, tool, pos, size):
        if tool == "ellipse":
            return pg.EllipseROI(pos, size, **_gate_roi_pens(self.gate_color))
        return pg.RectROI(pos, size, **_gate_roi_pens(self.gate_color))


class _GatePolygonROI(pg.PolyLineROI):
    """Polygon gate ROI whose vertices are edited via a right-click menu only."""

    def __init__(self, positions, **kwargs):
        super().__init__(positions, **kwargs)
        self._click_pos = None
        self._menu = None
        self._fix_editing_mode()

    def _fix_editing_mode(self) -> None:
        # Don't insert a vertex when a segment is clicked; don't show the
        # per-handle "remove" button. Both are handled by the context menu.
        # Instead, an edge click selects the polygon.
        for seg in self.segments:
            try:
                seg.sigClicked.disconnect(self.segmentClicked)
            except (TypeError, RuntimeError):
                pass
            try:
                seg.sigClicked.disconnect(self._edge_clicked)
            except (TypeError, RuntimeError):
                pass
            seg.sigClicked.connect(self._edge_clicked)
        for h in self.handles:
            h["item"].setDeletable(False)

    def _edge_clicked(self, segment, ev=None) -> None:
        # Forward an edge click to the polygon's own click signal.
        self.sigClicked.emit(self, ev)

    def hoverEvent(self, ev) -> None:
        # Highlight the whole polygon, not just the hovered edge.
        self.setMouseHover(not ev.isExit())
        if not ev.isExit():
            ev.acceptDrags(Qt.MouseButton.LeftButton)

    def addSegment(self, h1, h2, index=None):
        super().addSegment(h1, h2, index=index)
        self._fix_editing_mode()

    def mouseClickEvent(self, ev) -> None:
        if ev.button() == Qt.MouseButton.RightButton:
            self._click_pos = ev.pos()
            self._menu = self.getMenu()
            self._menu.popup(ev.screenPos().toPoint())
            ev.accept()
            return
        super().mouseClickEvent(ev)

    def getMenu(self):
        menu = QMenu()
        menu.setTitle("Polygon")
        add_act = QAction("Add point", menu)
        add_act.triggered.connect(self._add_point_clicked)
        menu.addAction(add_act)
        rem_act = QAction("Remove point", menu)
        rem_act.triggered.connect(self._remove_point_clicked)
        menu.addAction(rem_act)
        return menu

    def _add_point_clicked(self) -> None:
        if self._click_pos is None:
            return
        seg = self._nearest_segment(self._click_pos)
        if seg is not None:
            self.segmentClicked(seg, pos=self._click_pos)

    def _remove_point_clicked(self) -> None:
        if self._click_pos is None or len(self.handles) <= 3:
            return
        handle = self._nearest_handle(self._click_pos)
        if handle is not None:
            self.removeHandle(handle)

    def _nearest_segment(self, pos):
        best, best_d = None, None
        for seg in self.segments:
            h0 = seg.handles[0]["item"].pos()
            h1 = seg.handles[1]["item"].pos()
            mid = h0 + (h1 - h0) / 2
            d = (mid - pos).length()
            if best_d is None or d < best_d:
                best_d, best = d, seg
        return best

    def _nearest_handle(self, pos):
        best, best_d = None, None
        for h in self.handles:
            hp = h["item"].pos()
            d = (hp - pos).length()
            if best_d is None or d < best_d:
                best_d, best = d, h["item"]
        return best


class _SkewedQuadrantROI(pg.ROI):
    """A bent crosshair: 5 draggable points (center + 4 arms) joined by rays."""

    def __init__(self, center, p_right, p_up, p_left, p_down, **args):
        super().__init__([0, 0], [1, 1], removable=False, **args)
        self.addFreeHandle(center)
        self.addFreeHandle(p_right)
        self.addFreeHandle(p_up)
        self.addFreeHandle(p_left)
        self.addFreeHandle(p_down)
        self._bounds = None

    def _handles(self):
        return [h.pos() for h in self.getHandles()]

    def viewTransformChanged(self):
        # Ray endpoints depend on the visible range; recompute on pan/zoom.
        self._bounds = None
        super().viewTransformChanged()

    def boundingRect(self):
        if self._bounds is None:
            self._bounds = self._compute_bounds()
        return self._bounds

    def _compute_bounds(self):
        pts = self._handles()
        if not pts:
            return QRectF()
        xs = [p.x() for p in pts]
        ys = [p.y() for p in pts]
        vr = self.viewRect()
        if vr is not None:
            # Include the visible range so the rays (drawn to the view edge)
            # are never clipped away by a stale bounding rect.
            xs += [vr.left(), vr.right()]
            ys += [vr.top(), vr.bottom()]
        return QRectF(min(xs), min(ys), max(xs) - min(xs), max(ys) - min(ys))

    def paint(self, p, *args):
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.setPen(self.currentPen)
        pts = self._handles()
        if len(pts) < 5:
            return
        center = pts[0]
        vr = self.viewRect()
        for sp in pts[1:]:
            dx = sp.x() - center.x()
            dy = sp.y() - center.y()
            if dx == 0 and dy == 0:
                continue
            if vr is None:
                far = pg.Point(center.x() + 9 * dx, center.y() + 9 * dy)
            else:
                far = self._ray_to_rect(center, dx, dy, vr)
            p.drawLine(center, far)

    @staticmethod
    def _ray_to_rect(center, dx, dy, rect):
        """Point where the ray (center, direction (dx, dy)) leaves ``rect``."""
        hits = []
        if dx != 0:
            for x in (rect.left(), rect.right()):
                t = (x - center.x()) / dx
                if t >= 0:
                    y = center.y() + t * dy
                    if rect.top() <= y <= rect.bottom():
                        hits.append(t)
        if dy != 0:
            for y in (rect.top(), rect.bottom()):
                t = (y - center.y()) / dy
                if t >= 0:
                    x = center.x() + t * dx
                    if rect.left() <= x <= rect.right():
                        hits.append(t)
        if not hits:
            return pg.Point(center.x(), center.y())
        t = max(hits)
        return pg.Point(center.x() + t * dx, center.y() + t * dy)

    def shape(self):
        """Hit region along the rays and around the five handles.

        The default shape (== boundingRect) would span the whole plot and
        swallow later clicks, so instead we cover only the thin rays plus the
        handle points, keeping the rest of the plot clickable.
        """
        import math
        pts = self._handles()
        if len(pts) < 5:
            return QPainterPath()
        center = pts[0]
        vr = self.viewRect()
        max_len = max(
            math.hypot(p.x() - center.x(), p.y() - center.y()) for p in pts[1:]
        ) or 1.0
        r = max_len * 0.12
        w = max_len * 0.08
        path = QPainterPath()
        for p in pts:
            path.addEllipse(p.x() - r, p.y() - r, 2 * r, 2 * r)
        for sp in pts[1:]:
            dx = sp.x() - center.x()
            dy = sp.y() - center.y()
            if dx == 0 and dy == 0:
                continue
            far = self._ray_to_rect(center, dx, dy, vr) if vr is not None else sp
            length = math.hypot(far.x() - center.x(), far.y() - center.y())
            if length == 0:
                continue
            ux = (far.x() - center.x()) / length
            uy = (far.y() - center.y()) / length
            px, py = -uy, ux
            path.moveTo(center.x() + px * w, center.y() + py * w)
            path.lineTo(far.x() + px * w, far.y() + py * w)
            path.lineTo(far.x() - px * w, far.y() - py * w)
            path.lineTo(center.x() - px * w, center.y() - py * w)
            path.closeSubpath()
        return path


class _ReleaseFilter(QObject):
    """Run a callback after a mouse button is released."""

    def __init__(self, callback) -> None:
        super().__init__()
        self._callback = callback

    def eventFilter(self, obj, event) -> bool:
        if event.type() == QEvent.Type.MouseButtonRelease:
            QTimer.singleShot(0, self._callback)
        return False


class _ClickFilter(QObject):
    """Select a plot card when its widget (or embedded plot) is clicked."""

    def __init__(self, callback) -> None:
        super().__init__()
        self._callback = callback

    def eventFilter(self, obj, event) -> bool:
        if event.type() == QEvent.Type.MouseButtonPress:
            ctrl = bool(event.modifiers() & Qt.KeyboardModifier.ControlModifier)
            self._callback(ctrl)
        return False  # let the event continue (plots still pan/zoom)


class _DoubleClickFilter(QObject):
    """Focus a plot card when its widget (or embedded plot) is double-clicked."""

    def __init__(self, callback) -> None:
        super().__init__()
        self._callback = callback

    def eventFilter(self, obj, event) -> bool:
        if event.type() == QEvent.Type.MouseButtonDblClick:
            self._callback()
        return False


class _CardProxy(QGraphicsProxyWidget):
    """A card proxy: drag anywhere on the card to move it, double-click to focus.

    Once a card is focused its wheel/drag act on the plot content instead
    (handled by the canvas view), so moving it again means leaving focus first.
    """

    # Pixels the pointer must travel before a click becomes a drag, so a plain
    # click never reorders the cards.
    DRAG_THRESHOLD = 6
    # The bottom-left corner of a card holds the plot's own "A"/"F" buttons;
    # presses there go through to the plot instead of starting a card drag.
    BUTTON_SIZE = 44

    def __init__(self, on_select, on_drop, on_drag=None, on_drag_end=None,
                 on_focus=None, on_context=None) -> None:
        super().__init__()
        self._on_select = on_select
        self._on_drop = on_drop
        self._on_drag = on_drag
        self._on_drag_end = on_drag_end
        self._on_focus = on_focus
        self._on_context = on_context
        self._dragging = False
        self._moved = False
        self._press_scene = None
        self._start_pos = None

    def _on_plot_buttons(self, pos) -> bool:
        """True when the press lands on the plot's own corner buttons."""
        widget = self.widget()
        if widget is None:
            return False
        return (
            pos.y() >= widget.height() - self.BUTTON_SIZE
            and pos.x() <= self.BUTTON_SIZE
        )

    def mousePressEvent(self, event) -> None:
        if event.button() == Qt.MouseButton.RightButton and self._on_context:
            pos = event.screenPos()
            if hasattr(pos, "toPoint"):  # QPointF on some bindings
                pos = pos.toPoint()
            self._on_context(pos)
            event.accept()
            return
        if (
            event.button() == Qt.MouseButton.LeftButton
            and not self._on_plot_buttons(event.pos())
        ):
            self._dragging = True
            self._moved = False
            self._press_scene = event.scenePos()
            self._start_pos = self.pos()
            self.setZValue(1)
            self._on_select(bool(event.modifiers() & Qt.KeyboardModifier.ControlModifier))
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseDoubleClickEvent(self, event) -> None:
        if (
            event.button() == Qt.MouseButton.LeftButton
            and self._on_focus is not None
            and not self._on_plot_buttons(event.pos())
        ):
            # Cancel the drag the second click started, then focus the plot.
            self._dragging = False
            self._moved = False
            self.setZValue(0)
            self._on_focus()
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def mouseMoveEvent(self, event) -> None:
        if self._dragging and event.buttons() & Qt.MouseButton.LeftButton:
            delta = event.scenePos() - self._press_scene
            if not self._moved:
                if (
                    abs(delta.x()) < self.DRAG_THRESHOLD
                    and abs(delta.y()) < self.DRAG_THRESHOLD
                ):
                    event.accept()
                    return
                self._moved = True
            self.setPos(self._start_pos + delta)
            if self._on_drag is not None:
                self._on_drag(event.scenePos())
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event) -> None:
        if self._dragging:
            self._dragging = False
            self.setZValue(0)
            moved = self._moved
            self._moved = False
            if moved:
                self._on_drop(event.scenePos())
            else:
                # A plain click selects only: never move the card.
                self.setPos(self._start_pos)
                if self._on_drag_end is not None:
                    self._on_drag_end()
            event.accept()
            return
        super().mouseReleaseEvent(event)


class _ZoomableGraphicsView(QGraphicsView):
    """A canvas view that zooms the whole canvas with the mouse wheel."""

    def __init__(self, scene) -> None:
        super().__init__(scene)
        self.enter_callback = None
        self.delete_callback = None
        self.unfocus_callback = None
        self.plot_wheel_cb = None
        self.plot_pan_start_cb = None
        self.plot_pan_move_cb = None
        self.plot_pan_end_cb = None
        self.rubber_select_cb = None
        self.rubber_clear_cb = None
        self.select_all_cb = None
        self._rubber_band = None
        self._rubber_origin = None
        self._rubber_ctrl = False
        self.setAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignTop)
        self.setTransformationAnchor(QGraphicsView.ViewportAnchor.AnchorUnderMouse)
        self.setResizeAnchor(QGraphicsView.ViewportAnchor.AnchorUnderMouse)
        self.setBackgroundBrush(QColor("#eef2f7"))
        self.setFrameShape(QFrame.Shape.NoFrame)
        self.setRenderHints(QPainter.RenderHint.Antialiasing)

    def wheelEvent(self, event) -> None:
        # Route the wheel to a focused plot, else zoom the canvas.
        if self.plot_wheel_cb is not None:
            item = self.itemAt(event.position().toPoint())
            if self.plot_wheel_cb(item, event.angleDelta().y()):
                event.accept()
                return
        factor = 1.15 if event.angleDelta().y() > 0 else 1 / 1.15
        self.scale(factor, factor)

    def mousePressEvent(self, event) -> None:
        if event.button() == Qt.MouseButton.LeftButton:
            item = self.itemAt(event.position().toPoint())
            scene_pos = self.mapToScene(event.position().toPoint())
            if self.plot_pan_start_cb is not None and self.plot_pan_start_cb(item, scene_pos):
                event.accept()
                return
            if item is None:
                if self.unfocus_callback is not None:
                    self.unfocus_callback()
                self._begin_rubber_band(event.position().toPoint(), event.modifiers())
                event.accept()
                return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event) -> None:
        if self._rubber_origin is not None:
            self._rubber_band.setGeometry(
                QRect(self._rubber_origin, event.position().toPoint()).normalized()
            )
            event.accept()
            return
        if self.plot_pan_move_cb is not None:
            scene_pos = self.mapToScene(event.position().toPoint())
            if self.plot_pan_move_cb(scene_pos):
                event.accept()
                return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event) -> None:
        if self._rubber_origin is not None:
            self._finish_rubber_band(event.position().toPoint())
            event.accept()
            return
        if self.plot_pan_end_cb is not None and self.plot_pan_end_cb():
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def _begin_rubber_band(self, view_pos, modifiers) -> None:
        self._rubber_origin = view_pos
        self._rubber_ctrl = bool(modifiers & Qt.KeyboardModifier.ControlModifier)
        if self._rubber_band is None:
            self._rubber_band = QRubberBand(QRubberBand.Shape.Rectangle, self)
        self._rubber_band.setGeometry(QRect(view_pos, QSize()))
        self._rubber_band.show()

    def _finish_rubber_band(self, view_pos) -> None:
        rect = QRect(self._rubber_origin, view_pos).normalized()
        self._rubber_origin = None
        self._rubber_band.hide()
        if rect.width() < 4 and rect.height() < 4:
            # A plain click on empty canvas: clear the selection.
            if self.rubber_clear_cb is not None:
                self.rubber_clear_cb()
            return
        top_left = self.mapToScene(rect.topLeft())
        bottom_right = self.mapToScene(rect.bottomRight())
        scene_rect = QRectF(top_left, bottom_right).normalized()
        if self.rubber_select_cb is not None:
            self.rubber_select_cb(scene_rect, self._rubber_ctrl)

    def keyPressEvent(self, event) -> None:
        if (
            event.key() == Qt.Key.Key_A
            and event.modifiers() & Qt.KeyboardModifier.ControlModifier
            and self.select_all_cb is not None
        ):
            self.select_all_cb()
            event.accept()
            return
        if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
            if self.enter_callback is not None:
                self.enter_callback()
            event.accept()
            return
        if event.key() in (Qt.Key.Key_Delete, Qt.Key.Key_Backspace):
            if self.delete_callback is not None:
                self.delete_callback()
            event.accept()
            return
        super().keyPressEvent(event)


class _FigureCard(QFrame):
    """A bordered plot card (click to select, double-click to focus)."""

    _BASE = "#plotCard { background: #ffffff; border: 1px solid #c9d5e2; border-radius: 6px; }"
    _SELECTED = "#plotCard { background: #ffffff; border: 2px solid #4285f4; border-radius: 6px; }"
    _FOCUSED = "#plotCard { background: #ffffff; border: 2px solid #34a853; border-radius: 6px; }"

    def __init__(self, plot_widget, index: int, select_callback,
                 side_widget=None) -> None:
        super().__init__()
        self._index = index
        self._select_callback = select_callback
        self._plot_widget = plot_widget
        self._proxy = None
        self._selected = False
        self._focused = False
        self.setObjectName("plotCard")
        self.setMinimumSize(200, 200)

        lay = QVBoxLayout(self)
        lay.setContentsMargins(6, 6, 6, 6)
        lay.setSpacing(0)
        if side_widget is not None:
            body = QWidget()
            bh = QHBoxLayout(body)
            bh.setContentsMargins(0, 0, 0, 0)
            bh.setSpacing(4)
            bh.addWidget(plot_widget, 1)
            bh.addWidget(side_widget, 0)
            lay.addWidget(body, 1)
        else:
            lay.addWidget(plot_widget, 1)
        self._apply_style()

    def _apply_style(self) -> None:
        if self._focused:
            self.setStyleSheet(self._FOCUSED)
        elif self._selected:
            self.setStyleSheet(self._SELECTED)
        else:
            self.setStyleSheet(self._BASE)

    def index(self) -> int:
        return self._index

    def set_index(self, index: int) -> None:
        self._index = index

    def plot_widget(self):
        return self._plot_widget

    def proxy(self):
        return self._proxy

    def select(self) -> None:
        self._select_callback(self._index)

    def set_selected(self, selected: bool) -> None:
        self._selected = selected
        self._apply_style()

    def set_focused(self, focused: bool) -> None:
        self._focused = focused
        self._apply_style()


class _FigurePermuteDialog(QDialog):
    """Generate copies of one plot across files, an axis or filters.

    Only one dimension per run (as in OMIQ): run it again on the results to
    build a grid of, say, parameters × files.
    """

    FILE = "file"
    X_AXIS = "x"
    Y_AXIS = "y"
    FILTER = "filter"

    def __init__(self, parent, plot_type, files, columns, filters) -> None:
        super().__init__(parent)
        self.setWindowTitle("Permute")
        self.resize(560, 560)
        self._files = list(files)
        self._columns = list(columns)
        self._filters = list(filters)

        lay = QVBoxLayout(self)
        lay.setContentsMargins(14, 12, 14, 12)
        lay.setSpacing(8)

        lay.addWidget(QLabel("<b>Permute by</b>"))
        radios = QGridLayout()
        radios.setHorizontalSpacing(18)
        radios.setVerticalSpacing(4)
        # Radios sharing a parent are auto-exclusive in Qt, so the dimension
        # and layout choices need separate groups or one clears the other.
        self._dimension_group = QButtonGroup(self)
        self._layout_group = QButtonGroup(self)
        self._radios = {}
        specs = [
            (self.FILE, "File", bool(self._files)),
            (self.X_AXIS, "X axis", plot_type != "image" and bool(self._columns)),
            (self.Y_AXIS, "Y axis", plot_type == "scatter" and bool(self._columns)),
            (self.FILTER, "Filter", bool(self._filters)),
        ]
        for i, (key, label, enabled) in enumerate(specs):
            radio = QRadioButton(label)
            radio.setEnabled(bool(enabled))
            radio.toggled.connect(lambda checked: checked and self._reload_values())
            self._dimension_group.addButton(radio)
            radios.addWidget(radio, i // 2, i % 2)
            self._radios[key] = radio
        lay.addLayout(radios)

        lay.addWidget(QLabel("<b>Values</b>"))
        self.search = QLineEdit()
        self.search.setPlaceholderText("Search…")
        self.search.setClearButtonEnabled(True)
        self.search.textChanged.connect(lambda _t: self._apply_filter())
        lay.addWidget(self.search)

        self.values_list = QListWidget()
        self.values_list.setStyleSheet(
            "QListWidget { background: #ffffff; border: 1px solid #d0d7e2; }"
        )
        self.values_list.itemChanged.connect(lambda _i: self._update_preview())
        lay.addWidget(self.values_list, 1)

        pick_row = QHBoxLayout()
        all_btn = QPushButton("Select all")
        all_btn.clicked.connect(lambda _=False: self._check_all(True))
        none_btn = QPushButton("Clear")
        none_btn.clicked.connect(lambda _=False: self._check_all(False))
        pick_row.addWidget(all_btn)
        pick_row.addWidget(none_btn)
        pick_row.addStretch()
        lay.addLayout(pick_row)

        lay.addWidget(QLabel("<b>Layout</b>"))
        self.same_row_radio = QRadioButton("Same row")
        self.new_row_radio = QRadioButton("New row")
        self._layout_group.addButton(self.same_row_radio)
        self._layout_group.addButton(self.new_row_radio)
        self.same_row_radio.setChecked(True)
        lay.addWidget(self.same_row_radio)
        lay.addWidget(self.new_row_radio)

        self.preview = QLabel("")
        self.preview.setStyleSheet("color: #6b7785;")
        self.preview.setWordWrap(True)
        lay.addWidget(self.preview)

        buttons = QHBoxLayout()
        buttons.addStretch()
        cancel = QPushButton("Cancel")
        cancel.clicked.connect(self.reject)
        self.ok_btn = QPushButton("Permute")
        self.ok_btn.setDefault(True)
        self.ok_btn.clicked.connect(self.accept)
        buttons.addWidget(cancel)
        buttons.addWidget(self.ok_btn)
        lay.addLayout(buttons)

        for key, radio in self._radios.items():
            if radio.isEnabled():
                radio.setChecked(True)
                break
        self._reload_values()

    # -- values --------------------------------------------------------
    def _reload_values(self) -> None:
        dimension = self.dimension()
        self.values_list.blockSignals(True)
        self.values_list.clear()
        if dimension == self.FILE:
            for path, name in self._files:
                self._add_item(str(name or path), (path, name))
        elif dimension in (self.X_AXIS, self.Y_AXIS):
            for name in self._columns:
                self._add_item(str(name), name)
        elif dimension == self.FILTER:
            for label, payload in self._filters:
                self._add_item(str(label), dict(payload))
        self.values_list.blockSignals(False)
        self._apply_filter()

    def _add_item(self, text: str, payload) -> None:
        item = QListWidgetItem(text)
        item.setFlags(item.flags() | Qt.ItemFlag.ItemIsUserCheckable)
        item.setCheckState(Qt.CheckState.Unchecked)
        item.setData(Qt.ItemDataRole.UserRole, payload)
        self.values_list.addItem(item)

    def _apply_filter(self) -> None:
        query = self.search.text().strip().lower()
        for i in range(self.values_list.count()):
            item = self.values_list.item(i)
            item.setHidden(bool(query) and query not in item.text().lower())
        self._update_preview()

    def _check_all(self, checked: bool) -> None:
        state = Qt.CheckState.Checked if checked else Qt.CheckState.Unchecked
        self.values_list.blockSignals(True)
        for i in range(self.values_list.count()):
            item = self.values_list.item(i)
            if not item.isHidden():
                item.setCheckState(state)
        self.values_list.blockSignals(False)
        self._update_preview()

    def _update_preview(self) -> None:
        count = len(self.values())
        ready = count > 0 and bool(self.dimension())
        self.ok_btn.setEnabled(ready)
        if count:
            self.preview.setText(
                f"{count} new plot(s) will be created; the template stays."
            )
        else:
            self.preview.setText("Select at least one value.")

    # -- results -------------------------------------------------------
    def dimension(self) -> str:
        for key, radio in self._radios.items():
            if radio.isChecked():
                return key
        return ""

    def values(self) -> list:
        out = []
        for i in range(self.values_list.count()):
            item = self.values_list.item(i)
            if item.checkState() == Qt.CheckState.Checked:
                out.append(item.data(Qt.ItemDataRole.UserRole))
        return out

    def new_row(self) -> bool:
        return self.new_row_radio.isChecked()


class _FigureLegendWidget(QFrame):
    """A compact colour legend shown beside an image plot."""

    def __init__(self) -> None:
        super().__init__()
        self.setObjectName("imageLegend")
        self.setStyleSheet(
            "#imageLegend { background: #ffffff; border: 1px solid #c9d5e2; "
            "border-radius: 4px; }"
        )
        self.setMinimumWidth(80)
        self.setMaximumWidth(180)
        self._lay = QVBoxLayout(self)
        self._lay.setContentsMargins(6, 6, 6, 6)
        self._lay.setSpacing(4)

    def set_layers(self, layers) -> None:
        while self._lay.count():
            item = self._lay.takeAt(0)
            w = item.widget()
            if w is not None:
                w.deleteLater()
        for layer in layers:
            color = tuple(layer.get("color", (255, 255, 255)))
            name = str(layer.get("name") or layer.get("parameter") or "")
            row = QWidget()
            rh = QHBoxLayout(row)
            rh.setContentsMargins(0, 0, 0, 0)
            rh.setSpacing(4)
            swatch = QLabel()
            swatch.setFixedSize(12, 12)
            swatch.setStyleSheet(
                f"background-color: rgb({color[0]},{color[1]},{color[2]}); "
                "border: 1px solid #888;"
            )
            label = QLabel(name)
            label.setStyleSheet("color: #333;")
            rh.addWidget(swatch)
            rh.addWidget(label, 1)
            self._lay.addWidget(row)
        self._lay.addStretch(1)


def _format_number(value) -> str:
    """Format a number compactly (no trailing zeros) for the range fields."""
    if value is None:
        return ""
    value = float(value)
    if value.is_integer():
        return str(int(value))
    return f"{value:.10g}"


def _format_level(value) -> str:
    """Image channel Min/Max: one decimal is all the precision needed."""
    if value is None:
        return ""
    try:
        return f"{float(value):.1f}"
    except (TypeError, ValueError):
        return ""


def _round_level(value):
    try:
        return round(float(value), 1)
    except (TypeError, ValueError):
        return None


class _SelectAllFilter(QObject):
    """Select all text after a mouse click into the line edit."""

    def __init__(self, line_edit) -> None:
        super().__init__()
        self._line_edit = line_edit

    def eventFilter(self, obj, event) -> bool:
        if event.type() == QEvent.Type.MouseButtonRelease:
            QTimer.singleShot(0, self._line_edit.selectAll)
        return False


class _PinnedFirstTabBar(QTabBar):
    """A tab bar whose first tab can be selected but not dragged to reorder."""

    def __init__(self, parent=None) -> None:
        super().__init__(parent)
        self._pressed_index = -1

    def mousePressEvent(self, event) -> None:
        self._pressed_index = self.tabAt(event.position().toPoint())
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event) -> None:
        super().mouseReleaseEvent(event)
        self._pressed_index = -1

    def mouseMoveEvent(self, event) -> None:
        if self._pressed_index == 0:
            return  # block dragging the pinned first (Workflow) tab
        super().mouseMoveEvent(event)


class _SizeField(QWidget):
    """Integer size field: a plain line edit with ±10 step buttons."""

    def __init__(self, value, on_change, minimum: int = 200, maximum: int = 4000) -> None:
        super().__init__()
        self._value = None if value is None else int(value)
        self._on_change = on_change
        self._min = minimum
        self._max = maximum
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)

        lay = QHBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(1)

        self.edit = QLineEdit()
        self.edit.setFixedWidth(56)
        self.edit.setText("" if self._value is None else str(self._value))
        self.edit.setAlignment(Qt.AlignmentFlag.AlignRight)
        self.edit.editingFinished.connect(self._commit)
        # Select all after a click so typing replaces the old value.
        self._filter = _SelectAllFilter(self.edit)
        self.edit.installEventFilter(self._filter)
        lay.addWidget(self.edit)

        btns = QVBoxLayout()
        btns.setContentsMargins(0, 0, 0, 0)
        btns.setSpacing(0)
        self._up = QToolButton()
        self._up.setText("▲")
        self._up.setFixedSize(16, 12)
        self._up.setCursor(Qt.CursorShape.PointingHandCursor)
        self._up.clicked.connect(lambda: self._step(10))
        self._down = QToolButton()
        self._down.setText("▼")
        self._down.setFixedSize(16, 12)
        self._down.setCursor(Qt.CursorShape.PointingHandCursor)
        self._down.clicked.connect(lambda: self._step(-10))
        btns.addWidget(self._up)
        btns.addWidget(self._down)
        lay.addLayout(btns)

    def value(self) -> int:
        return self._value

    def set_enabled(self, enabled: bool) -> None:
        self.edit.setEnabled(enabled)
        self._up.setEnabled(enabled)
        self._down.setEnabled(enabled)

    def set_value(self, value) -> None:
        """Set the displayed value without triggering on_change."""
        if value is None:
            self._value = None
            self.edit.setText("")
        else:
            self._value = self._clamp(value)
            self.edit.setText(str(self._value))

    def _clamp(self, value) -> int:
        return max(self._min, min(self._max, int(value)))

    def _step(self, delta: int) -> None:
        base = self._value if self._value is not None else self._min
        self._value = self._clamp(base + delta)
        self.edit.setText(str(self._value))
        if self._on_change is not None:
            self._on_change(self._value)

    def _commit(self) -> None:
        text = self.edit.text().strip()
        if text == "":
            self._value = None
            self.edit.setText("")
            return
        try:
            self._value = self._clamp(int(text))
        except (ValueError, TypeError):
            self.edit.setText("" if self._value is None else str(self._value))
            return
        self.edit.setText(str(self._value))
        if self._on_change is not None:
            self._on_change(self._value)


class _LogStepSpinBox(QWidget):
    """Narrow numeric field: text shown as typed; ▲/▼ step ×10 / ÷10.

    `decimals` fixes how many decimals are shown and stored (axis ranges use 1).
    """

    def __init__(self, value, on_change, decimals: int | None = None) -> None:
        super().__init__()
        self._value = value
        self._on_change = on_change
        self._decimals = decimals
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)

        lay = QHBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(1)

        self.edit = QLineEdit()
        self.edit.setFixedWidth(64)
        self.edit.setText(self._format(value))
        self.edit.editingFinished.connect(self._commit_edit)
        self.edit.returnPressed.connect(self._commit_edit)
        lay.addWidget(self.edit)

        btns = QVBoxLayout()
        btns.setContentsMargins(0, 0, 0, 0)
        btns.setSpacing(0)
        self._up = QToolButton()
        self._up.setText("▲")
        self._up.setFixedSize(16, 12)
        self._up.setAutoRaise(True)
        self._up.setCursor(Qt.CursorShape.PointingHandCursor)
        self._up.clicked.connect(lambda: self._step(10.0))
        self._down = QToolButton()
        self._down.setText("▼")
        self._down.setFixedSize(16, 12)
        self._down.setAutoRaise(True)
        self._down.setCursor(Qt.CursorShape.PointingHandCursor)
        self._down.clicked.connect(lambda: self._step(0.1))
        btns.addWidget(self._up)
        btns.addWidget(self._down)
        lay.addLayout(btns)

    def _format(self, value) -> str:
        if self._decimals is not None and value is not None:
            try:
                return f"{float(value):.{self._decimals}f}"
            except (TypeError, ValueError):
                return _format_number(value)
        return _format_number(value)

    def _round(self, value):
        if self._decimals is not None and value is not None:
            try:
                return round(float(value), self._decimals)
            except (TypeError, ValueError):
                return value
        return value

    def value(self):
        return self._value

    def set_enabled(self, enabled: bool) -> None:
        self.edit.setEnabled(enabled)
        self._up.setEnabled(enabled)
        self._down.setEnabled(enabled)

    def set_value(self, value) -> None:
        self._value = value
        self.edit.setText(self._format(value))

    def _current_value(self) -> float:
        try:
            return float(self.edit.text().strip())
        except (ValueError, TypeError):
            return 0.0

    def _step(self, factor: float) -> None:
        base = 1.0 if self.edit.text().strip() == "" else self._current_value()
        self._value = self._round(base * factor)
        self.edit.setText(self._format(self._value))
        if self._on_change is not None:
            self._on_change(self._value)

    def _commit_edit(self) -> None:
        text = self.edit.text().strip()
        try:
            self._value = self._round(float(text))
        except (ValueError, TypeError):
            self.edit.setText(self._format(self._value))
            return
        self.edit.setText(self._format(self._value))
        if self._on_change is not None:
            self._on_change(self._value)


def _task_color(task_type: str) -> str:
    """Return the color for a task type."""
    if task_type == "root":
        return ROOT_COLOR
    return TASK_TYPES.get(task_type, ("Task", FALLBACK_COLOR))[1]


# Module kinds: every non-import task is a map, generate, or visualize module.
# kind is derived from type (not stored in the manifest), so old projects need
# no migration.
MODULE_KINDS = {
    "gating": "map",
    "scale": "map",
    "rename": "map",
    "compensation": "map",
    "illumination": "map",
    # Unmix can now generate image pyramids ("Unmix for image"), which locks
    # its upstream modules; the parameter-only behaviour still works.
    "unmix": "generate",
    "segmentation": "generate",
    "figure": "visualize",
    "feature": "generate",
    "gate2col": "generate",
    # Placeholder modules (no implementation yet).
    "feature_up": "generate",
    "subset": "map",
    "subsample": "map",
    "dimred": "generate",
    "cluster": "generate",
    # Area only computes and displays a result; it never changes the data that
    # flows downstream, so it must not lock its upstream modules.
    "area": "visualize",
    "data_clean": "generate",
    "batch_align": "map",
    "export": "map",
}


class _AreaCancelled(Exception):
    """Raised inside a running Area job when its parameters changed."""


def _task_kind(task_type: str) -> str:
    """Return a task's kind: import / map / generate / visualize."""
    if task_type == "import":
        return "import"
    return MODULE_KINDS.get(task_type, "map")


# Open-module registry states: a module is unmodified, modified-but-unsaved, or
# just saved (transient, used to trigger a downstream update before returning
# to unmodified).
MODULE_STATE_UNMODIFIED = "unmodified"
MODULE_STATE_MODIFIED = "modified"
MODULE_STATE_SAVED = "saved"


def _task_is_locked(task: dict) -> bool:
    """True if a descendant generate module has saved data.

    Saved generated output (for example segmentation masks) locks every module
    *above* it: those modules can still be opened and explored, but their
    changes cannot be saved. The generate module itself is never locked, and
    neither is anything below it.
    """

    def walk(node) -> bool:
        for child in node.get("children", []):
            if (
                _task_kind(child.get("type", "")) == "generate"
                and child.get("output", {}).get("saved")
            ):
                return True
            if walk(child):
                return True
        return False

    return walk(task)


class _CustomColormapDialog(QDialog):
    """Create a custom colormap from a list of colour stops."""

    def __init__(self, parent=None, start_name: str = "viridis") -> None:
        super().__init__(parent)
        self.setWindowTitle("New Colormap")
        self.resize(560, 470)
        self._entry = None
        self._rows = []  # [[position, [r, g, b]], ...]

        lay = QVBoxLayout(self)
        lay.setContentsMargins(12, 12, 12, 12)
        lay.setSpacing(8)

        form = QGridLayout()
        form.setHorizontalSpacing(10)
        form.setVerticalSpacing(6)
        form.addWidget(QLabel("Name"), 0, 0)
        self.name_edit = QLineEdit()
        self.name_edit.setPlaceholderText("My colormap")
        form.addWidget(self.name_edit, 0, 1)
        form.addWidget(QLabel("Start from"), 1, 0)
        self.start_combo = _NoWheelComboBox()
        for name in _palette_names():
            self.start_combo.addItem(name, name)
        index = self.start_combo.findData(start_name)
        self.start_combo.setCurrentIndex(index if index >= 0 else 0)
        form.addWidget(self.start_combo, 1, 1)
        lay.addLayout(form)

        self.preview = QLabel()
        self.preview.setFixedHeight(30)
        lay.addWidget(self.preview)

        lay.addWidget(QLabel("Stops (position 0–1 and colour)"))
        self.table = QTableWidget(0, 3)
        self.table.setHorizontalHeaderLabels(["Position", "Color", ""])
        self.table.verticalHeader().setVisible(False)
        header = self.table.horizontalHeader()
        header.setSectionResizeMode(0, QHeaderView.ResizeMode.Fixed)
        header.setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
        header.setSectionResizeMode(2, QHeaderView.ResizeMode.Fixed)
        self.table.setColumnWidth(0, 120)
        self.table.setColumnWidth(2, 90)
        self.table.setStyleSheet(
            "QTableWidget { background: #ffffff; border: 1px solid #d0d7e2; }"
        )
        lay.addWidget(self.table, 1)

        add_btn = QPushButton("Add stop")
        add_btn.clicked.connect(self._add_stop)
        lay.addWidget(add_btn, 0, Qt.AlignmentFlag.AlignLeft)

        self.hint = QLabel("")
        self.hint.setStyleSheet("color: #c0392b;")
        self.hint.setWordWrap(True)
        lay.addWidget(self.hint)

        buttons = QHBoxLayout()
        buttons.addStretch()
        cancel = QPushButton("Cancel")
        cancel.clicked.connect(self.reject)
        self.ok_btn = QPushButton("OK")
        self.ok_btn.setDefault(True)
        self.ok_btn.clicked.connect(self._accept)
        buttons.addWidget(cancel)
        buttons.addWidget(self.ok_btn)
        lay.addLayout(buttons)

        self.name_edit.textChanged.connect(lambda _t: self._validate())
        self.start_combo.currentIndexChanged.connect(lambda _i: self._load_start())
        self._load_start()

    # -- stops ---------------------------------------------------------
    def _load_start(self) -> None:
        name = self.start_combo.currentData()
        rows = []
        try:
            cmap = _figure_colormap(name)
            for pos, color in zip(list(cmap.pos), list(cmap.color)):
                rows.append([float(pos), [int(c) for c in list(color)[:3]]])
        except Exception:
            rows = []
        if len(rows) > 7:
            # Built-in maps expand to 256 stops; keep a handful of samples so
            # the editor stays usable (and the saved JSON stays small).
            lut = cmap.getLookupTable(0.0, 1.0, 256)
            rows = []
            for i in range(7):
                position = i / 6.0
                color = lut[int(round(position * 255))]
                rows.append([position, [int(c) for c in color[:3]]])
        if len(rows) < 2:
            rows = [[0.0, [0, 0, 0]], [1.0, [255, 255, 255]]]
        self._rows = rows
        self._rebuild_table()

    def _color_at(self, position: float):
        try:
            cmap = _colormap_from_stops(self._rows)
            lut = cmap.getLookupTable(0.0, 1.0, 256)
            index = int(round(max(0.0, min(1.0, position)) * 255))
            return [int(c) for c in lut[index][:3]]
        except Exception:
            return [0, 0, 0]

    def _paint_swatch(self, button, rgb) -> None:
        button.setStyleSheet(
            f"background-color: rgb({rgb[0]},{rgb[1]},{rgb[2]}); "
            "border: 1px solid #6b7785; border-radius: 3px;"
        )

    def _rebuild_table(self) -> None:
        self.table.setRowCount(len(self._rows))
        for i, (position, rgb) in enumerate(self._rows):
            spin = _NoWheelDoubleSpinBox()
            spin.setRange(0.0, 1.0)
            spin.setDecimals(3)
            spin.setSingleStep(0.05)
            spin.setValue(float(position))
            spin.valueChanged.connect(
                lambda value, row=i: self._set_position(row, value)
            )
            self.table.setCellWidget(i, 0, spin)

            swatch = QPushButton()
            swatch.setCursor(Qt.CursorShape.PointingHandCursor)
            swatch.clicked.connect(lambda _=False, row=i: self._pick_color(row))
            self._paint_swatch(swatch, rgb)
            self.table.setCellWidget(i, 1, swatch)

            remove = QPushButton("Remove")
            remove.setEnabled(len(self._rows) > 2)
            remove.clicked.connect(lambda _=False, row=i: self._remove_stop(row))
            self.table.setCellWidget(i, 2, remove)
        self._update_preview()

    def _set_position(self, row, value) -> None:
        if 0 <= row < len(self._rows):
            self._rows[row][0] = float(value)
            self._update_preview()

    def _pick_color(self, row) -> None:
        if not (0 <= row < len(self._rows)):
            return
        rgb = self._rows[row][1]
        chosen = QColorDialog.getColor(
            QColor(rgb[0], rgb[1], rgb[2]), self, "Choose stop color"
        )
        if chosen.isValid():
            self._rows[row][1] = [chosen.red(), chosen.green(), chosen.blue()]
            self._rebuild_table()

    def _add_stop(self) -> None:
        rows = sorted(self._rows, key=lambda r: r[0])
        position = 0.5
        if len(rows) >= 2:
            gaps = [
                (rows[i + 1][0] - rows[i][0], i) for i in range(len(rows) - 1)
            ]
            _gap, i = max(gaps)
            position = (rows[i][0] + rows[i + 1][0]) / 2.0
        self._rows.append([position, self._color_at(position)])
        self._rows.sort(key=lambda r: r[0])
        self._rebuild_table()

    def _remove_stop(self, row) -> None:
        if len(self._rows) <= 2 or not (0 <= row < len(self._rows)):
            return
        del self._rows[row]
        self._rebuild_table()

    def _update_preview(self) -> None:
        try:
            lut = _colormap_from_stops(self._rows).getLookupTable(0.0, 1.0, 260)
        except Exception:
            lut = None
        self.preview.setPixmap(_gradient_pixmap(lut, 260, 26))
        self._validate()

    # -- validation ----------------------------------------------------
    def _validate(self) -> None:
        name = self.name_edit.text().strip()
        if not name:
            message = "Enter a name for the colormap."
        elif _colormap_name_taken(name):
            message = f"“{name}” is already used by another colormap."
        else:
            message = ""
        self.hint.setText(message)
        self.ok_btn.setEnabled(not message)

    def _accept(self) -> None:
        self._entry = {
            "name": self.name_edit.text().strip(),
            "stops": [
                [round(float(pos), 4), list(rgb)]
                for pos, rgb in _normalize_stops(self._rows)
            ],
        }
        self.accept()

    def result_entry(self) -> dict:
        return self._entry or {}


class _ColormapPicker(QWidget):
    """Searchable list of every colormap with swatches, preview and CRUD."""

    selectionChanged = Signal(str)

    def __init__(self, current: str = "", parent=None) -> None:
        super().__init__(parent)
        self._current = current or _default_palette()

        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(6)

        self.search = QLineEdit()
        self.search.setPlaceholderText("Search colormaps…")
        self.search.setClearButtonEnabled(True)
        self.search.textChanged.connect(lambda _t: self.reload())
        lay.addWidget(self.search)

        self.list = QListWidget()
        self.list.setUniformItemSizes(True)
        self.list.setIconSize(QSize(110, 14))
        self.list.setStyleSheet(
            "QListWidget { background: #ffffff; border: 1px solid #d0d7e2; }"
        )
        self.list.currentItemChanged.connect(self._on_current)
        lay.addWidget(self.list, 1)

        preview_row = QHBoxLayout()
        self.preview = QLabel()
        self.preview.setMinimumHeight(26)
        preview_row.addWidget(self.preview, 1)
        self.preview_name = QLabel("")
        self.preview_name.setStyleSheet("color: #5a6673;")
        preview_row.addWidget(self.preview_name)
        lay.addLayout(preview_row)

        buttons = QHBoxLayout()
        self.new_btn = QPushButton("New custom…")
        self.new_btn.clicked.connect(self._new_custom)
        self.delete_btn = QPushButton("Delete custom")
        self.delete_btn.clicked.connect(self._delete_custom)
        buttons.addWidget(self.new_btn)
        buttons.addWidget(self.delete_btn)
        buttons.addStretch()
        lay.addLayout(buttons)

        self.reload()

    # -- list ----------------------------------------------------------
    def selected(self) -> str:
        return self._current

    def set_selected(self, name: str) -> None:
        if name:
            self._current = name
            self.reload()

    def reload(self) -> None:
        query = self.search.text().strip().lower()
        self.list.blockSignals(True)
        self.list.clear()
        target = None
        for title, names in _colormap_groups():
            shown = [n for n in names if not query or query in n.lower()]
            if not shown:
                continue
            header = QListWidgetItem(title)
            header.setFlags(Qt.ItemFlag.NoItemFlags)
            font = header.font()
            font.setBold(True)
            header.setFont(font)
            header.setForeground(QColor("#8a94a0"))
            self.list.addItem(header)
            for name in shown:
                item = QListWidgetItem(_colormap_gradient_pixmap(name), name)
                item.setData(Qt.ItemDataRole.UserRole, name)
                self.list.addItem(item)
                if name == self._current:
                    target = item
        self.list.blockSignals(False)
        if target is not None:
            self.list.setCurrentItem(target)
            self.list.scrollToItem(
                target, QAbstractItemView.ScrollHint.PositionAtCenter
            )
        else:
            self._show_preview(self._current)

    def _show_preview(self, name: str) -> None:
        try:
            lut = _figure_colormap(name).getLookupTable(0.0, 1.0, 260)
        except Exception:
            lut = None
        self.preview.setPixmap(_gradient_pixmap(lut, 260, 24))
        self.preview_name.setText(name)
        custom = {m["name"] for m in _custom_colormaps()}
        self.delete_btn.setEnabled(name in custom)

    def _on_current(self, current, _previous) -> None:
        name = current.data(Qt.ItemDataRole.UserRole) if current else None
        if not name:
            return
        self._current = name
        self._show_preview(name)
        self.selectionChanged.emit(name)

    # -- custom colormaps ----------------------------------------------
    def _new_custom(self) -> None:
        dialog = _CustomColormapDialog(self, self._current)
        if dialog.exec() != QDialog.DialogCode.Accepted:
            return
        entry = dialog.result_entry()
        if not entry.get("name"):
            return
        settings = _global_settings()
        settings.setdefault("colormaps", []).append(entry)
        _save_global_settings(settings)
        _GRADIENT_CACHE.clear()
        self._current = entry["name"]
        self.reload()
        self.selectionChanged.emit(self._current)

    def _delete_custom(self) -> None:
        name = self._current
        settings = _global_settings()
        maps = settings.setdefault("colormaps", [])
        if not any(m.get("name") == name for m in maps):
            return
        reply = QMessageBox.question(
            self,
            "Delete Colormap",
            f"Delete the custom colormap “{name}”?\n"
            "Plots using it will fall back to viridis.",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
        )
        if reply != QMessageBox.StandardButton.Yes:
            return
        settings["colormaps"] = [m for m in maps if m.get("name") != name]
        _save_global_settings(settings)
        _GRADIENT_CACHE.clear()
        self._current = _default_palette()
        self.reload()
        self.selectionChanged.emit(self._current)


class _GlobalSettingsDialog(QDialog):
    """Global Settings: left tab list + right pages, applied on OK."""

    def __init__(self, parent=None) -> None:
        super().__init__(parent)
        self.setWindowTitle("Global Settings")
        self.resize(840, 620)
        self._draft = copy.deepcopy(_global_settings())

        root = QVBoxLayout(self)
        root.setContentsMargins(12, 12, 12, 10)
        root.setSpacing(10)

        body = QHBoxLayout()
        body.setSpacing(10)

        self.tabs = QListWidget()
        self.tabs.setFixedWidth(160)
        self.tabs.setStyleSheet(
            "QListWidget { background: #ffffff; border: 1px solid #d0d7e2; }"
            "QListWidget::item { padding: 7px 9px; }"
            "QListWidget::item:selected { background: #e1ecf9; color: #1a4a76; }"
        )
        body.addWidget(self.tabs)

        self.stack = QStackedWidget()
        body.addWidget(self.stack, 1)
