    def _build_middle_panel(self) -> QWidget:
        """Middle column: Parameter (top, 3) + Sample (bottom, 1)."""
        container = QWidget()
        layout = QVBoxLayout(container)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(12)
