    def _dimred_column_values(self, parquet_path, rec, name):
        """Row-aligned float64 values of one Dimension Reduction column."""
        import numpy as np
        import pandas as pd

        if not isinstance(rec, dict) or not rec.get("parquet"):
            return None
        dparquet = rec["parquet"]
        if rec.get("kind") == "image":
            man = self._image_load_manifest(dparquet)
            if man is None:
                return None
            try:
                src = pd.read_parquet(parquet_path, columns=["x", "y"])
                ddf = pd.read_parquet(dparquet, columns=["x", "y", name])
            except Exception:  # noqa: BLE001
                return None
            xmin = float(man["xmin"])
            ymin = float(man["ymin"])
            width = int(round(float(man["xmax"]) - xmin)) + 1
            height = int(round(float(man["ymax"]) - ymin)) + 1
            dxi = np.rint(ddf["x"].to_numpy(dtype="float64") - xmin).astype(np.int64)
            dyi = np.rint(ddf["y"].to_numpy(dtype="float64") - ymin).astype(np.int64)
            grid = np.full((height, width), np.nan, dtype="float64")
            dok = (dxi >= 0) & (dxi < width) & (dyi >= 0) & (dyi < height)
            grid[dyi[dok], dxi[dok]] = ddf[name].to_numpy(dtype="float64")[dok]
            sxi = np.rint(src["x"].to_numpy(dtype="float64") - xmin).astype(np.int64)
            syi = np.rint(src["y"].to_numpy(dtype="float64") - ymin).astype(np.int64)
            sok = (sxi >= 0) & (sxi < width) & (syi >= 0) & (syi < height)
            out = np.full(len(src), np.nan, dtype="float64")
            out[sok] = grid[syi[sok], sxi[sok]]
            return out
        try:
            df = pd.read_parquet(dparquet, columns=[name])
        except Exception:  # noqa: BLE001
            return None
        return df[name].to_numpy(dtype="float64")

    def _dimred_raster(self, rec, bbox, spacing):
        """Return (scalar_2d, data_rect) for a Dimension Reduction channel."""
        if not isinstance(rec, dict) or not rec.get("parquet"):
            return None, None
        ent = self._ensure_image_index(rec["parquet"])
        if ent is None or ent.get("manifest") is None:
            return None, None
        crop, rect, _frac = self._image_raster(
            rec["parquet"], ent["manifest"], bbox, spacing, rec.get("channel"), None, None
        )
        return crop, rect

    def _seg_load_mask(self, mask_path):
        """Load a mask's full 2-D label grid (cached by path + signature)."""
        import numpy as np
        import pandas as pd

        cache = getattr(self, "_seg_mask_cache", None)
        if cache is None:
            cache = {}
            self._seg_mask_cache = cache
        key = str(mask_path)
        sign = self._seg_signature(mask_path)
        hit = cache.get(key)
        if hit is not None and hit[0] == sign:
            return hit[1]
        man = self._image_load_manifest(mask_path)
        if man is None:
            return None
        width = int(round(float(man["xmax"]) - float(man["xmin"]))) + 1
        height = int(round(float(man["ymax"]) - float(man["ymin"]))) + 1
        try:
            df = pd.read_parquet(mask_path, columns=["x", "y", "mask"])
        except (OSError, ValueError):
            return None
        xi = np.rint(
            df["x"].to_numpy(dtype="float64") - float(man["xmin"])
        ).astype(np.int64)
        yi = np.rint(
            df["y"].to_numpy(dtype="float64") - float(man["ymin"])
        ).astype(np.int64)
        mask = np.zeros((height, width), dtype=np.int32)
        ok = (xi >= 0) & (xi < width) & (yi >= 0) & (yi < height)
        mask[yi[ok], xi[ok]] = df["mask"].to_numpy(dtype=np.int32)[ok]
        if len(cache) > 4:
            cache.clear()
        cache[key] = (sign, mask)
        return mask

    def _seg_mask_values(self, parquet_path, mask_path):
        """Mask labels aligned to a parquet's rows (float64, 0 where unknown)."""
        import numpy as np
        import pandas as pd

        ent = self._ensure_image_index(parquet_path)
        if ent is None or ent.get("manifest") is None:
            return None
        man = ent["manifest"]
        mask = self._seg_load_mask(mask_path)
        if mask is None:
            return None
        cache = getattr(self, "_seg_value_cache", None)
        if cache is None:
            cache = {}
            self._seg_value_cache = cache
        key = (str(parquet_path), str(mask_path))
        hit = cache.get(key)
        if hit is not None:
            return hit
        try:
            df = pd.read_parquet(parquet_path, columns=["x", "y"])
        except Exception:  # noqa: BLE001
            return None
        xi = np.rint(
            df["x"].to_numpy(dtype="float64") - float(man["xmin"])
        ).astype(np.int64)
        yi = np.rint(
            df["y"].to_numpy(dtype="float64") - float(man["ymin"])
        ).astype(np.int64)
        ok = (
            (xi >= 0) & (xi < mask.shape[1])
            & (yi >= 0) & (yi < mask.shape[0])
        )
        out = np.zeros(len(df), dtype="float64")
        out[ok] = mask[yi[ok], xi[ok]].astype("float64")
        if len(cache) > 4:
            cache.clear()
        cache[key] = out
        return out

    def _seg_mask_raster(self, mask_path, bbox, spacing):
        """Return (label_2d, data_rect) for a mask over the visible bbox.

        Reads the mask's own raster pyramid (mode per block) so zoomed-out
        views load only the coarse level; deep zooms read raw labels.
        """
        ent = self._ensure_image_index(mask_path)
        if ent is None or ent.get("manifest") is None:
            return None, None
        crop, rect, _frac = self._image_raster(
            mask_path, ent["manifest"], bbox, spacing, "mask", None, None
        )
        return crop, rect

    def _g2c_raster(self, rec, bbox, spacing):
        """Return (scalar_2d, data_rect) for a Gate2Col 0/1 channel over a bbox."""
        if not isinstance(rec, dict) or not rec.get("parquet"):
            return None, None
        ent = self._ensure_image_index(rec["parquet"])
        if ent is None or ent.get("manifest") is None:
            return None, None
        crop, rect, _frac = self._image_raster(
            rec["parquet"], ent["manifest"], bbox, spacing, rec.get("channel"), None, None
        )
        return crop, rect

    def _seg_temp_dir(self):
        """Shared temp folder for this project's segmentation caches."""
        import hashlib
        import tempfile

        key = "no-project"
        if self.project is not None:
            key = hashlib.md5(
                str(self.project.path.resolve()).encode("utf-8")
            ).hexdigest()[:12]
        return Path(tempfile.gettempdir()) / "smage" / "segmentation" / key

    def _seg_clear_edge_cache(self) -> None:
        """Drop this project's cached mask-edge images (temp data only)."""
        import shutil

        cache = getattr(self, "_seg_edge_cache", None)
        if cache is not None:
            cache.clear()
        try:
            shutil.rmtree(self._seg_temp_dir(), ignore_errors=True)
        except Exception:  # noqa: BLE001
            pass

    def _seg_edge_map(self, mask_path):
        """Return (and disk-cache) the boolean edge map of a mask."""
        import numpy as np

        mask = self._seg_load_mask(mask_path)
        if mask is None:
            return None
        sign = self._seg_signature(mask_path)
        cache = getattr(self, "_seg_edge_cache", None)
        if cache is None:
            cache = {}
            self._seg_edge_cache = cache
        key = str(mask_path)
        hit = cache.get(key)
        if hit is not None and hit[0] == sign:
            return hit[1]
        path = self._seg_temp_dir() / f"{Path(str(mask_path)).stem}.{sign}.npy"
        edge = None
        if path.is_file():
            try:
                edge = np.load(path)
            except (OSError, ValueError):
                edge = None
        if edge is None or edge.shape != mask.shape:
            edge = np.zeros(mask.shape, dtype=bool)
            if mask.size:
                edge[1:, :] |= mask[1:, :] != mask[:-1, :]
                edge[:, 1:] |= mask[:, 1:] != mask[:, :-1]
            try:
                path.parent.mkdir(parents=True, exist_ok=True)
                np.save(path, edge)
            except OSError:
                pass
        if len(cache) > 4:
            cache.clear()
        cache[key] = (sign, edge)
        return edge

    # --- segmentation page
    def _build_segmentation_page(self, name: str, task_def: dict, locked: bool) -> QWidget:
        """Build the Segmentation page (files | method | preview | plot settings)."""
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        bar = QFrame()
        bar.setObjectName("moduleBar")
        tl = QHBoxLayout(bar)
        tl.setContentsMargins(12, 6, 12, 6)
        tl.setSpacing(4)
        tl.addWidget(QLabel(f"<b>{self._module_display_title(task_def.get('id'), name)}</b>"))
        if locked:
            lock_icon = QLabel()
            lock_icon.setPixmap(_lock_pixmap())
            lock_icon.setFixedSize(14, 14)
            lock_icon.setToolTip("Locked — a downstream generate module has saved data")
            tl.addWidget(lock_icon)
            draft = QLabel("Draft (locked)")
            draft.setStyleSheet("color: #b58900; font-weight: bold;")
            tl.addWidget(draft)
        tl.addStretch()
        save_btn = QPushButton("Save")
        save_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        save_btn.setEnabled(not locked)
        close_btn = QPushButton("Close")
        close_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        close_btn.clicked.connect(lambda _=False: self._seg_close(page))
        tl.addWidget(save_btn)
        tl.addWidget(close_btn)
        layout.addWidget(bar)

        params = task_def.setdefault("params", {})
        params.setdefault("method", "nuclear_expansion")
        # Migrate legacy method ids (Cellpose/StarDist) to their -cpu names.
        if params.get("method") == "cellpose":
            params["method"] = "cellpose-cpu"
        elif params.get("method") == "stardist":
            params["method"] = "stardist-cpu"
        params.setdefault("files", [])
        params.setdefault("expose", {})
        params.setdefault("column", "Mask")
        params.setdefault("method_params", {})
        params.setdefault("masks", {})
        params.setdefault("applied", {})
        params.setdefault("plot", {})
        page._seg_task_def = task_def
        page._seg_task_id = task_def.get("id")
        page._seg_params = params
        page._seg_locked = locked
        page._seg_save_btn = save_btn
        page._seg_dirty = False
        page._seg_snapshot = copy.deepcopy(params)
        page._seg_applied_snapshot = dict(params.get("applied") or {})
        page._seg_overlay_item = None
        page._seg_mask_cache = {}
        page._seg_ext_running = False
        page._seg_log_lines = []
        save_btn.clicked.connect(lambda _=False: self._seg_save_now(page))

        content = QWidget()
        content.setStyleSheet("background: #f5f8fb;")
        row = QHBoxLayout(content)
        row.setContentsMargins(12, 12, 12, 12)
        row.setSpacing(12)
        splitter = QSplitter(Qt.Orientation.Horizontal)
        splitter.setChildrenCollapsible(False)
        splitter.addWidget(self._seg_files_panel(page))
        splitter.addWidget(self._seg_method_panel(page))
        page._seg_preview_panel = self._seg_preview_panel(page)
        page._seg_settings_panel = self._seg_plot_settings_panel(page)
        splitter.addWidget(page._seg_preview_panel)
        splitter.addWidget(page._seg_settings_panel)
        splitter.setStretchFactor(0, 1)
        splitter.setStretchFactor(1, 1)
        splitter.setStretchFactor(2, 2)
        splitter.setStretchFactor(3, 1)
        splitter.setSizes([260, 260, 520, 260])
        row.addWidget(splitter, 1)
        layout.addWidget(content, 1)
        page._seg_splitter = splitter

        self._seg_refresh_files(page)
        self._seg_update_preview_visibility(page)
        self._seg_update_save_btn(page)
        return page

    def _seg_default_plot(self, parquet_path, task_id=None) -> dict:
        """A fresh image plot config for the preview panel."""
        columns = []
        rec = self._figure_record(parquet_path)
        if rec is not None:
            columns = self._columns_for(rec.get("parquet"), task_id)
        channel = next((c for c in columns if c not in ("x", "y")), None)
        return {
            "type": "image",
            "file": parquet_path,
            "file_name": rec.get("name") if rec else None,
            "x": "x",
            "y": "y",
            "color_mode": "parameter",
            "color_param": channel,
            "last_color_param": channel,
            "palette": _default_palette(),
            "layers": (
                [{
                    "parameter": channel,
                    "color": (255, 255, 255),
                    "name": str(channel),
                    "visible": True,
                }] if channel else []
            ),
            "show_legend": True,
            "show_axes": True,
            "show_axis_names": True,
            "show_indices": True,
            "show_sample_name": True,
            "mask_mode": "shape",
            "mask_color": "random",
            "mask_alpha": 45,
        }

    def _seg_file_rows(self, page) -> list:
        return list(page._seg_params.get("files") or [])

    def _seg_file_status(self, page, parquet_path) -> str:
        """no mask / pending / applied for one file."""
        params = page._seg_params
        rec = self._seg_mask_record(params, parquet_path)
        path = self._seg_mask_file(rec)
        if path is None:
            return SEG_STATUS_NO_MASK
        saved = page._seg_applied_snapshot.get(parquet_path) if hasattr(
            page, "_seg_applied_snapshot"
        ) else None
        if saved and saved == self._seg_signature(path):
            return SEG_STATUS_APPLIED
        return SEG_STATUS_PENDING

    def _seg_any_mask(self, page) -> bool:
        for path in self._seg_file_rows(page):
            rec = self._seg_mask_record(page._seg_params, path)
            if self._seg_mask_file(rec) is not None:
                return True
        return False

    def _seg_files_panel(self, page) -> QWidget:
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)

        # Top: method chooser (small), bottom: files (large) — ratio 1:6.
        top = QWidget()
        tlay = QVBoxLayout(top)
        tlay.setContentsMargins(0, 0, 0, 0)
        tlay.setSpacing(4)
        tlay.addWidget(QLabel("Method"))
        method_combo = _NoWheelComboBox()
        for text, value in SEG_METHODS:
            method_combo.addItem(text, value)
        idx = method_combo.findData(page._seg_params.get("method"))
        method_combo.setCurrentIndex(idx if idx >= 0 else 0)
        method_combo.setEnabled(not page._seg_locked)
        method_combo.currentIndexChanged.connect(
            lambda _=0: self._seg_on_method_changed(page)
        )
        tlay.addWidget(method_combo)
        page._seg_method_combo = method_combo

        bottom = QWidget()
        blay = QVBoxLayout(bottom)
        blay.setContentsMargins(0, 0, 0, 0)
        blay.setSpacing(6)
        set_btn = QPushButton("Set Files")
        set_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        set_btn.setEnabled(not page._seg_locked)
        set_btn.clicked.connect(lambda _=False: self._seg_set_files(page))
        blay.addWidget(set_btn)
        page._seg_setfiles_btn = set_btn

        table = QTableWidget()
        table.setColumnCount(3)
        table.setHorizontalHeaderLabels(["File", "Expose", "Status"])
        header = table.horizontalHeader()
        header.setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
        header.setSectionResizeMode(1, QHeaderView.ResizeMode.ResizeToContents)
        header.setSectionResizeMode(2, QHeaderView.ResizeMode.ResizeToContents)
        table.verticalHeader().setVisible(False)
        table.verticalHeader().setDefaultSectionSize(26)
        table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
        table.setStyleSheet(
            "QTableWidget { background: #ffffff; border: none; }"
            "QTableWidget::item:selected { background: #dbeafa; }"
        )
        table.itemChanged.connect(lambda item: self._seg_expose_changed(page, item))
        blay.addWidget(table, 1)
        page._seg_files_table = table

        blay.addWidget(QLabel("Mask column"))
        name_edit = QLineEdit(str(page._seg_params.get("column") or "Mask"))
        name_edit.setEnabled(not page._seg_locked)
        name_edit.editingFinished.connect(
            lambda: self._seg_column_edited(page)
        )
        blay.addWidget(name_edit)
        page._seg_column_edit = name_edit
        hint = QLabel(
            "Checked files expose their mask as a parameter to downstream modules "
            "when this module is saved."
        )
        hint.setStyleSheet("color: #6b7785;")
        hint.setWordWrap(True)
        blay.addWidget(hint)

        split = QSplitter(Qt.Orientation.Vertical)
        split.setChildrenCollapsible(False)
        split.addWidget(top)
        split.addWidget(bottom)
        split.setStretchFactor(0, 1)
        split.setStretchFactor(1, 6)
        split.setSizes([90, 540])
        lay.addWidget(split, 1)
        return panel

    def _seg_refresh_files(self, page) -> None:
        """Rebuild the file table and the mask-column status snapshot."""
        table = page._seg_files_table
        table.blockSignals(True)
        rows = self._seg_file_rows(page)
        table.setRowCount(len(rows))
        expose = page._seg_params.get("expose") or {}
        editable = not page._seg_locked
        for i, path in enumerate(rows):
            name_item = QTableWidgetItem(self._comp_file_name(path, page._seg_task_id))
            name_item.setData(Qt.ItemDataRole.UserRole, path)
            name_item.setFlags(Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable)
            table.setItem(i, 0, name_item)

            has_mask = self._seg_mask_file(
                self._seg_mask_record(page._seg_params, path)
            ) is not None
            chk = QTableWidgetItem()
            chk.setFlags(
                Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsUserCheckable
            )
            chk.setCheckState(
                Qt.CheckState.Checked if expose.get(path) else Qt.CheckState.Unchecked
            )
            chk.setSelected(False)
            if not has_mask or not editable:
                chk.setFlags(Qt.ItemFlag.ItemIsSelectable)
            table.setItem(i, 1, chk)

            status = self._seg_file_status(page, path)
            sitem = QTableWidgetItem(status)
            sitem.setFlags(Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable)
            if status == SEG_STATUS_APPLIED:
                sitem.setForeground(QColor("#1a7f37"))
            elif status == SEG_STATUS_PENDING:
                sitem.setForeground(QColor("#b58900"))
            else:
                sitem.setForeground(QColor("#9aa0a6"))
            table.setItem(i, 2, sitem)
        table.blockSignals(False)
        self._seg_rebuild_method_panel(page)
        self._seg_refresh_plot_settings(page)
        self._seg_update_preview_visibility(page)

    def _seg_expose_changed(self, page, item) -> None:
        if page._seg_locked or item.column() != 1:
            return
        table = page._seg_files_table
        row = table.row(item)
        rows = self._seg_file_rows(page)
        if not (0 <= row < len(rows)):
            return
        path = rows[row]
        expose = page._seg_params.setdefault("expose", {})
        expose[path] = item.checkState() == Qt.CheckState.Checked
        self._seg_refresh_status(page)
        self._seg_mark_dirty(page)

    def _seg_refresh_status(self, page) -> None:
        """Update only the status cells (no widget rebuild)."""
        table = page._seg_files_table
        rows = self._seg_file_rows(page)
        table.blockSignals(True)
        for i, path in enumerate(rows):
            if i >= table.rowCount():
                break
            item = table.item(i, 2)
            if item is None:
                continue
            status = self._seg_file_status(page, path)
            item.setText(status)
            if status == SEG_STATUS_APPLIED:
                item.setForeground(QColor("#1a7f37"))
            elif status == SEG_STATUS_PENDING:
                item.setForeground(QColor("#b58900"))
            else:
                item.setForeground(QColor("#9aa0a6"))
        table.blockSignals(False)

    def _seg_is_image_file(self, rec) -> bool:
        """Whether an imported (processed) file holds pixel data.

        Processed records do not carry the original dimensions, so this checks
        the source file's extension, then any recorded image dimensions, then
        the presence of an image index (which the importer builds for TIFFs).
        """
        dims = rec.get("dimensions") or {}
        if dims.get("kind") == "image":
            return True
        source = str(rec.get("source") or "")
        if Path(source).suffix.lower() in (".tif", ".tiff"):
            return True
        parquet = rec.get("parquet")
        if parquet and self._image_load_manifest(parquet) is not None:
            return True
        return False

    def _seg_set_files(self, page) -> None:
        records = self._available_files(page._seg_task_id)
        names = [rec.get("name", "") for rec in records]
        current = [self._comp_file_name(p, page._seg_task_id) for p in self._seg_file_rows(page)]
        chosen = self._pick_items_dialog(
            "Select data files", names, current, "Filter files..."
        )
        if chosen is None:
            return
        chosen_set = set(chosen)
        picks = [rec for rec in records if rec.get("name", "") in chosen_set]
        bad = [rec.get("name", "") for rec in picks if not self._seg_is_image_file(rec)]
        if bad:
            QMessageBox.warning(
                self,
                "Segmentation",
                "Only image files can be used: segmentation works on pixels and "
                "the mask must line up row by row with the image.\n\n"
                "Not image files:\n" + "\n".join(f"· {n}" for n in bad),
            )
            return
        page._seg_params["files"] = [rec.get("parquet") for rec in picks]
        self._seg_refresh_files(page)
        self._seg_mark_dirty(page)

    def _seg_column_edited(self, page) -> None:
        name = page._seg_column_edit.text().strip() or "Mask"
        page._seg_params["column"] = name
        self._seg_refresh_status(page)
        self._seg_mark_dirty(page)

    def _seg_on_method_changed(self, page) -> None:
        page._seg_params["method"] = page._seg_method_combo.currentData()
        self._seg_rebuild_method_panel(page)
        self._seg_mark_dirty(page)

    def _seg_rebuild_method_panel(self, page) -> None:
        """Swap the second panel between method params and the mask-input table."""
        host = page._seg_method_host
        self._clear_settings_layout(host.layout())
        method = page._seg_params.get("method")
        if method == "mask_input":
            self._seg_mask_input_panel(page, host)
        elif _extension_def(method) is not None:
            self._seg_external_method_panel(page, host)
        else:
            self._seg_method_params_panel(page, host)

    def _seg_method_panel(self, page) -> QWidget:
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        host = QWidget()
        host.setLayout(QVBoxLayout())
        host.layout().setContentsMargins(0, 0, 0, 0)
        host.layout().setSpacing(6)
        lay.addWidget(host, 1)
        page._seg_method_host = host
        return panel

    def _seg_map_params(self, page) -> dict:
        method = page._seg_params.get("method") or "nuclear_expansion"
        store = page._seg_params.setdefault("method_params", {})
        params = store.setdefault(method, {})
        for key, value in SEG_DEFAULT_PARAMS.items():
            params.setdefault(key, value)
        return params

    def _seg_otsu_value(self, page, parquet_path, channel):
        """Otsu threshold of one channel (cached per file + channel)."""
        import pandas as pd

        cache = getattr(page, "_seg_otsu_cache", None)
        if cache is None:
            cache = {}
            page._seg_otsu_cache = cache
        key = (str(parquet_path), str(channel))
        if key in cache:
            return cache[key]
        try:
            df = pd.read_parquet(parquet_path, columns=[channel])
        except Exception:  # noqa: BLE001
            return None
        values = pd.to_numeric(
            df[channel], errors="coerce"
        ).to_numpy(dtype="float64")
        value = _otsu_threshold(values)
        cache[key] = value
        return value

    def _seg_method_params_panel(self, page, host) -> None:
        """Nuclear Expansion parameters + Calculate."""
        lay = host.layout()
        params = self._seg_map_params(page)
        enabled = not page._seg_locked

        lay.addWidget(QLabel("<b>Nuclear Expansion</b>"))
        lay.addWidget(QLabel("Nucleus channel"))
        columns = []
        for path in self._seg_file_rows(page):
            for name in self._columns_for(path, page._seg_task_id):
                if name not in columns:
                    columns.append(name)
        channel_combo = _NoWheelComboBox()
        channel_combo.addItem("", None)
        for name in columns:
            if name in ("x", "y"):
                continue
            channel_combo.addItem(name, name)
        idx = channel_combo.findData(params.get("channel"))
        if idx >= 0:
            channel_combo.setCurrentIndex(idx)
        channel_combo.setEnabled(enabled)
        lay.addWidget(channel_combo)
        lay.addWidget(self._param_hint(
            "Channel used to detect nuclei."
        ))

        lay.addWidget(QLabel("Threshold"))
        mode_combo = _NoWheelComboBox()
        mode_combo.addItem("Otsu (automatic)", "otsu")
        mode_combo.addItem("Manual value", "manual")
        idx = mode_combo.findData(params.get("threshold_mode", "otsu"))
        mode_combo.setCurrentIndex(max(0, idx))
        mode_combo.setEnabled(enabled)
        lay.addWidget(mode_combo)
        lay.addWidget(self._param_hint(
            "Otsu picks the cut-off from the histogram; Manual uses the value "
            "below."
        ))

        def otsu_default():
            """The Otsu value of the chosen channel, used as the default."""
            channel = params.get("channel")
            rows = self._seg_file_rows(page)
            if not channel or not rows:
                return None
            return self._seg_otsu_value(page, rows[0], channel)

        initial = float(params.get("threshold", 0.0))
        if params.get("threshold_mode", "otsu") != "manual":
            otsu = otsu_default()
            if otsu is not None:
                initial = otsu
        thr_spin = _LogStepSpinBox(initial, lambda v: on_threshold(v))
        thr_spin.set_enabled(enabled)
        thr_spin.setToolTip(
            "Prefilled with the Otsu value of the chosen channel. Editing it "
            "switches to a manual threshold."
        )
        lay.addWidget(thr_spin)
        lay.addWidget(self._param_hint(
            "Prefilled with the Otsu value. Editing it switches the mode to "
            "Manual."
        ))

        lay.addWidget(QLabel("Minimum nucleus area (px)"))
        area_spin = _NoWheelSpinBox()
        area_spin.setRange(1, 1000000)
        area_spin.setValue(int(params.get("min_area", 30)))
        area_spin.setEnabled(enabled)
        lay.addWidget(area_spin)
        lay.addWidget(self._param_hint(
            "Objects smaller than this many pixels are discarded as debris."
        ))

        lay.addWidget(QLabel("Expansion radius (px)"))
        exp_spin = _NoWheelSpinBox()
        exp_spin.setRange(0, 500)
        exp_spin.setValue(int(params.get("expand", 5)))
        exp_spin.setEnabled(enabled)
        lay.addWidget(exp_spin)
        lay.addWidget(self._param_hint(
            "How far each nucleus grows to approximate the cell body."
        ))

        calc_btn = QPushButton("Calculate")
        calc_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        calc_btn.setEnabled(enabled)
        lay.addWidget(calc_btn)
        status = QLabel("")
        status.setStyleSheet("color: #6b7785;")
        status.setWordWrap(True)
        lay.addWidget(status)
        lay.addStretch(1)
        page._seg_calc_btn = calc_btn
        page._seg_calc_status = status

        def refresh_otsu():
            if params.get("threshold_mode") == "manual":
                return
            value = otsu_default()
            if value is not None:
                thr_spin.set_value(value)

        def on_threshold(value):
            params["threshold"] = float(value)
            if params.get("threshold_mode") != "manual":
                params["threshold_mode"] = "manual"
                mode_combo.setCurrentIndex(mode_combo.findData("manual"))
            self._seg_mark_dirty(page)

        def on_channel(_=0):
            params["channel"] = channel_combo.currentData()
            refresh_otsu()
            self._seg_mark_dirty(page)

        def on_mode(_=0):
            params["threshold_mode"] = mode_combo.currentData()
            if params["threshold_mode"] == "otsu":
                refresh_otsu()
            self._seg_mark_dirty(page)

        def on_area(value):
            params["min_area"] = int(value)
            self._seg_mark_dirty(page)

        def on_expand(value):
            params["expand"] = int(value)
            self._seg_mark_dirty(page)

        channel_combo.currentIndexChanged.connect(on_channel)
        mode_combo.currentIndexChanged.connect(on_mode)
        area_spin.valueChanged.connect(on_area)
        exp_spin.valueChanged.connect(on_expand)
        calc_btn.clicked.connect(lambda _=False: self._seg_calculate(page))

    def _seg_channel_columns(self, page) -> list:
        """Union of non-coordinate columns across the selected files."""
        columns = []
        for path in self._seg_file_rows(page):
            for name in self._columns_for(path, page._seg_task_id):
                if name in ("x", "y"):
                    continue
                if name not in columns:
                    columns.append(name)
        return columns

    def _seg_external_method_panel(self, page, host) -> None:
        """Cellpose / StarDist params: extension status, channel, Calculate."""
        method = page._seg_params.get("method")
        entry = _extension_def(method)
        lay = host.layout()
        params = self._seg_map_params(page)
        enabled = not page._seg_locked
        ready = self._ext_ready(method)

        lay.addWidget(QLabel(f"<b>{entry['name']}</b>"))
        lay.addWidget(QLabel(entry["desc"]))
        lay.addWidget(QLabel("Runs in an external Python environment."))

        banner = QLabel()
        banner.setWordWrap(True)
        if ready:
            banner.setText("Extension ready ✓")
            banner.setStyleSheet("color: #1a7f37; font-weight: bold;")
        else:
            banner.setText(
                f"{entry['name']} extension is not configured.\n"
                "Open Extension → Manage Extension to set it up first."
            )
            banner.setStyleSheet("color: #b58900; font-weight: bold;")
        lay.addWidget(banner)

        def param_label(title, desc=""):
            row = QWidget()
            h = QHBoxLayout(row)
            h.setContentsMargins(0, 0, 0, 0)
            h.setSpacing(6)
            h.addWidget(QLabel(title))
            if desc:
                d = QLabel(desc)
                d.setStyleSheet("color: #6b7785;")
                h.addWidget(d)
            h.addStretch()
            return row

        lay.addWidget(QLabel("Files to calculate"))
        files_list = QListWidget()
        files_list.setStyleSheet(
            "QListWidget { background: #ffffff; border: 1px solid #d0d7e2; }"
        )
        files_list.setMaximumHeight(110)
        for path in self._seg_file_rows(page):
            item = QListWidgetItem(self._comp_file_name(path, page._seg_task_id))
            item.setData(Qt.ItemDataRole.UserRole, path)
            item.setFlags(item.flags() | Qt.ItemFlag.ItemIsUserCheckable)
            has_mask = (
                self._seg_mask_file(self._seg_mask_record(page._seg_params, path))
                is not None
            )
            item.setCheckState(
                Qt.CheckState.Unchecked if has_mask else Qt.CheckState.Checked
            )
            files_list.addItem(item)
        lay.addWidget(files_list)
        page._seg_calc_files_list = files_list

        lay.addWidget(param_label("Nucleus channel"))
        columns = self._seg_channel_columns(page)
        channel_combo = _NoWheelComboBox()
        channel_combo.addItem("", None)
        for name in columns:
            channel_combo.addItem(name, name)
        idx = channel_combo.findData(params.get("channel"))
        if idx >= 0:
            channel_combo.setCurrentIndex(idx)
        channel_combo.setEnabled(enabled)
        lay.addWidget(channel_combo)
        lay.addWidget(self._param_hint(
            "Channel used to detect nuclei."
        ))

        cyto_combo = None
        if entry["family"] == "cellpose":
            lay.addWidget(param_label("Cytoplasm channel (optional)"))
            cyto_combo = _NoWheelComboBox()
            cyto_combo.addItem("(none)", None)
            for name in columns:
                cyto_combo.addItem(name, name)
            idx = cyto_combo.findData(params.get("cyto_channel"))
            if idx >= 0:
                cyto_combo.setCurrentIndex(idx)
            cyto_combo.setEnabled(enabled)
            lay.addWidget(cyto_combo)
            lay.addWidget(self._param_hint(
                "Optional second channel that helps Cellpose follow the cell "
                "body around each nucleus."
            ))

        prob_spin = None
        nms_spin = None
        tile_size_spin = None
        if entry["family"] == "stardist":
            params.setdefault("model", entry["model"])
            params.setdefault("prob", 0.5)
            params.setdefault("nms", 0.3)
            params.setdefault("tile_size", 0)
            lay.addWidget(param_label("Probability threshold"))
            prob_spin = _NoWheelDoubleSpinBox()
            prob_spin.setRange(0.01, 1.0)
            prob_spin.setSingleStep(0.05)
            prob_spin.setDecimals(2)
            prob_spin.setValue(float(params.get("prob", 0.5)))
            prob_spin.setEnabled(enabled)
            lay.addWidget(prob_spin)
            lay.addWidget(self._param_hint(
                "Lower values detect more cells, and more false positives."
            ))

            lay.addWidget(param_label("NMS threshold"))
            nms_spin = _NoWheelDoubleSpinBox()
            nms_spin.setRange(0.0, 1.0)
            nms_spin.setSingleStep(0.05)
            nms_spin.setDecimals(2)
            nms_spin.setValue(float(params.get("nms", 0.3)))
            nms_spin.setEnabled(enabled)
            lay.addWidget(nms_spin)
            lay.addWidget(self._param_hint(
                "Non-maximum suppression: higher removes more overlapping "
                "detections."
            ))

            lay.addWidget(param_label("Tile size (px)"))
            tile_size_spin = _NoWheelSpinBox()
            tile_size_spin.setRange(0, 20000)
            tile_size_spin.setSingleStep(64)
            tile_size_spin.setValue(int(params.get("tile_size", 0)))
            tile_size_spin.setEnabled(enabled)
            tile_size_spin.setToolTip(
                "Approximate edge length of each tile in pixels. Smage splits "
                "each image into roughly this-sized tiles (n × m), so the "
                "actual counts adapt to the image dimensions. 0 lets StarDist "
                "pick a good size automatically."
            )
            lay.addWidget(tile_size_spin)
            lay.addWidget(self._param_hint(
                "Approximate tile edge in pixels; Smage adapts the actual "
                "tiles to the image size. 0 = let StarDist choose."
            ))

        calc_btn = QPushButton("Calculate")
        calc_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        calc_btn.setEnabled(enabled and ready)
        lay.addWidget(calc_btn)
        status = QLabel("")
        status.setStyleSheet("color: #6b7785;")
        status.setWordWrap(True)
        lay.addWidget(status)
        log = QPlainTextEdit()
        log.setReadOnly(True)
        log.setPlaceholderText("Calculation output appears here…")
        log.setStyleSheet(
            "background: #1e1e1e; color: #d4d4d4; "
            "font-family: Consolas, monospace; font-size: 9pt;"
        )
        for line in getattr(page, "_seg_log_lines", []):
            log.appendPlainText(line)
        lay.addWidget(log, 1)
        page._seg_calc_btn = calc_btn
        page._seg_calc_status = status
        page._seg_calc_log = log

        def on_channel(_=0):
            params["channel"] = channel_combo.currentData()
            self._seg_mark_dirty(page)

        def on_cyto(_=0):
            params["cyto_channel"] = cyto_combo.currentData()
            self._seg_mark_dirty(page)

        def on_prob(value):
            params["prob"] = float(value)
            self._seg_mark_dirty(page)

        def on_nms(value):
            params["nms"] = float(value)
            self._seg_mark_dirty(page)

        def on_tile_size(value):
            params["tile_size"] = int(value)
            self._seg_mark_dirty(page)

        channel_combo.currentIndexChanged.connect(on_channel)
        if cyto_combo is not None:
            cyto_combo.currentIndexChanged.connect(on_cyto)
        if prob_spin is not None:
            prob_spin.valueChanged.connect(on_prob)
        if nms_spin is not None:
            nms_spin.valueChanged.connect(on_nms)
        if tile_size_spin is not None:
            tile_size_spin.valueChanged.connect(on_tile_size)
        calc_btn.clicked.connect(lambda _=False: self._seg_calculate(page))

    def _seg_mask_input_panel(self, page, host) -> None:
        """Mask Input: one row per file with a mask-file picker + Import."""
        lay = host.layout()
        lay.addWidget(QLabel("<b>Mask Input</b>"))
        table = QTableWidget()
        table.setColumnCount(3)
        table.setHorizontalHeaderLabels(["File", "Mask file", "Status"])
        header = table.horizontalHeader()
        header.setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
        header.setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
        header.setSectionResizeMode(2, QHeaderView.ResizeMode.ResizeToContents)
        table.verticalHeader().setVisible(False)
        table.verticalHeader().setDefaultSectionSize(28)
        table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        table.setStyleSheet(
            "QTableWidget { background: #ffffff; border: none; }"
        )
        lay.addWidget(table, 1)
        page._seg_input_table = table

        import_btn = QPushButton("Import")
        import_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        import_btn.setEnabled(not page._seg_locked)
        lay.addWidget(import_btn)
        hint = QLabel(
            "Masks must be TIFF images whose width and height match the data file."
        )
        hint.setStyleSheet("color: #6b7785;")
        hint.setWordWrap(True)
        lay.addWidget(hint)
        status = QLabel("")
        status.setStyleSheet("color: #6b7785;")
        status.setWordWrap(True)
        lay.addWidget(status)
        page._seg_import_status = status
        import_btn.clicked.connect(lambda _=False: self._seg_import_masks(page))

        self._seg_refresh_input_table(page)

    def _seg_mask_record_live(self, page, parquet_path, create=False) -> dict:
        masks = page._seg_params.setdefault("masks", {})
        rec = masks.get(parquet_path)
        if not isinstance(rec, dict):
            if not create:
                return {}
            rec = {"path": None, "source": None, "input": None,
                   "state": SEG_IMPORT_SELECT}
            masks[parquet_path] = rec
        return rec

    def _seg_refresh_input_table(self, page) -> None:
        table = getattr(page, "_seg_input_table", None)
        if table is None:
            return
        rows = self._seg_file_rows(page)
        table.blockSignals(True)
        table.setRowCount(len(rows))
        enabled = not page._seg_locked
        for i, path in enumerate(rows):
            name_item = QTableWidgetItem(self._comp_file_name(path, page._seg_task_id))
            name_item.setFlags(Qt.ItemFlag.ItemIsEnabled)
            table.setItem(i, 0, name_item)

            rec = self._seg_mask_record(page._seg_params, path) or {}
            btn = QPushButton(Path(str(rec.get("input") or "")).name or "…")
            btn.setCursor(Qt.CursorShape.PointingHandCursor)
            btn.setEnabled(enabled)
            btn.setToolTip(rec.get("input") or "Choose a mask file")
            btn.clicked.connect(
                lambda _=False, p=path: self._seg_pick_mask_file(page, p)
            )
            table.setCellWidget(i, 1, btn)

            state = rec.get("state") or (
                SEG_IMPORT_DONE if self._seg_mask_file(rec) else SEG_IMPORT_SELECT
            )
            sitem = QTableWidgetItem(state)
            sitem.setFlags(Qt.ItemFlag.ItemIsEnabled)
            if state == SEG_IMPORT_DONE:
                sitem.setForeground(QColor("#1a7f37"))
            elif state in (SEG_IMPORT_FORMAT, SEG_IMPORT_SIZE, SEG_IMPORT_UNKNOWN):
                sitem.setForeground(QColor("#c0392b"))
            else:
                sitem.setForeground(QColor("#9aa0a6"))
            table.setItem(i, 2, sitem)
        table.blockSignals(False)

    def _seg_pick_mask_file(self, page, parquet_path) -> None:
        rec = self._seg_mask_record_live(page, parquet_path, create=True)
        already = self._seg_mask_file(rec) is not None
        if already:
            reply = QMessageBox.question(
                self,
                "Choose mask file",
                "This file's mask has already been imported.\n"
                "Choosing another one will delete the imported mask. Continue?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return
        start_dir = getattr(self, "_seg_last_mask_dir", None) or str(Path.home())
        if rec.get("input"):
            start_dir = str(Path(str(rec["input"])).parent)
        path, _ = QFileDialog.getOpenFileName(
            self, "Select mask file", start_dir, "All files (*)"
        )
        if not path:
            return
        self._seg_last_mask_dir = str(Path(path).parent)
        if already:
            self._seg_delete_mask(page, parquet_path)
        rec["input"] = path
        rec["state"] = SEG_IMPORT_WAITING
        rec["path"] = rec.get("path") if rec.get("source") == "builtin" else None
        self._seg_refresh_input_table(page)
        self._seg_refresh_files(page)
        self._seg_mark_dirty(page)

    def _seg_delete_mask(self, page, parquet_path) -> None:
        """Remove a file's mask parquet, its raster pyramid and its record."""
        import shutil

        rec = self._seg_mask_record(page._seg_params, parquet_path) or {}
        rel = rec.get("path")
        if rel and self.project is not None:
            try:
                (self.project.path / rel).unlink(missing_ok=True)
            except OSError:
                pass
            try:
                shutil.rmtree(
                    _image_index_dir(self.project.path / rel), ignore_errors=True
                )
            except OSError:
                pass
        page._seg_mask_cache = {}
        self._seg_value_cache = {}

    def _seg_import_masks(self, page) -> None:
        import numpy as np
        import tifffile

        rows = self._seg_file_rows(page)
        if not rows:
            QMessageBox.information(
                self, "Import", "Select data files first."
            )
            return
        pending = []
        for path in rows:
            rec = self._seg_mask_record_live(page, path, create=True)
            if rec.get("state") == SEG_IMPORT_DONE and self._seg_mask_file(rec):
                continue
            if not rec.get("input"):
                continue
            pending.append((path, rec))
        if not pending:
            QMessageBox.information(
                self, "Import",
                "All files have already been imported — nothing new to import.",
            )
            return

        done = 0
        errors = []
        for parquet_path, rec in pending:
            ent = self._ensure_image_index(parquet_path)
            if ent is None or ent.get("manifest") is None:
                rec["state"] = SEG_IMPORT_UNKNOWN
                errors.append(f"{self._comp_file_name(parquet_path, page._seg_task_id)}: no image index")
                continue
            man = ent["manifest"]
            height = int(round(man["ymax"] - man["ymin"])) + 1
            width = int(round(man["xmax"] - man["xmin"])) + 1
            src = str(rec.get("input") or "")
            suffix = Path(src).suffix.lower()
            if suffix not in (".tif", ".tiff", ".ome.tif", ".ome.tiff"):
                rec["state"] = SEG_IMPORT_FORMAT
                continue
            try:
                arr = tifffile.imread(src)
            except Exception:  # noqa: BLE001
                rec["state"] = SEG_IMPORT_FORMAT
                continue
            arr = np.asarray(arr)
            while arr.ndim > 2:
                arr = arr[0]
            if arr.ndim != 2:
                rec["state"] = SEG_IMPORT_FORMAT
                continue
            if arr.shape[0] != height or arr.shape[1] != width:
                rec["state"] = SEG_IMPORT_SIZE
                continue
            try:
                rel = self._seg_write_mask(page._seg_task_id, parquet_path, arr)
            except Exception:  # noqa: BLE001
                rec["state"] = SEG_IMPORT_UNKNOWN
                continue
            rec["path"] = rel
            rec["source"] = "import"
            rec["state"] = SEG_IMPORT_DONE
            done += 1

        self._seg_after_masks_changed(page)
        self._seg_refresh_input_table(page)
        self._seg_refresh_files(page)
        msg = f"Imported {done} mask(s)."
        if errors:
            msg += "\n" + "\n".join(errors)
        page._seg_import_status.setText(msg)
        self.statusBar().showMessage(msg.splitlines()[0])

    def _seg_write_mask(self, task_id, parquet_path, array) -> str:
        """Save a mask as a self-contained ``[x, y, mask]`` parquet + label pyramid.

        The mask becomes an extra channel of the source image: a parquet with
        one row per pixel (x/y shared with the source) plus a mode-based raster
        pyramid so large masks zoom like the original image. Returns the
        relative path of the mask parquet.
        """
        import numpy as np
        import pandas as pd

        if self.project is None:
            raise RuntimeError("no project")
        ent = self._ensure_image_index(parquet_path)
        if ent is None or ent.get("manifest") is None:
            raise RuntimeError("source image has no index")
        man = ent["manifest"]
        xmin = int(round(float(man["xmin"])))
        ymin = int(round(float(man["ymin"])))
        width = int(round(float(man["xmax"]) - float(man["xmin"]))) + 1
        height = int(round(float(man["ymax"]) - float(man["ymin"]))) + 1
        arr = np.asarray(array, dtype=np.int32)
        if arr.ndim != 2 or arr.shape[0] != height or arr.shape[1] != width:
            # Trust the array's own shape if it disagrees with the manifest.
            height, width = arr.shape

        stem = Path(str(parquet_path)).stem
        rel = f"Module/{task_id}/{stem}_mask.parquet"
        path = self.project.path / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        xx = np.tile(np.arange(width, dtype=np.int32), height) + xmin
        yy = np.repeat(np.arange(height, dtype=np.int32), width) + ymin
        pd.DataFrame({"x": xx, "y": yy, "mask": arr.ravel()}).to_parquet(
            path, index=False
        )
        _build_label_index(
            path, arr, xmin, xmin + width - 1, ymin, ymin + height - 1
        )
        self._seg_mask_cache = {}
        self._seg_value_cache = {}
        return rel

    def _seg_after_masks_changed(self, page) -> None:
        """Persist mask records: masks are products, so save right away."""
        self._seg_mask_cache = {}
        self._seg_value_cache = {}
        page._seg_task_def["output"] = {"saved": True}
        page._seg_task_def["params"] = page._seg_params
        if self.project is not None:
            self.project.save()
        page._seg_snapshot = copy.deepcopy(page._seg_params)
        page._seg_dirty = False
        self._seg_update_save_btn(page)
        self._refresh_workflow_tree()
        self._module_saved(page)

    def _seg_calculate(self, page) -> None:
        """Run the selected method on every selected file."""
        method = page._seg_params.get("method")
        if _extension_def(method) is not None:
            self._seg_calculate_external(page)
            return
        self._seg_calculate_nuclear(page)

    def _seg_calculate_nuclear(self, page) -> None:
        """Run Nuclear Expansion on every selected file."""
        rows = self._seg_file_rows(page)
        params = self._seg_map_params(page)
        status = getattr(page, "_seg_calc_status", None)
        if not rows:
            QMessageBox.information(self, "Calculate", "Select data files first.")
            return
        if not params.get("channel"):
            QMessageBox.information(
                self, "Calculate", "Choose the nucleus channel first."
            )
            return
        QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
        done = 0
        cells = 0
        errors = []
        try:
            for i, parquet_path in enumerate(rows):
                if status is not None:
                    status.setText(
                        f"Calculating {i + 1}/{len(rows)}: "
                        f"{self._comp_file_name(parquet_path, page._seg_task_id)}…"
                    )
                    QApplication.processEvents()
                mask, err = self._seg_nuclear_expansion(parquet_path, params)
                if mask is None:
                    errors.append(f"{self._comp_file_name(parquet_path, page._seg_task_id)}: {err}")
                    continue
                try:
                    rel = self._seg_write_mask(page._seg_task_id, parquet_path, mask)
                except Exception as exc:  # noqa: BLE001
                    errors.append(f"{self._comp_file_name(parquet_path, page._seg_task_id)}: {exc}")
                    continue
                rec = self._seg_mask_record_live(page, parquet_path, create=True)
                rec["path"] = rel
                rec["source"] = "builtin"
                rec["state"] = SEG_IMPORT_DONE
                done += 1
                cells += int(mask.max())
        finally:
            QApplication.restoreOverrideCursor()

        self._seg_after_masks_changed(page)
        self._seg_refresh_files(page)
        # The refresh rebuilds the parameter panel, so re-read its status label.
        status = getattr(page, "_seg_calc_status", status)
        if status is not None:
            msg = f"Calculated {done} mask(s) · {cells} cell(s)."
            if errors:
                msg += "\n" + "\n".join(errors)
            status.setText(msg)

    def _seg_raster_stack(self, parquet_path, channels):
        """Reconstruct a (C, H, W) float stack of the given channels."""
        import numpy as np

        images = []
        shape = None
        for channel in channels:
            image, err = self._seg_raster_channel(parquet_path, channel)
            if image is None:
                return None, err
            if shape is None:
                shape = image.shape
            elif image.shape != shape:
                return None, "channel shapes differ"
            images.append(image)
        return np.stack(images, axis=0).astype("float32"), None

    def _seg_calculate_external(self, page) -> None:
        """Run Cellpose / StarDist on the selected files in one subprocess."""
        import json
        import tempfile

        import numpy as np

        method = page._seg_params.get("method")
        entry = _extension_def(method)
        params = self._seg_map_params(page)
        files_list = getattr(page, "_seg_calc_files_list", None)
        if files_list is not None:
            rows = []
            for i in range(files_list.count()):
                item = files_list.item(i)
                if item.checkState() == Qt.CheckState.Checked:
                    rows.append(item.data(Qt.ItemDataRole.UserRole))
        else:
            rows = self._seg_file_rows(page)
        status = getattr(page, "_seg_calc_status", None)

        if not rows:
            QMessageBox.information(
                self, "Calculate",
                "Select at least one file in the list to calculate.",
            )
            return
        if not params.get("channel"):
            QMessageBox.information(
                self, "Calculate", "Choose the nucleus channel first."
            )
            return
        if not self._ext_ready(method):
            QMessageBox.information(
                self,
                "Calculate",
                f"{entry['name']} extension is not configured.\n"
                "Open Extension → Manage Extension to set it up first.",
            )
            return

        python = self._ext_python(method)
        runner = str(self._ext_runner_path(method))
        tmpdir = Path(tempfile.mkdtemp(prefix="smage-seg-"))
        jobs = []
        manifest = []
        nucleus = params.get("channel")
        cyto = params.get("cyto_channel") if entry["family"] == "cellpose" else None
        # Reconstructing the channel image happens in the main app, before the
        # external subprocess starts, so log it (this is the silent phase).
        self._seg_log(page, f"Rasterizing {len(rows)} file(s)…")
        for i, parquet_path in enumerate(rows):
            self._seg_log(
                page, f"  rasterizing {self._comp_file_name(parquet_path, page._seg_task_id)}…"
            )
            if cyto:
                stack, err = self._seg_raster_stack(parquet_path, [cyto, nucleus])
                nucleus_idx, cyto_idx = 1, 0
            else:
                stack, err = self._seg_raster_stack(parquet_path, [nucleus])
                nucleus_idx, cyto_idx = 0, None
            if stack is None:
                continue
            image_npy = tmpdir / f"in_{i}.npy"
            output_npy = tmpdir / f"out_{i}.npy"
            np.save(image_npy, stack)
            manifest.append({"image": str(image_npy), "output": str(output_npy)})
            jobs.append({"parquet": parquet_path, "output": str(output_npy)})

        if not jobs:
            return

        manifest_path = tmpdir / "jobs.json"
        manifest_path.write_text(json.dumps(manifest), encoding="utf-8")

        argv = [
            python, runner, "segment",
            "--manifest", str(manifest_path),
            "--nucleus", str(nucleus_idx),
            "--model", entry["model"],
            "--device", entry["device"],
        ]
        if cyto_idx is not None:
            argv += ["--cyto", str(cyto_idx)]
        if entry["family"] == "stardist":
            argv += [
                "--prob", str(params.get("prob", 0.5)),
                "--nms", str(params.get("nms", 0.3)),
                "--tile-size", str(params.get("tile_size", 0)),
            ]

        page._seg_ext_jobs = jobs
        page._seg_ext_tmpdir = tmpdir
        page._seg_ext_done = set()
        page._seg_ext_errors = []
        page._seg_ext_cells = 0
        page._seg_ext_report = []
        page._seg_ext_tile = None
        page._seg_ext_activity = ""
        page._seg_ext_finished = False
        page._seg_ext_running = True
        page._seg_ext_start_time = time.monotonic()
        # Keep appending to the existing log so each run's history is preserved.
        self._seg_log(
            page,
            f"===== {entry['name']} run — {len(jobs)} file(s) =====",
        )
        worker = self._ext_worker()
        worker.clear()  # drop any stale results from earlier operations
        # Stop any previous run's poll timer so it can't steal this run's events.
        old_timer = getattr(page, "_seg_ext_timer", None)
        if old_timer is not None:
            old_timer.stop()
        worker.run(("seg-batch",), argv)
        if status is not None:
            status.setText(f"Running {entry['name']} on {len(jobs)} file(s)…")

        timer = QTimer(self)
        timer.setInterval(150)
        timer.timeout.connect(lambda: self._seg_ext_poll(page))
        timer.start()
        page._seg_ext_timer = timer

    def _seg_log(self, page, text) -> None:
        """Append a timestamped line to the segmentation calculation log."""
        ts = datetime.now().strftime("%H:%M:%S")
        lines = getattr(page, "_seg_log_lines", None)
        if lines is None:
            lines = []
            page._seg_log_lines = lines
        for line in text.splitlines():
            if line.strip():
                lines.append(f"[{ts}] {line}")
        box = getattr(page, "_seg_calc_log", None)
        if box is not None:
            for line in text.splitlines():
                if line.strip():
                    box.appendPlainText(f"[{ts}] {line}")
        page._seg_log_last_is_tile = False

    def _seg_log_tile(self, page, i, total) -> None:
        """Update the in-progress tile line in the log (replace in place)."""
        ts = datetime.now().strftime("%H:%M:%S")
        text = f"[{ts}] tile {i}/{total}"
        lines = getattr(page, "_seg_log_lines", None)
        if lines is None:
            lines = []
            page._seg_log_lines = lines
        if getattr(page, "_seg_log_last_is_tile", False) and lines:
            lines[-1] = text
        else:
            lines.append(text)
        box = getattr(page, "_seg_calc_log", None)
        if box is not None:
            if getattr(page, "_seg_log_last_is_tile", False):
                cursor = box.textCursor()
                cursor.movePosition(QTextCursor.MoveOperation.End)
                cursor.select(QTextCursor.SelectionType.BlockUnderCursor)
                cursor.removeSelectedText()
                cursor.insertText(text)
            else:
                box.appendPlainText(text)
        page._seg_log_last_is_tile = True

    def _seg_ext_poll(self, page) -> None:
        """Collect finished external segmentations and finalize the masks."""
        import shutil

        import numpy as np

        worker = self._ext_worker()
        status = getattr(page, "_seg_calc_status", None)
        jobs = getattr(page, "_seg_ext_jobs", None) or []
        done = getattr(page, "_seg_ext_done", None) or set()
        errors = getattr(page, "_seg_ext_errors", [])
        cells = getattr(page, "_seg_ext_cells", 0)
        report = getattr(page, "_seg_ext_report", None) or []
        tile = getattr(page, "_seg_ext_tile", None)
        activity = getattr(page, "_seg_ext_activity", "") or ""
        finished = getattr(page, "_seg_ext_finished", False)
        out_to_job = {job["output"]: job for job in jobs}

        for item in worker.poll():
            if item[1] == "line":
                line = item[2]
                if line.startswith("tile: "):
                    info = line[len("tile: "):].strip()
                    if "/" in info:
                        try:
                            cur, tot = info.split("/", 1)
                            tile = (int(cur), int(tot))
                            self._seg_log_tile(page, int(cur), int(tot))
                        except ValueError:
                            pass
                elif line.startswith("done:"):
                    body = line[len("done:"):].strip()
                    out_path, sep, meta = body.partition("|")
                    out_path = out_path.strip()
                    n_cells = 0
                    seconds = 0.0
                    for part in meta.split("|"):
                        if part.startswith("cells="):
                            try:
                                n_cells = int(part[len("cells="):])
                            except ValueError:
                                pass
                        elif part.startswith("time="):
                            try:
                                seconds = float(part[len("time="):])
                            except ValueError:
                                pass
                    job = out_to_job.get(out_path)
                    if job is None or out_path in done:
                        continue
                    parquet_path = job["parquet"]
                    try:
                        arr = np.load(out_path)
                        if arr.ndim != 2:
                            raise ValueError("bad mask shape")
                        rel = self._seg_write_mask(
                            page._seg_task_id, parquet_path, arr
                        )
                        rec = self._seg_mask_record_live(
                            page, parquet_path, create=True
                        )
                        rec["path"] = rel
                        rec["source"] = "builtin"
                        rec["state"] = SEG_IMPORT_DONE
                        cells += int(arr.max())
                        report.append(
                            f"{self._comp_file_name(parquet_path, page._seg_task_id)}: "
                            f"{n_cells} cells, {seconds:.1f}s"
                        )
                        self._seg_log(
                            page,
                            f"✓ {self._comp_file_name(parquet_path, page._seg_task_id)}: "
                            f"{n_cells} cells, {seconds:.1f}s",
                        )
                    except Exception as exc:  # noqa: BLE001
                        errors.append(f"{self._comp_file_name(parquet_path, page._seg_task_id)}: {exc}")
                        self._seg_log(page, f"✗ {self._comp_file_name(parquet_path, page._seg_task_id)}: {exc}")
                    done.add(out_path)
                else:
                    # Non-progress output (e.g. TensorFlow/model loading lines):
                    # remember the latest for the status, and record it in the
                    # scrollable log so the user can see and copy the details.
                    if line.strip():
                        activity = line.strip()[-120:]
                        self._seg_log(page, line)
                continue
            if len(item) != 4 or item[1] != "done":
                continue
            key, _tag, code, text = item[0], item[1], item[2], item[3]
            if not (isinstance(key, tuple) and key[0] == "seg-batch"):
                continue
            finished = True
            for job in jobs:
                if job["output"] in done:
                    continue
                if code != 0:
                    errors.append(
                        f"{self._comp_file_name(job['parquet'], page._seg_task_id)}: "
                        f"{text.strip()[-200:]}"
                    )
                else:
                    errors.append(
                        f"{self._comp_file_name(job['parquet'], page._seg_task_id)}: no output produced"
                    )
                done.add(job["output"])
            if text and code != 0:
                self._seg_log(page, text.rstrip())

        page._seg_ext_done = done
        page._seg_ext_errors = errors
        page._seg_ext_cells = cells
        page._seg_ext_report = report
        page._seg_ext_tile = tile
        page._seg_ext_activity = activity
        page._seg_ext_finished = finished
        if finished:
            page._seg_ext_running = False

        if not finished:
            if status is not None:
                start = getattr(page, "_seg_ext_start_time", None)
                elapsed = int(time.monotonic() - start) if start else 0
                minutes, seconds = divmod(elapsed, 60)
                elapsed_str = (
                    f"{minutes}m {seconds}s" if minutes else f"{seconds}s"
                )
                stamp = f"[{datetime.now().strftime('%H:%M:%S')} · {elapsed_str}]"
                msg = f"{stamp} Running… {len(done)}/{len(jobs)} file(s) done"
                if tile is not None:
                    msg += f" — tile {tile[0]}/{tile[1]}"
                elif activity:
                    msg += f" — {activity}"
                status.setText(msg)
            return

        timer = getattr(page, "_seg_ext_timer", None)
        if timer is not None:
            timer.stop()
        shutil.rmtree(page._seg_ext_tmpdir, ignore_errors=True)
        ok_count = len(jobs) - len(errors)
        start = getattr(page, "_seg_ext_start_time", None)
        elapsed = int(time.monotonic() - start) if start else 0
        minutes, seconds = divmod(elapsed, 60)
        elapsed_str = f"{minutes}m {seconds}s" if minutes else f"{seconds}s"
        self._seg_log(
            page,
            f"Calculated {ok_count} mask(s) · {cells} cell(s) in {elapsed_str}.",
        )
        for err in errors:
            self._seg_log(page, f"✗ {err}")
        self._seg_after_masks_changed(page)
        self._seg_refresh_files(page)
        status = getattr(page, "_seg_calc_status", None)
        if status is not None:
            msg = f"Calculated {ok_count} mask(s) · {cells} cell(s) in {elapsed_str}."
            if report:
                msg += "\n" + "\n".join(report)
            if errors:
                msg += "\n" + "\n".join(errors)
            status.setText(msg)

    def _seg_raster_channel(self, parquet_path, channel):
        """Reconstruct one channel as a 2-D float image (or (None, error))."""
        import numpy as np
        import pandas as pd

        ent = self._ensure_image_index(parquet_path)
        if ent is None or ent.get("manifest") is None:
            return None, "no image index — re-import this file as an image"
        man = ent["manifest"]
        try:
            df = pd.read_parquet(parquet_path, columns=["x", "y", channel])
        except Exception as exc:  # noqa: BLE001
            return None, str(exc)
        xmin = float(man["xmin"])
        ymin = float(man["ymin"])
        width = int(round(float(man["xmax"]) - xmin)) + 1
        height = int(round(float(man["ymax"]) - ymin)) + 1
        xi = np.rint(df["x"].to_numpy(dtype="float64") - xmin).astype(np.int64)
        yi = np.rint(df["y"].to_numpy(dtype="float64") - ymin).astype(np.int64)
        values = pd.to_numeric(df[channel], errors="coerce").to_numpy(dtype="float64")
        image = np.zeros((height, width), dtype="float64")
        ok = (
            (xi >= 0) & (xi < width) & (yi >= 0) & (yi < height)
            & np.isfinite(values)
        )
        image[yi[ok], xi[ok]] = values[ok]
        if values[ok].size == 0:
            return None, "no finite pixel values"
        return image, None

    def _seg_nuclear_expansion(self, parquet_path, params):
        """Threshold → label → filter → expand. Returns (mask, error)."""
        import numpy as np
        from scipy import ndimage

        channel = params.get("channel")
        if not channel:
            return None, "no nucleus channel"
        image, err = self._seg_raster_channel(parquet_path, channel)
        if image is None:
            return None, err

        if params.get("threshold_mode") == "manual":
            threshold = float(params.get("threshold", 0.0))
        else:
            threshold = _otsu_threshold(image)
        binary = image > threshold
        if not binary.any():
            return None, "threshold produced an empty mask"
        binary = ndimage.binary_opening(binary, structure=np.ones((3, 3)))
        labels, _count = ndimage.label(binary)
        labels = _relabel_sequential(labels, int(params.get("min_area", 1)))
        expand = int(params.get("expand", 0))
        if expand > 0 and labels.any():
            distance, (iy, ix) = ndimage.distance_transform_edt(
                labels == 0, return_indices=True
            )
            grown = distance <= expand
            labels = np.where(grown, labels[iy, ix], labels)
        return labels.astype(np.int32), None

    def _seg_mark_dirty(self, page) -> None:
        page._seg_dirty = True
        self._seg_update_save_btn(page)
        self._module_set_state(page, MODULE_STATE_MODIFIED)

    def _seg_update_save_btn(self, page) -> None:
        page._seg_save_btn.setEnabled(page._seg_dirty and not page._seg_locked)

    def _seg_save_now(self, page) -> None:
        params = page._seg_params
        column = (params.get("column") or "Mask").strip() or "Mask"
        expose = params.get("expose") or {}
        # The mask column must not collide with a real column name of a file
        # that is exposed (checked) in this module — unchecked files don't
        # publish a mask column, so their names don't matter here.
        taken = set()
        for path in self._seg_file_rows(page):
            if not expose.get(path):
                continue
            for name in self._column_index.get(self._rel_data_key(path), []):
                taken.add(name)
        if column in taken:
            QMessageBox.warning(
                self,
                "Mask column",
                f'"{column}" is already a column of the selected files.\n'
                "Choose another name.",
            )
            return
        params["column"] = column
        applied = {}
        for path in self._seg_file_rows(page):
            if not expose.get(path):
                continue
            rec = self._seg_mask_record(params, path)
            mask_path = self._seg_mask_file(rec)
            if mask_path is None:
                continue
            applied[path] = self._seg_signature(mask_path)
        params["applied"] = applied
        page._seg_applied_snapshot = dict(applied)
        page._seg_task_def["params"] = params
        if self.project is not None:
            self.project.save()
        page._seg_snapshot = copy.deepcopy(params)
        page._seg_dirty = False
        self._seg_update_save_btn(page)
        self._seg_refresh_status(page)
        self._seg_value_cache = {}
        self.statusBar().showMessage("Segmentation saved")
        self._module_saved(page)

    def _seg_close(self, page) -> None:
        if getattr(page, "_seg_ext_running", False):
            reply = QMessageBox.question(
                self,
                "Close Segmentation",
                "A calculation is still running.\n"
                "Closing the module now will interrupt it. Continue?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return
            self._ext_worker().kill()
        if page._seg_dirty:
            reply = QMessageBox.question(
                self,
                "Close Segmentation",
                "There are unsaved changes.\nClose without saving? Unsaved changes will be lost.",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return
            page._seg_task_def["params"] = page._seg_snapshot
        for name in ("_seg_overlay_timer", "_seg_ext_timer"):
            timer = getattr(page, name, None)
            if timer is not None:
                timer.stop()
        self._close_module_page(page)

    # --- segmentation preview (part 3) and plot settings (part 4)
    def _seg_preview_panel(self, page) -> QWidget:
        import pyqtgraph as pg

        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        lay.addWidget(QLabel("<b>Preview</b>"))
        body = QWidget()
        bh = QHBoxLayout(body)
        bh.setContentsMargins(0, 0, 0, 0)
        bh.setSpacing(4)
        plot = pg.PlotWidget(background=_plot_background())
        plot.showGrid(x=True, y=True, alpha=0.2)
        plot.getPlotItem().setAxisItems({
            "bottom": _make_sci_axis("bottom"),
            "left": _make_sci_axis("left"),
        })
        bh.addWidget(plot, 1)
        legend = self._figure_attach_legend(plot)
        bh.addWidget(legend, 0)
        lay.addWidget(body, 1)
        page._seg_preview_plot = plot
        # Re-render both the image (LOD raster for the new view) and the mask
        # overlay when the user zooms or pans.
        timer = QTimer(self)
        timer.setSingleShot(True)
        timer.setInterval(30)
        timer.timeout.connect(lambda: self._seg_render_preview(page))
        page._seg_overlay_timer = timer
        plot.getPlotItem().getViewBox().sigRangeChanged.connect(
            lambda *_: timer.start()
        )
        return panel

    def _seg_plot_settings_panel(self, page) -> QWidget:
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        lay.addWidget(QLabel("<b>Plot settings</b>"))
        host = QWidget()
        host.setLayout(QVBoxLayout())
        host.layout().setContentsMargins(0, 0, 0, 0)
        host.layout().setSpacing(6)
        lay.addWidget(host, 1)
        page._seg_settings_host = host
        return panel

    def _seg_plot_dict(self, page) -> dict:
        """The preview's plot config, defaulted for the current files."""
        plot_dict = page._seg_params.setdefault("plot", {})
        rows = self._seg_file_rows(page)
        if not rows:
            return plot_dict
        if plot_dict.get("file") not in rows:
            fresh = self._seg_default_plot(rows[0], page._seg_task_id)
            fresh.update({k: v for k, v in plot_dict.items() if k != "file"})
            plot_dict.clear()
            plot_dict.update(fresh)
        if not plot_dict.get("type"):
            plot_dict["type"] = "image"
        if not plot_dict.get("layers") and plot_dict.get("color_param"):
            channel = plot_dict["color_param"]
            plot_dict["layers"] = [{
                "parameter": channel,
                "color": (255, 255, 255),
                "name": str(channel),
                "visible": True,
            }]
        plot_dict.setdefault("show_legend", True)
        return plot_dict

    def _seg_refresh_plot_settings(self, page) -> None:
        """Rebuild part 4 (file/channel/mask options) from the current files."""
        host = getattr(page, "_seg_settings_host", None)
        if host is None:
            return
        self._clear_settings_layout(host.layout())
        lay = host.layout()
        enabled = not page._seg_locked
        plot_dict = self._seg_plot_dict(page)
        rows = [p for p in self._seg_file_rows(page)
                if self._seg_mask_file(self._seg_mask_record(page._seg_params, p))]

        lay.addWidget(QLabel("File"))
        file_combo = _NoWheelComboBox()
        for path in rows:
            file_combo.addItem(self._comp_file_name(path, page._seg_task_id), path)
        idx = file_combo.findData(plot_dict.get("file"))
        if idx >= 0:
            file_combo.setCurrentIndex(idx)
        file_combo.setEnabled(enabled and bool(rows))
        lay.addWidget(file_combo)

        columns = []
        rec = self._figure_record(plot_dict.get("file"))
        if rec is not None:
            columns = self._columns_for(rec.get("parquet"), page._seg_task_id)

        self._figure_image_layer_settings(
            lay, plot_dict, columns, enabled,
            on_change=lambda: self._seg_render_preview(page),
            on_rebuild=lambda: (
                self._seg_refresh_plot_settings(page),
                self._seg_render_preview(page),
            ),
            task_id=page._seg_task_id,
        )

        lay.addWidget(QLabel("Mask display"))
        mode_combo = _NoWheelComboBox()
        mode_combo.addItem("Don't show mask", "none")
        mode_combo.addItem("Show mask as shape", "shape")
        mode_combo.addItem("Show mask edges", "edges")
        idx = mode_combo.findData(plot_dict.get("mask_mode", "shape"))
        mode_combo.setCurrentIndex(max(0, idx))
        mode_combo.setEnabled(enabled)
        lay.addWidget(mode_combo)

        color_mode_combo = None
        alpha_spin = None
        if plot_dict.get("mask_mode", "shape") != "none":
            lay.addWidget(QLabel("Mask colors"))
            color_mode_combo = _NoWheelComboBox()
            color_mode_combo.addItem("Random colors", "random")
            color_mode_combo.addItem("Grayscale", "gray")
            idx = color_mode_combo.findData(plot_dict.get("mask_color", "random"))
            color_mode_combo.setCurrentIndex(max(0, idx))
            color_mode_combo.setEnabled(enabled)
            lay.addWidget(color_mode_combo)

            lay.addWidget(QLabel("Opacity (%)"))
            alpha_spin = _NoWheelSpinBox()
            alpha_spin.setRange(5, 100)
            alpha_spin.setValue(int(plot_dict.get("mask_alpha", 45)))
            alpha_spin.setEnabled(enabled)
            lay.addWidget(alpha_spin)

        self._figure_display_toggles(
            lay, plot_dict, enabled,
            on_change=lambda: (
                self._figure_apply_display_options(
                    plot_dict, getattr(page, "_seg_preview_plot", None)
                )
                if getattr(page, "_seg_preview_plot", None) is not None
                else self._seg_render_preview(page)
            ),
        )
        lay.addStretch(1)

        def on_file(_=0):
            path = file_combo.currentData()
            if not path:
                return
            plot_dict["file"] = path
            plot_dict["file_name"] = file_combo.currentText()
            self._seg_refresh_plot_settings(page)
            self._seg_render_preview(page)
            self._seg_mark_dirty(page)

        def on_mode(_=0):
            plot_dict["mask_mode"] = mode_combo.currentData()
            self._seg_refresh_plot_settings(page)
            self._seg_render_preview(page)
            self._seg_mark_dirty(page)

        def on_color_mode(_=0):
            plot_dict["mask_color"] = color_mode_combo.currentData()
            self._seg_render_overlay(page)
            self._seg_mark_dirty(page)

        def on_alpha(value):
            plot_dict["mask_alpha"] = int(value)
            self._seg_render_overlay(page)
            self._seg_mark_dirty(page)

        file_combo.currentIndexChanged.connect(on_file)
        mode_combo.currentIndexChanged.connect(on_mode)
        if color_mode_combo is not None:
            color_mode_combo.currentIndexChanged.connect(on_color_mode)
        if alpha_spin is not None:
            alpha_spin.valueChanged.connect(on_alpha)

    def _seg_update_preview_visibility(self, page) -> None:
        """Parts 3 and 4 appear once at least one file has a mask."""
        has_mask = self._seg_any_mask(page)
        panel3 = getattr(page, "_seg_preview_panel", None)
        panel4 = getattr(page, "_seg_settings_panel", None)
        for panel in (panel3, panel4):
            if panel is not None:
                panel.setVisible(has_mask)
        if has_mask:
            self._seg_render_preview(page)

    def _seg_render_preview(self, page) -> None:
        plot = getattr(page, "_seg_preview_plot", None)
        if plot is None:
            return
        plot_dict = self._seg_plot_dict(page)
        rec = self._figure_record(plot_dict.get("file"))
        if rec is None:
            return
        self._figure_render(plot_dict, plot, task_id=page._seg_task_id)
        self._seg_render_overlay(page)

    def _seg_render_overlay(self, page) -> None:
        """Draw the mask overlay on top of the preview image."""
        import numpy as np
        import pyqtgraph as pg

        plot = getattr(page, "_seg_preview_plot", None)
        if plot is None:
            return
        plot_dict = self._seg_plot_dict(page)
        old = getattr(page, "_seg_overlay_item", None)
        if old is not None:
            try:
                plot.removeItem(old)
            except Exception:  # noqa: BLE001
                pass
            page._seg_overlay_item = None
        mode = plot_dict.get("mask_mode", "shape")
        if mode == "none":
            return
        parquet_path = plot_dict.get("file")
        rec = self._seg_mask_record(page._seg_params, parquet_path)
        mask_path = self._seg_mask_file(rec)
        if mask_path is None:
            return
        ent = self._ensure_image_index(parquet_path)
        if ent is None or ent.get("manifest") is None:
            return
        man = ent["manifest"]
        vb = plot.getPlotItem().getViewBox()
        xr = vb.viewRange()[0]
        yr = vb.viewRange()[1]
        x0, x1 = min(xr), max(xr)
        y0, y1 = min(yr), max(yr)
        if x1 <= x0 or y1 <= y0:
            return
        xmin, ymin = float(man["xmin"]), float(man["ymin"])
        i0 = max(0, int(np.floor(x0 - xmin)))
        i1 = min(int(round(float(man["xmax"]) - xmin)) + 1, int(np.ceil(x1 - xmin)))
        j0 = max(0, int(np.floor(y0 - ymin)))
        j1 = min(int(round(float(man["ymax"]) - ymin)) + 1, int(np.ceil(y1 - ymin)))
        if i1 <= i0 or j1 <= j0:
            return
        mask = self._seg_load_mask(mask_path)
        if mask is None:
            return
        i1 = min(i1, mask.shape[1])
        j1 = min(j1, mask.shape[0])
        step = max(1, int(round((x1 - x0) / max(1, plot.width()))))
        crop = mask[j0:j1:step, i0:i1:step].astype(np.int64)
        if crop.size == 0:
            return
        max_label = int(crop.max())
        if max_label <= 0:
            return
        # Per-label colors: grayscale or a stable random palette.
        if plot_dict.get("mask_color") == "random":
            rng = np.random.default_rng(20240521)
            lut = rng.integers(60, 256, size=(max_label + 1, 3))
            lut[0] = 0
        else:
            ramp = np.linspace(0.35, 1.0, max(1, max_label + 1))
            lut = np.stack(
                [ramp * 255.0, ramp * 255.0, ramp * 255.0], axis=1
            ).astype(np.int64)
        if mode == "edges":
            edges_full = self._seg_edge_map(mask_path)
            if edges_full is None:
                return
            edge = edges_full[j0:j1:step, i0:i1:step]
            neighbor = np.zeros_like(crop)
            neighbor[:-1, :] = np.maximum(neighbor[:-1, :], crop[1:, :])
            neighbor[1:, :] = np.maximum(neighbor[1:, :], crop[:-1, :])
            neighbor[:, :-1] = np.maximum(neighbor[:, :-1], crop[:, 1:])
            neighbor[:, 1:] = np.maximum(neighbor[:, 1:], crop[:, :-1])
            label_for_color = np.where(crop > 0, crop, neighbor)
            alpha = np.where(edge, 255, 0)
        else:
            label_for_color = crop
            alpha = np.where(crop > 0, 255, 0)
        opacity = max(0, min(100, int(plot_dict.get("mask_alpha", 45))))
        rgba = np.zeros((crop.shape[0], crop.shape[1], 4), dtype=np.uint8)
        clipped = np.clip(label_for_color, 0, max_label)
        rgba[..., 0:3] = lut[clipped]
        rgba[..., 3] = (alpha * opacity / 100.0).astype(np.uint8)
        item = pg.ImageItem(axisOrder="row-major")
        item.setImage(rgba, autoLevels=False)
        item.setRect(QRectF(
            xmin + i0 * step, ymin + j0 * step,
            crop.shape[1] * step, crop.shape[0] * step,
        ))
        item.setZValue(10)
        plot.addItem(item)
        page._seg_overlay_item = item

    # ----- feature module (generate) ------------------------------------
    def _build_feature_page(self, name: str, task_def: dict, locked: bool) -> QWidget:
        """Build the Feature page: files (1) | aggregation rules (3) | log."""
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        # Toolbar with Save/Close.
        bar = QFrame()
        bar.setObjectName("moduleBar")
        tl = QHBoxLayout(bar)
        tl.setContentsMargins(12, 6, 12, 6)
        tl.setSpacing(4)
        tl.addWidget(QLabel(f"<b>{self._module_display_title(task_def.get('id'), name)}</b>"))
        if locked:
            lock_icon = QLabel()
            lock_icon.setPixmap(_lock_pixmap())
            lock_icon.setFixedSize(14, 14)
            lock_icon.setToolTip("Locked — a downstream generate module has saved data")
            tl.addWidget(lock_icon)
            draft = QLabel("Draft (locked)")
            draft.setStyleSheet("color: #b58900; font-weight: bold;")
            tl.addWidget(draft)
        tl.addStretch()
        save_btn = QPushButton("Save")
        save_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        save_btn.setEnabled(not locked)
        close_btn = QPushButton("Close")
        close_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        close_btn.clicked.connect(lambda _=False: self._feat_close(page))
        tl.addWidget(save_btn)
        tl.addWidget(close_btn)
        layout.addWidget(bar)

        params = task_def.setdefault("params", {})
        params.setdefault("feature", None)
        params.setdefault("files", [])
        params.setdefault("rules", [])
        params.setdefault("outputs", {})
        params.setdefault("log", [])
        # The first rule is always Count; it cannot be deleted.
        rules = params.get("rules") or []
        if not rules or (rules[0].get("method") != "count"):
            rules = [{"source": None, "method": "count", "lo": 0, "hi": 100,
                      "perc": None, "name": "count"}] + [
                r for r in rules if r.get("method") != "count"
            ]
            params["rules"] = rules
        page._feat_task_def = task_def
        page._feat_task_id = task_def.get("id")
        page._feat_params = params
        page._feat_locked = locked
        page._feat_save_btn = save_btn
        page._feat_dirty = False
        page._feat_snapshot = copy.deepcopy(params)
        page._feat_log_lines = list(params.get("log") or [])
        page._feat_running = False
        page._feat_cancel = False
        save_btn.clicked.connect(lambda _=False: self._feat_save_now(page))

        content = QWidget()
        content.setStyleSheet("background: #f5f8fb;")
        row = QVBoxLayout(content)
        row.setContentsMargins(12, 12, 12, 12)
        row.setSpacing(10)

        splitter = QSplitter(Qt.Orientation.Horizontal)
        splitter.setChildrenCollapsible(False)
        splitter.addWidget(self._feat_files_panel(page))
        splitter.addWidget(self._feat_rules_panel(page))
        splitter.setStretchFactor(0, 1)
        splitter.setStretchFactor(1, 3)
        splitter.setSizes([320, 880])
        row.addWidget(splitter, 1)

        row.addWidget(self._feat_log_panel(page))
        layout.addWidget(content, 1)

        self._feat_refresh_files(page)
        self._feat_update_save_btn(page)
        return page

    def _feat_log_panel(self, page) -> QWidget:
        """Timestamped log area shared by the whole module."""
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        lay.addWidget(QLabel("<b>Log</b>"))
        log = QPlainTextEdit()
        log.setReadOnly(True)
        log.setPlaceholderText("Calculation output appears here…")
        log.setStyleSheet(
            "background: #1e1e1e; color: #d4d4d4; "
            "font-family: Consolas, monospace; font-size: 9pt;"
        )
        log.setFixedHeight(120)
        for line in getattr(page, "_feat_log_lines", []):
            log.appendPlainText(line)
        lay.addWidget(log)
        page._feat_log = log
        return panel

    def _feat_log(self, page, text) -> None:
        """Append a timestamped line to the Feature log (persisted with the module)."""
        ts = datetime.now().strftime("%H:%M:%S")
        lines = getattr(page, "_feat_log_lines", None)
        if lines is None:
            lines = []
            page._feat_log_lines = lines
        for line in str(text).splitlines():
            if line.strip():
                lines.append(f"[{ts}] {line}")
        # Keep the log bounded, then store it in the module's params so it is
        # saved with the project and shown again when the module is reopened.
        if len(lines) > _FEATURE_LOG_LIMIT:
            del lines[:-_FEATURE_LOG_LIMIT]
        if getattr(page, "_feat_params", None) is not None:
            page._feat_params["log"] = list(lines)
        box = getattr(page, "_feat_log", None)
        if box is not None:
            for line in str(text).splitlines():
                if line.strip():
                    box.appendPlainText(f"[{ts}] {line}")

    def _feat_all_columns(self, page) -> list:
        """Every column visible at this module (union across available files)."""
        columns = []
        for rec in self._available_files(page._feat_task_id):
            for name in self._columns_for(rec.get("parquet"), page._feat_task_id):
                if name not in columns:
                    columns.append(name)
        return columns

    def _feat_file_columns(self, page, parquet_path) -> list:
        return self._columns_for(parquet_path, page._feat_task_id)

    def _feat_common_columns(self, page) -> list:
        """Columns shared by every selected file (rule sources must exist in all)."""
        files = list(page._feat_params.get("files") or [])
        if not files:
            return []
        common = set(self._feat_file_columns(page, files[0]))
        for path in files[1:]:
            common &= set(self._feat_file_columns(page, path))
        return sorted(common)

    def _feat_files_panel(self, page) -> QWidget:
        """Left panel: feature variable, file picker and per-file status."""
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        lay.addWidget(QLabel("<b>Feature variable</b>"))

        combo = _NoWheelComboBox()
        combo.addItem("", None)
        for name in self._feat_all_columns(page):
            combo.addItem(name, name)
        idx = combo.findData(page._feat_params.get("feature"))
        if idx >= 0:
            combo.setCurrentIndex(idx)
        combo.setEnabled(not page._feat_locked)
        lay.addWidget(combo)
        page._feat_column_combo = combo

        lay.addWidget(QLabel("Data files"))
        select_btn = QPushButton("Select files…")
        select_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        select_btn.setEnabled(not page._feat_locked)
        lay.addWidget(select_btn)

        table = QTableWidget()
        table.setColumnCount(2)
        table.setHorizontalHeaderLabels(["File", "Status"])
        header = table.horizontalHeader()
        header.setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
        header.setSectionResizeMode(1, QHeaderView.ResizeMode.ResizeToContents)
        table.verticalHeader().setVisible(False)
        table.verticalHeader().setDefaultSectionSize(26)
        table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        table.setSelectionMode(QAbstractItemView.SelectionMode.NoSelection)
        table.setStyleSheet("QTableWidget { background: #ffffff; border: none; }")
        lay.addWidget(table, 1)
        page._feat_files_table = table

        def on_column_changed(_=0):
            page._feat_params["feature"] = combo.currentData()
            # Keep only the files that contain the chosen feature variable.
            feature = page._feat_params["feature"]
            if feature:
                files = [
                    p for p in page._feat_params.get("files") or []
                    if feature in self._feat_file_columns(page, p)
                ]
                page._feat_params["files"] = files
            self._feat_refresh_files(page)
            self._feat_mark_dirty(page)

        combo.currentIndexChanged.connect(on_column_changed)
        select_btn.clicked.connect(lambda _=False: self._feat_select_files(page))
        return panel

    def _feat_select_files(self, page) -> None:
        """Pick the data files this module aggregates."""
        feature = page._feat_params.get("feature")
        if not feature:
            QMessageBox.information(
                self, "Select files", "Choose the feature variable first."
            )
            return
        candidates = [
            rec for rec in self._available_files(page._feat_task_id)
            if feature in self._feat_file_columns(page, rec.get("parquet"))
        ]
        names = [rec.get("name", "") for rec in candidates]
        by_name = {rec.get("name", ""): rec.get("parquet") for rec in candidates}
        current = [self._comp_file_name(p, page._feat_task_id) for p in page._feat_params.get("files") or []]
        chosen = self._pick_items_dialog(
            "Select data files", names, current, "Filter files..."
        )
        if chosen is None:
            return
        files = []
        for name in chosen:
            path = by_name.get(name)
            if path and path not in files:
                files.append(path)
        page._feat_params["files"] = files
        self._feat_refresh_files(page)
        self._feat_mark_dirty(page)

    def _feat_file_status(self, page, parquet_path) -> str:
        """'Calculated' only when a current, matching output exists for the file."""
        params = page._feat_params
        rec = (params.get("outputs") or {}).get(parquet_path)
        if not isinstance(rec, dict) or not rec.get("path"):
            return FEATURE_STATUS_PENDING
        if self.project is None:
            return FEATURE_STATUS_PENDING
        path = self.project.path / rec["path"]
        if not path.is_file():
            return FEATURE_STATUS_PENDING
        if rec.get("signature") != self._feature_signature(params, parquet_path):
            return FEATURE_STATUS_PENDING
        return FEATURE_STATUS_DONE

    def _feat_refresh_files(self, page) -> None:
        """Rebuild the file status table and the rules table."""
        table = getattr(page, "_feat_files_table", None)
        if table is not None:
            files = list(page._feat_params.get("files") or [])
            table.blockSignals(True)
            table.setRowCount(len(files))
            for i, path in enumerate(files):
                name_item = QTableWidgetItem(self._comp_file_name(path, page._feat_task_id))
                name_item.setFlags(Qt.ItemFlag.ItemIsEnabled)
                table.setItem(i, 0, name_item)
                status = self._feat_file_status(page, path)
                sitem = QTableWidgetItem(status)
                sitem.setFlags(Qt.ItemFlag.ItemIsEnabled)
                sitem.setForeground(
                    QColor("#1a7f37") if status == FEATURE_STATUS_DONE
                    else QColor("#9aa0a6")
                )
                table.setItem(i, 1, sitem)
            table.blockSignals(False)
        self._feat_rebuild_rules(page)

    def _feat_rules_panel(self, page) -> QWidget:
        """Right panel: the 4-column aggregation rules table."""
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        lay.addWidget(QLabel("<b>Aggregation rules</b>"))

        table = QTableWidget()
        table.setColumnCount(4)
        table.setHorizontalHeaderLabels(
            ["Source variable", "Method", "Range (% per class)", "New column name"]
        )
        header = table.horizontalHeader()
        for column in range(4):
            header.setSectionResizeMode(column, QHeaderView.ResizeMode.Stretch)
        table.verticalHeader().setVisible(False)
        table.verticalHeader().setDefaultSectionSize(34)
        table.setStyleSheet("QTableWidget { background: #ffffff; border: none; }")
        lay.addWidget(table, 1)
        page._feat_rules_table = table

        note = QLabel(
            "Range (% per class): for each class, use only the points between "
            "these two percentiles, sorted by the row's own source variable. "
            "0–100 means all points (e.g. 0–30 = dimmest 30%, 90–100 = "
            "brightest 10%). The Count row always uses all points."
        )
        note.setWordWrap(True)
        note.setStyleSheet("color: #6b7785;")
        lay.addWidget(note)

        btns = QHBoxLayout()
        add_btn = QPushButton("Add")
        add_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        add_btn.setEnabled(not page._feat_locked)
        del_btn = QPushButton("Delete")
        del_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        del_btn.setEnabled(not page._feat_locked)
        btns.addWidget(add_btn)
        btns.addWidget(del_btn)
        btns.addStretch()
        lay.addLayout(btns)

        calc_btn = QPushButton("Calculate")
        calc_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        calc_btn.setEnabled(not page._feat_locked)
        lay.addWidget(calc_btn)
        status = QLabel("")
        status.setStyleSheet("color: #6b7785;")
        status.setWordWrap(True)
        lay.addWidget(status)
        page._feat_calc_btn = calc_btn
        page._feat_calc_status = status

        def on_add():
            page._feat_params["rules"].append(
                {"source": None, "method": "mean", "lo": 0, "hi": 100,
                 "perc": None, "name": ""}
            )
            self._feat_refresh_rules(page)
            self._feat_mark_dirty(page)

        def on_delete():
            row = table.currentRow()
            rules = page._feat_params["rules"]
            if row <= 0 or row >= len(rules):
                if row == 0:
                    QMessageBox.information(
                        self, "Delete", "The Count row is fixed and cannot be deleted."
                    )
                return
            del rules[row]
            self._feat_refresh_rules(page)
            self._feat_mark_dirty(page)

        add_btn.clicked.connect(lambda _=False: on_add())
        del_btn.clicked.connect(lambda _=False: on_delete())
        calc_btn.clicked.connect(lambda _=False: self._feat_calculate(page))
        return panel

    def _feat_rebuild_rules(self, page) -> None:
        """Rebuild the rules table widgets from params (without losing edits)."""
        table = getattr(page, "_feat_rules_table", None)
        if table is None:
            return
        params = page._feat_params
        rules = params.get("rules") or []
        common = self._feat_common_columns(page)
        enabled = not page._feat_locked

        table.blockSignals(True)
        # Clear via row count so old cell widgets are destroyed too (items are
        # cleared by clearContents, cell widgets are not).
        table.setRowCount(0)
        table.setRowCount(len(rules))

        def mark():
            self._feat_mark_dirty(page)
            self._feat_refresh_statuses(page)

        def rebuild_soon():
            # Rebuilding the table destroys the widget whose signal we are
            # handling, so defer the rebuild to the next event-loop turn.
            QTimer.singleShot(0, lambda: self._feat_rebuild_rules(page))

        for i, rule in enumerate(rules):
            is_count = rule.get("method") == "count"

            # Column 0: source variable (fixed label for Count).
            if is_count:
                item = QTableWidgetItem("(all rows)")
                item.setFlags(Qt.ItemFlag.ItemIsEnabled)
                item.setForeground(QColor("#6b7785"))
                table.setItem(i, 0, item)
            else:
                combo = _NoWheelComboBox()
                combo.addItem("", None)
                names = list(common)
                if rule.get("source") and rule["source"] not in names:
                    names.append(rule["source"])
                for name in names:
                    combo.addItem(name, name)
                idx = combo.findData(rule.get("source"))
                combo.setCurrentIndex(max(0, idx))
                combo.setEnabled(enabled)

                def on_source(value, r=rule):
                    old_auto = self._feat_auto_name(r)
                    r["source"] = value
                    current = (r.get("name") or "").strip()
                    if not current or current == old_auto:
                        r["name"] = self._feat_auto_name(r)
                    rebuild_soon()
                    mark()

                combo.currentIndexChanged.connect(
                    lambda _=0, c=combo, cb=on_source: cb(c.currentData())
                )
                table.setCellWidget(i, 0, combo)

            # Column 1: method (+ percentile value when relevant).
            method_box = QWidget()
            mh = QHBoxLayout(method_box)
            mh.setContentsMargins(0, 0, 0, 0)
            mh.setSpacing(4)
            method_combo = _NoWheelComboBox()
            for label, key in FEATURE_METHODS:
                method_combo.addItem(label, key)
            midx = method_combo.findData(rule.get("method", "mean"))
            method_combo.setCurrentIndex(max(0, midx))
            percent_spin = None
            if is_count:
                method_combo.setEnabled(False)
            else:
                def on_method(value, r=rule):
                    r["method"] = value
                    rebuild_soon()
                    mark()
                method_combo.currentIndexChanged.connect(
                    lambda _=0, c=method_combo, cb=on_method: cb(c.currentData())
                )
            mh.addWidget(method_combo)
            if rule.get("method") == "percentile":
                percent_spin = _NoWheelSpinBox()
                percent_spin.setRange(0, 100)
                percent_spin.setSingleStep(1)
                percent_spin.setValue(int(rule.get("perc") or 50))
                percent_spin.setEnabled(enabled)
                percent_spin.setFixedWidth(76)
                percent_spin.setToolTip("Percentile to compute within each class")

                def on_perc(value, r=rule):
                    r["perc"] = int(value)
                    mark()

                percent_spin.valueChanged.connect(
                    lambda v, cb=on_perc: cb(v)
                )
                mh.addWidget(percent_spin)
            table.setCellWidget(i, 1, method_box)

            # Column 2: in-class percentile range.
            range_box = QWidget()
            rh = QHBoxLayout(range_box)
            rh.setContentsMargins(0, 0, 0, 0)
            rh.setSpacing(4)
            lo_spin = _NoWheelSpinBox()
            hi_spin = _NoWheelSpinBox()
            for spin, value in ((lo_spin, rule.get("lo", 0)),
                                (hi_spin, rule.get("hi", 100))):
                spin.setRange(0, 100)
                spin.setSingleStep(1)
                spin.setValue(int(value))
                spin.setFixedWidth(72)
                spin.setEnabled(enabled and not is_count)
            if is_count:
                tip = "Not used by the Count row (always counts all points)"
            else:
                tip = ("Use only the points between these percentiles within "
                       "each class (sorted by this row's source variable)")
            lo_spin.setToolTip(tip)
            hi_spin.setToolTip(tip)

            def on_range(_=0, r=rule, lo=lo_spin, hi=hi_spin):
                if r.get("method") == "count":
                    return
                r["lo"] = int(lo.value())
                r["hi"] = int(hi.value())
                mark()

            lo_spin.valueChanged.connect(lambda v, cb=on_range: cb())
            hi_spin.valueChanged.connect(lambda v, cb=on_range: cb())
            rh.addWidget(lo_spin)
            rh.addWidget(QLabel("–"))
            rh.addWidget(hi_spin)
            table.setCellWidget(i, 2, range_box)

            # Column 3: new column name.
            if is_count:
                # Default 'count'; resolved to count_1, count_2… on a clash.
                rule["name"] = self._feat_count_name(params)
            name_edit = QLineEdit(str(rule.get("name") or self._feat_auto_name(rule)))
            name_edit.setEnabled(enabled)

            def on_name(text, r=rule):
                r["name"] = text.strip()
                mark()

            name_edit.textEdited.connect(lambda t, cb=on_name: cb(t))
            table.setCellWidget(i, 3, name_edit)

        table.blockSignals(False)

    def _feat_refresh_rules(self, page) -> None:
        """Rebuild the rules table after a structural change."""
        self._feat_rebuild_rules(page)

    def _feat_auto_name(self, rule) -> str:
        """Default new-column name: <source>_<method> (or 'count')."""
        if rule.get("method") == "count":
            return "count"
        source = rule.get("source") or "value"
        method = rule.get("method") or "mean"
        if method == "percentile":
            perc = rule.get("perc")
            suffix = f"p{int(perc)}" if perc else "p"
        else:
            suffix = method
        return f"{source}_{suffix}"

    def _feat_refresh_statuses(self, page) -> None:
        """Update only the status column of the file table."""
        table = getattr(page, "_feat_files_table", None)
        if table is None:
            return
        files = list(page._feat_params.get("files") or [])
        for i, path in enumerate(files):
            if i >= table.rowCount():
                break
            status = self._feat_file_status(page, path)
            item = table.item(i, 1)
            if item is None:
                item = QTableWidgetItem()
                item.setFlags(Qt.ItemFlag.ItemIsEnabled)
                table.setItem(i, 1, item)
            item.setText(status)
            item.setForeground(
                QColor("#1a7f37") if status == FEATURE_STATUS_DONE
                else QColor("#9aa0a6")
            )

    def _feat_mark_dirty(self, page) -> None:
        page._feat_dirty = True
        self._feat_update_save_btn(page)
        self._module_set_state(page, MODULE_STATE_MODIFIED)
        if getattr(page, "_feat_calc_status", None) is not None:
            page._feat_calc_status.setText("")

    def _feat_update_save_btn(self, page) -> None:
        btn = getattr(page, "_feat_save_btn", None)
        if btn is not None:
            btn.setEnabled(page._feat_dirty and not page._feat_locked)

    def _feat_save_now(self, page) -> None:
        """Persist the module's settings without recomputing."""
        params = page._feat_params
        page._feat_task_def["params"] = params
        if self.project is not None:
            self.project.save()
        page._feat_snapshot = copy.deepcopy(params)
        page._feat_dirty = False
        self._feat_update_save_btn(page)
        self._feat_log(page, "Settings saved")
        self.statusBar().showMessage("Feature settings saved")
        self._module_saved(page)

    def _feat_validate(self, page):
        """Return (ok, message) for the current settings."""
        params = page._feat_params
        if not params.get("feature"):
            return False, "Choose the feature variable first."
        if not params.get("files"):
            return False, "Select at least one data file."
        rules = params.get("rules") or []
        if not rules:
            return False, "Add at least one aggregation rule."
        common = set(self._feat_common_columns(page))
        names = []
        for i, rule in enumerate(rules):
            if rule.get("method") == "count":
                if i != 0:
                    return False, "Count must be the first row."
                name = (rule.get("name") or "").strip()
                if not name:
                    return False, "Give the Count row a column name."
                names.append(name)
                continue
            source = rule.get("source")
            if not source:
                return False, f"Row {i + 1}: choose a source variable."
            if source not in common:
                return False, (
                    f"Row {i + 1}: '{source}' is not present in every selected file."
                )
            lo = float(rule.get("lo", 0.0))
            hi = float(rule.get("hi", 100.0))
            if not (0.0 <= lo < hi <= 100.0):
                return False, (
                    f"Row {i + 1}: the range must satisfy 0 ≤ from < to ≤ 100."
                )
            if rule.get("method") == "percentile":
                perc = rule.get("perc")
                if perc is None or not (0.0 <= float(perc) <= 100.0):
                    return False, f"Row {i + 1}: the percentile must be 0–100."
            name = (rule.get("name") or "").strip()
            if not name:
                return False, f"Row {i + 1}: give the new column a name."
            names.append(name)
        if len(names) != len(set(names)):
            return False, "New column names must be unique."
        if params["feature"] in names:
            return False, (
                f"'{params['feature']}' is kept as the identifier column; "
                "choose a different new column name."
            )
        return True, ""

    def _feat_count_name(self, params) -> str:
        """The Count column name, resolved to be unique (see the module helper)."""
        return _feature_count_name(params)

    def _feat_output_stem(self, page, parquet_path) -> str:
        """Output file stem: '<source file name>_<feature>', '_new' on a clash.

        The source file's display name (the name shown in the Workflow / file
        lists) is used, not the internal parquet stem. A previous output of
        this same file is overwritten in place when the name is unchanged.
        """
        params = page._feat_params
        feature = params.get("feature") or "feature"
        outputs = params.get("outputs") or {}
        existing = outputs.get(parquet_path) if isinstance(outputs, dict) else None
        old_stem = (
            Path(existing["path"]).stem
            if isinstance(existing, dict) and existing.get("path") else None
        )
        display = self._comp_file_name(parquet_path, page._feat_task_id) or Path(str(parquet_path)).name
        base = _feature_safe_stem(f"{Path(display).stem}_{feature}")
        if old_stem == base:
            return base
        used = {
            Path(rec["path"]).stem
            for source, rec in outputs.items()
            if source != parquet_path and isinstance(rec, dict) and rec.get("path")
        }
        if self.project is not None:
            folder = self.project.path / "Module" / str(page._feat_task_id)
            if folder.is_dir():
                used |= {
                    p.stem for p in folder.glob("*.parquet") if p.stem != old_stem
                }
        stem = base
        n = 0
        while stem in used:
            n += 1
            stem = f"{base}_new" if n == 1 else f"{base}_new{n}"
        if n:
            self._feat_log(
                page,
                f"'{base}' already exists — writing as '{stem}' instead.",
            )
        return stem

    def _feat_calculate(self, page) -> None:
        """Aggregate every selected file and save the generated parquet files."""
        ok, message = self._feat_validate(page)
        if not ok:
            QMessageBox.warning(self, "Calculate", message)
            return
        params = page._feat_params
        outputs = params.get("outputs") or {}
        selected = params.get("files") or []
        existing = [p for p in selected if isinstance(outputs.get(p), dict)]
        if existing:
            reply = QMessageBox.question(
                self,
                "Calculate",
                f"{len(existing)} file(s) already have results.\n"
                "Recalculate and overwrite them?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return

        status = getattr(page, "_feat_calc_status", None)
        if status is not None:
            status.setText("Calculating…")
        QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
        done = 0
        failed = []
        page._feat_running = True
        page._feat_cancel = False
        try:
            for path in selected:
                if getattr(page, "_feat_cancel", False):
                    self._feat_log(page, "Calculation cancelled.")
                    break
                name = self._comp_file_name(path, page._feat_task_id)
                if status is not None:
                    status.setText(f"Calculating… {name}")
                QApplication.processEvents()
                previous = outputs.get(path)
                try:
                    rel, columns, warnings = self._feat_compute_file(page, path)
                except Exception as exc:  # noqa: BLE001
                    failed.append(f"{name}: {exc}")
                    self._feat_log(page, f"✗ {name}: {exc}")
                    continue
                # A renamed output (e.g. after this file's name scheme changed)
                # leaves its old parquet behind; remove it.
                if isinstance(previous, dict) and previous.get("path"):
                    if previous["path"] != rel and self.project is not None:
                        try:
                            (self.project.path / previous["path"]).unlink(
                                missing_ok=True
                            )
                        except OSError:
                            pass
                for warning in warnings:
                    self._feat_log(page, warning)
                outputs[path] = {
                    "path": rel,
                    "name": Path(rel).stem,
                    "columns": columns,
                    "signature": self._feature_signature(
                        params, path, page._feat_task_id
                    ),
                }
                done += 1
                self._feat_log(
                    page,
                    f"✓ {name} → {Path(rel).name} "
                    f"({len(columns)} column(s))",
                )
        finally:
            QApplication.restoreOverrideCursor()
            page._feat_running = False

        # Drop stale mappings for files that are no longer selected.
        for path in list(outputs.keys()):
            if path not in selected:
                outputs.pop(path, None)
        params["outputs"] = outputs
        page._feat_task_def["output"] = {"saved": bool(outputs)}
        page._feat_task_def["params"] = params
        if self.project is not None:
            self.project.save()
        page._feat_snapshot = copy.deepcopy(params)
        page._feat_dirty = False
        self._feat_update_save_btn(page)
        self._feat_refresh_files(page)

        summary = f"Calculated {done} file(s)."
        if failed:
            summary += f" {len(failed)} failed — see the log."
        if status is not None:
            status.setText(summary)
        self._feat_log(page, summary)
        self.statusBar().showMessage(summary)
        self._module_saved(page)

    def _feat_compute_file(self, page, parquet_path):
        """Aggregate one source file; return (relative path, columns, warnings)."""
        import numpy as np
        import pandas as pd

        params = page._feat_params
        feature = params["feature"]
        rules = params.get("rules") or []
        count_name = self._feat_count_name(params)
        sources = [r["source"] for r in rules if r.get("source")]

        values = self._column_data(
            page._feat_task_id, parquet_path, [feature] + sources
        )
        if feature not in values:
            raise ValueError(f"'{feature}' is missing from this file")
        data = {feature: values[feature]}
        for source in sources:
            if source not in values:
                raise ValueError(f"'{source}' is missing from this file")
            data[source] = values[source]
        df = pd.DataFrame(data)
        before = len(df)
        df = df[np.isfinite(df[feature])]
        dropped = before - len(df)
        warnings = []
        if dropped:
            warnings.append(
                f"{self._comp_file_name(parquet_path, page._feat_task_id)}: skipped {dropped} row(s) "
                f"with an empty '{feature}' value"
            )
        # A Segmentation mask labels objects 1..N and leaves the background 0.
        # Aggregating label 0 would create a huge "background object" that then
        # takes part in gating and gets painted over every background pixel
        # downstream, so it is skipped.
        if feature in self._seg_applied_columns(page._feat_task_id, parquet_path):
            background = int((df[feature] == 0).sum())
            if background:
                df = df[df[feature] != 0]
                warnings.append(
                    f"{self._comp_file_name(parquet_path, page._feat_task_id)}: "
                    f"skipped {background} background pixel(s) (mask label 0)"
                )
        if df.empty:
            raise ValueError("no rows with a valid feature value")

        out, columns, agg_warnings = _feature_aggregate_frame(
            df, feature, rules, count_name
        )
        warnings.extend(agg_warnings)

        stem = self._feat_output_stem(page, parquet_path)
        rel = f"Module/{page._feat_task_id}/{stem}.parquet"
        if self.project is None:
            raise RuntimeError("no project")
        path = self.project.path / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        out.to_parquet(path, index=False)
        return rel, columns, warnings

    def _feat_close(self, page) -> None:
        if getattr(page, "_feat_running", False):
            reply = QMessageBox.question(
                self,
                "Close Feature",
                "A calculation is still running.\n"
                "Stop it and close the module?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return
            # Stop at the next file; the page stays open until the loop ends so
            # its widgets are never destroyed mid-calculation.
            page._feat_cancel = True
            self._feat_log(page, "Stopping after the current file…")
            return
        if getattr(page, "_feat_dirty", False):
            reply = QMessageBox.question(
                self,
                "Close Feature",
                "There are unsaved changes.\nClose without saving? "
                "Unsaved changes will be lost.",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return
            # Keep the log: it is part of the module's record, not a setting.
            log_lines = list(getattr(page, "_feat_log_lines", []) or [])
            page._feat_task_def["params"] = page._feat_snapshot
            page._feat_task_def["params"]["log"] = log_lines
        self._close_module_page(page)

    # ----- gate2col module (generate) ------------------------------------
    def _build_gate2col_page(self, name: str, task_def: dict, locked: bool) -> QWidget:
        """Build the Gate2Col page: files (1) | gates table (2) | log."""
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        bar = QFrame()
        bar.setObjectName("moduleBar")
        tl = QHBoxLayout(bar)
        tl.setContentsMargins(12, 6, 12, 6)
        tl.setSpacing(4)
        tl.addWidget(QLabel(f"<b>{self._module_display_title(task_def.get('id'), name)}</b>"))
        if locked:
            lock_icon = QLabel()
            lock_icon.setPixmap(_lock_pixmap())
            lock_icon.setFixedSize(14, 14)
            lock_icon.setToolTip("Locked — a downstream generate module has saved data")
            tl.addWidget(lock_icon)
            draft = QLabel("Draft (locked)")
            draft.setStyleSheet("color: #b58900; font-weight: bold;")
            tl.addWidget(draft)
        tl.addStretch()
        save_btn = QPushButton("Save")
        save_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        save_btn.setEnabled(not locked)
        close_btn = QPushButton("Close")
        close_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        close_btn.clicked.connect(lambda _=False: self._g2c_close(page))
        tl.addWidget(save_btn)
        tl.addWidget(close_btn)
        layout.addWidget(bar)

        params = task_def.setdefault("params", {})
        params.setdefault("files", [])
        params.setdefault("rules", [])
        params.setdefault("outputs", {})
        params.setdefault("log", [])
        page._g2c_task_def = task_def
        page._g2c_task_id = task_def.get("id")
        page._g2c_params = params
        page._g2c_locked = locked
        page._g2c_save_btn = save_btn
        page._g2c_dirty = False
        page._g2c_snapshot = copy.deepcopy(params)
        page._g2c_log_lines = list(params.get("log") or [])
        page._g2c_running = False
        page._g2c_cancel = False
        save_btn.clicked.connect(lambda _=False: self._g2c_save_now(page))

        content = QWidget()
        content.setStyleSheet("background: #f5f8fb;")
        row = QVBoxLayout(content)
        row.setContentsMargins(12, 12, 12, 12)
        row.setSpacing(10)

        splitter = QSplitter(Qt.Orientation.Horizontal)
        splitter.setChildrenCollapsible(False)
        splitter.addWidget(self._g2c_files_panel(page))
        splitter.addWidget(self._g2c_rules_panel(page))
        splitter.setStretchFactor(0, 1)
        splitter.setStretchFactor(1, 2)
        splitter.setSizes([300, 620])
        row.addWidget(splitter, 1)

        row.addWidget(self._g2c_log_panel(page))
        layout.addWidget(content, 1)

        self._g2c_refresh_files(page)
        self._g2c_update_save_btn(page)
        return page

    def _g2c_log_panel(self, page) -> QWidget:
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        lay.addWidget(QLabel("<b>Log</b>"))
        log = QPlainTextEdit()
        log.setReadOnly(True)
        log.setPlaceholderText("Conversion output appears here…")
        log.setStyleSheet(
            "background: #1e1e1e; color: #d4d4d4; "
            "font-family: Consolas, monospace; font-size: 9pt;"
        )
        log.setFixedHeight(120)
        for line in getattr(page, "_g2c_log_lines", []):
            log.appendPlainText(line)
        lay.addWidget(log)
        page._g2c_log = log
        return panel

    def _g2c_log(self, page, text) -> None:
        ts = datetime.now().strftime("%H:%M:%S")
        lines = getattr(page, "_g2c_log_lines", None)
        if lines is None:
            lines = []
            page._g2c_log_lines = lines
        for line in str(text).splitlines():
            if line.strip():
                lines.append(f"[{ts}] {line}")
        if len(lines) > _FEATURE_LOG_LIMIT:
            del lines[:-_FEATURE_LOG_LIMIT]
        if getattr(page, "_g2c_params", None) is not None:
            page._g2c_params["log"] = list(lines)
        box = getattr(page, "_g2c_log", None)
        if box is not None:
            for line in str(text).splitlines():
                if line.strip():
                    box.appendPlainText(f"[{ts}] {line}")

    def _g2c_gate_options(self, page):
        """Enumerate every gate of every upstream Gating module."""
        opts = []
        gating_tasks = [
            t for t in self._task_chain(page._g2c_task_id)
            if t.get("id") != page._g2c_task_id and t.get("type") == "gating"
        ]
        multi = len(gating_tasks) > 1
        for task in gating_tasks:
            gates = self._gating_gates_for(task)
            by_id = {g["id"]: g for g in gates}
            for gate in gates:
                chain = _gate_chain(gates, gate["id"])
                needed = set()
                for g in chain:
                    needed |= _gate_needed_columns(g, by_id)
                # Show at most three levels: grandparent -> parent -> this gate.
                label = " -> ".join(g.get("name", g["id"]) for g in chain[-3:])
                if multi:
                    label += f" ({task.get('name', '')})"
                opts.append({
                    "gate_task": task["id"],
                    "task_name": task.get("name", ""),
                    "gate_id": gate["id"],
                    "gates": gates,
                    "name": gate.get("name", gate["id"]),
                    "label": label,
                    "needed": needed,
                })
        return opts

    def _g2c_gate_mask(self, gate_task_id, gates, gate_id, parquet_path):
        """Row-aligned int8 0/1 mask of a gate and its ancestors, or None."""
        import numpy as np

        by_id = {g["id"]: g for g in gates}
        needed = set()
        for g in _gate_chain(gates, gate_id):
            needed |= _gate_needed_columns(g, by_id)
        if not needed:
            return None
        values = self._column_data(gate_task_id, parquet_path, list(needed))
        if not values:
            return None
        try:
            mask = _compute_gate_filter_mask(
                gates, gate_id, parquet_path, {},
                existing=set(values), extra=values,
            )
        except Exception:  # noqa: BLE001
            return None
        if mask is None:
            return None
        return mask.astype("int8")

    def _g2c_files_panel(self, page) -> QWidget:
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        lay.addWidget(QLabel("<b>Data files</b>"))
        select_btn = QPushButton("Select files…")
        select_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        select_btn.setEnabled(not page._g2c_locked)
        lay.addWidget(select_btn)

        count = QLabel("")
        count.setStyleSheet("color: #6b7785;")
        lay.addWidget(count)

        table = QTableWidget()
        table.setColumnCount(2)
        table.setHorizontalHeaderLabels(["File", "Status"])
        header = table.horizontalHeader()
        header.setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
        header.setSectionResizeMode(1, QHeaderView.ResizeMode.ResizeToContents)
        table.verticalHeader().setVisible(False)
        table.verticalHeader().setDefaultSectionSize(26)
        table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        table.setSelectionMode(QAbstractItemView.SelectionMode.NoSelection)
        table.setStyleSheet("QTableWidget { background: #ffffff; border: none; }")
        lay.addWidget(table, 1)
        page._g2c_files_table = table
        page._g2c_count_label = count
        select_btn.clicked.connect(lambda _=False: self._g2c_select_files(page))
        return panel

    def _g2c_select_files(self, page) -> None:
        records = self._available_files(page._g2c_task_id)
        names = [rec.get("name", "") for rec in records]
        by_name = {rec.get("name", ""): rec.get("parquet") for rec in records}
        current = [self._comp_file_name(p, page._g2c_task_id) for p in page._g2c_params.get("files") or []]
        chosen = self._pick_items_dialog(
            "Select data files", names, current, "Filter files..."
        )
        if chosen is None:
            return
        # Reject a file that lacks the columns needed by an already-selected gate.
        rules = page._g2c_params.get("rules") or []
        selected_opts = [
            o for o in self._g2c_gate_options(page)
            if any(r.get("gate_task") == o["gate_task"] and r.get("gate_id") == o["gate_id"]
                   for r in rules)
        ]
        rejected = []
        accepted = []
        for name in chosen:
            path = by_name.get(name)
            if path is None:
                continue
            cols = set(self._columns_for(path, page._g2c_task_id))
            missing = [
                o["label"] for o in selected_opts if not (o["needed"] <= cols)
            ]
            if missing:
                rejected.append(f"{name} (missing {', '.join(missing)})")
            else:
                accepted.append(path)
        if rejected:
            QMessageBox.warning(
                self, "Select files",
                "These files were not added because they lack the columns "
                "needed by the selected gates:\n" + "\n".join(rejected),
            )
        page._g2c_params["files"] = accepted
        self._g2c_refresh_files(page)
        self._g2c_mark_dirty(page)

    def _g2c_file_status(self, page, parquet_path) -> str:
        params = page._g2c_params
        rec = (params.get("outputs") or {}).get(parquet_path)
        if not isinstance(rec, dict) or not rec.get("path"):
            return "Not converted"
        if self.project is None:
            return "Not converted"
        if not (self.project.path / rec["path"]).is_file():
            return "Not converted"
        if rec.get("signature") != self._gate2col_signature(
            params, parquet_path, page._g2c_task_id
        ):
            return "Not converted"
        return "Converted"

    def _g2c_refresh_files(self, page) -> None:
        table = getattr(page, "_g2c_files_table", None)
        files = list(page._g2c_params.get("files") or [])
        if table is not None:
            table.blockSignals(True)
            table.setRowCount(len(files))
            for i, path in enumerate(files):
                missing = not Path(str(path)).is_file()
                label = self._comp_file_name(path, page._g2c_task_id)
                if missing:
                    label += "  (missing)"
                item = QTableWidgetItem(label)
                item.setFlags(Qt.ItemFlag.ItemIsEnabled)
                if missing:
                    item.setForeground(QColor("#c0392b"))
                    item.setToolTip(
                        "This file is no longer on disk — re-run the module that "
                        "created it, or select files again."
                    )
                table.setItem(i, 0, item)
                status = "File missing" if missing else self._g2c_file_status(page, path)
                sitem = QTableWidgetItem(status)
                sitem.setFlags(Qt.ItemFlag.ItemIsEnabled)
                if missing:
                    sitem.setForeground(QColor("#c0392b"))
                else:
                    sitem.setForeground(
                        QColor("#1a7f37") if status == "Converted" else QColor("#9aa0a6")
                    )
                table.setItem(i, 1, sitem)
            table.blockSignals(False)
        count = getattr(page, "_g2c_count_label", None)
        if count is not None:
            count.setText(f"{len(files)} file(s) selected")
        self._g2c_rebuild_rules(page)

    def _g2c_rules_panel(self, page) -> QWidget:
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        lay.addWidget(QLabel("<b>Convert gates</b>"))

        table = QTableWidget()
        table.setColumnCount(2)
        table.setHorizontalHeaderLabels(["Gate", "New column name"])
        header = table.horizontalHeader()
        header.setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
        header.setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
        table.verticalHeader().setVisible(False)
        table.verticalHeader().setDefaultSectionSize(34)
        table.setStyleSheet("QTableWidget { background: #ffffff; border: none; }")
        lay.addWidget(table, 1)
        page._g2c_rules_table = table

        btns = QHBoxLayout()
        add_btn = QPushButton("Add")
        add_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        add_btn.setEnabled(not page._g2c_locked)
        del_btn = QPushButton("Delete")
        del_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        del_btn.setEnabled(not page._g2c_locked)
        btns.addWidget(add_btn)
        btns.addWidget(del_btn)
        btns.addStretch()
        lay.addLayout(btns)

        calc_btn = QPushButton("Convert")
        calc_btn.setCursor(Qt.CursorShape.PointingHandCursor)
