    def _fup_refresh_files(self, page) -> None:
        from_box = getattr(page, "_fup_from_box", None)
        to_box = getattr(page, "_fup_to_box", None)
        params = page._fup_params
        if from_box is not None:
            from_box.blockSignals(True)
            from_box.clear()
            for p in params.get("from_files") or []:
                from_box.addItem(self._comp_file_name(p, page._fup_task_id))
            from_box.blockSignals(False)
        if to_box is not None:
            to_box.blockSignals(True)
            to_box.clear()
            for p in params.get("to_files") or []:
                to_box.addItem(self._comp_file_name(p, page._fup_task_id))
            to_box.blockSignals(False)
        self._fup_refresh_key_combos(page)
        self._fup_rebuild_matches(page)
        self._fup_rebuild_features(page)

    def _fup_common_columns(self, page, files_key) -> list:
        """Columns shared by every file selected under `files_key`."""
        paths = list(page._fup_params.get(files_key) or [])
        if not paths:
            return []
        common = set(self._columns_for(paths[0], page._fup_task_id))
        for p in paths[1:]:
            common &= set(self._columns_for(p, page._fup_task_id))
        return sorted(common)

    def _fup_refresh_key_combos(self, page) -> None:
        params = page._fup_params
        for which, combo_attr, key_attr, files_key in (
            ("from", "_fup_key_from", "key_from", "from_files"),
            ("to", "_fup_key_to", "key_to", "to_files"),
        ):
            combo = getattr(page, combo_attr, None)
            if combo is None:
                continue
            cols = self._fup_common_columns(page, files_key)
            cur = params.get(key_attr)
            combo.blockSignals(True)
            combo.clear()
            combo.addItem("", None)
            for c in cols:
                combo.addItem(c, c)
            idx = combo.findData(cur)
            combo.setCurrentIndex(max(0, idx))
            combo.blockSignals(False)

    def _fup_on_key(self, page, which) -> None:
        params = page._fup_params
        combo = getattr(page, f"_fup_key_{which}", None)
        if combo is None:
            return
        params[f"key_{which}"] = combo.currentData()
        self._fup_mark_dirty(page)
        self._fup_rebuild_matches(page)

    def _fup_select_files(self, page, which) -> None:
        records = self._available_files(page._fup_task_id)
        names = [rec.get("name", "") for rec in records]
        by_name = {rec.get("name", ""): rec.get("parquet") for rec in records}
        key = "from_files" if which == "from" else "to_files"
        current = [self._comp_file_name(p, page._fup_task_id) for p in page._fup_params.get(key) or []]
        title = "Select From files" if which == "from" else "Select To files"
        chosen = self._pick_items_dialog(title, names, current, "Filter files...")
        if chosen is None:
            return
        page._fup_params[key] = [by_name[n] for n in chosen if n in by_name]
        self._fup_refresh_files(page)
        self._fup_mark_dirty(page)

    def _fup_select_features(self, page) -> None:
        from_cols = self._fup_common_columns(page, "from_files")
        if not from_cols:
            QMessageBox.information(self, "Features", "Select From files first.")
            return
        key_from = page._fup_params.get("key_from")
        options = [c for c in from_cols if c != key_from]
        existing = [f.get("source") for f in page._fup_params.get("features") or []]
        chosen = self._pick_items_dialog(
            "Select features", options, existing, "Filter columns..."
        )
        if chosen is None:
            return
        kept = {
            f.get("source"): f for f in page._fup_params.get("features") or []
            if f.get("source") in chosen
        }
        features = []
        for source in chosen:
            if source in kept:
                features.append(kept[source])
            else:
                features.append({"source": source, "name": source})
        page._fup_params["features"] = features
        self._fup_rebuild_features(page)
        self._fup_mark_dirty(page)

    def _fup_delete_feature(self, page) -> None:
        table = page._fup_features_table
        row = table.currentRow()
        features = page._fup_params.get("features") or []
        if 0 <= row < len(features):
            del features[row]
            self._fup_rebuild_features(page)
            self._fup_mark_dirty(page)

    def _fup_rebuild_features(self, page) -> None:
        table = getattr(page, "_fup_features_table", None)
        if table is None:
            return
        features = page._fup_params.get("features") or []
        enabled = not page._fup_locked
        dup = self._fup_duplicate_names(page)
        table.blockSignals(True)
        table.setRowCount(0)
        table.setRowCount(len(features))
        for i, feat in enumerate(features):
            src_item = QTableWidgetItem(feat.get("source") or "")
            src_item.setFlags(Qt.ItemFlag.ItemIsEnabled)
            table.setItem(i, 0, src_item)

            name_box = QWidget()
            nh = QHBoxLayout(name_box)
            nh.setContentsMargins(0, 0, 0, 0)
            nh.setSpacing(4)
            name_edit = QLineEdit(str(feat.get("name") or ""))
            name_edit.setEnabled(enabled)
            warn = QLabel("⚠")
            warn.setToolTip("Duplicate column name")
            warn.setStyleSheet("color: #b58900; font-weight: bold;")

            def on_name(text, f=feat, warn_label=warn):
                f["name"] = text.strip()
                warn_label.setVisible(
                    (f.get("name") or "").strip() in self._fup_duplicate_names(page)
                )
                self._fup_mark_dirty(page)

            name_edit.textEdited.connect(lambda t, cb=on_name: cb(t))
            nh.addWidget(name_edit, 1)
            nh.addWidget(warn)
            table.setCellWidget(i, 1, name_box)
            warn.setVisible((feat.get("name") or "").strip() in dup)
        table.blockSignals(False)

    def _fup_existing_columns(self, page) -> set:
        cols = set()
        for path in page._fup_params.get("to_files") or []:
            cols |= set(self._columns_for(path, page._fup_task_id))
        return cols

    def _fup_duplicate_names(self, page) -> set:
        existing = self._fup_existing_columns(page)
        dup = set()
        seen = set()
        for feat in page._fup_params.get("features") or []:
            name = (feat.get("name") or "").strip()
            if not name:
                continue
            if name in existing or name in seen:
                dup.add(name)
            seen.add(name)
        return dup

    def _fup_default_to(self, page, from_path):
        """Default pairing: the To file whose stem is the longest prefix."""
        from_stem = Path(str(from_path)).stem
        best = None
        for to_path in page._fup_params.get("to_files") or []:
            if str(to_path) == str(from_path):
                continue
            stem = Path(str(to_path)).stem
            if stem and from_stem.startswith(stem):
                if best is None or len(Path(str(best)).stem) < len(stem):
                    best = to_path
        return best

    def _fup_match(self, page) -> None:
        params = page._fup_params
        if not params.get("from_files"):
            QMessageBox.warning(self, "Match", "Select at least one From file.")
            return
        if not params.get("to_files"):
            QMessageBox.warning(self, "Match", "Select at least one To file.")
            return
        if not params.get("key_from") or not params.get("key_to"):
            QMessageBox.warning(
                self, "Match", "Choose a key column for both From and To files."
            )
            return
        if params.get("matches"):
            reply = QMessageBox.question(
                self, "Match",
                "Re-matching will overwrite the current file pairing.\nContinue?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return
        matches = {}
        for from_path in params.get("from_files") or []:
            to_path = self._fup_default_to(page, from_path)
            if to_path is not None:
                matches[from_path] = to_path
        params["matches"] = matches
        self._fup_rebuild_matches(page)
        self._fup_mark_dirty(page)
        self._fup_log(page, "Matched files.")

    def _fup_key_values(self, task_id, parquet_path, key):
        """Identifier column values for matching, in their stored dtype.

        Prefers the pipeline view (renames, virtual columns), then falls back
        to the stored parquet column when the pipeline cannot expose it.
        """
        if not parquet_path or not key:
            return None
        try:
            values = self._column_data(task_id, parquet_path, [key], numeric=False)
            if values.get(key) is not None:
                return values[key]
        except Exception as exc:  # noqa: BLE001
            _debug_log(
                f"feature up: column_data failed for {key!r} in {parquet_path}: {exc!r}"
            )
        try:
            import pandas as pd

            frame = pd.read_parquet(parquet_path, columns=[key])
            return frame[key].to_numpy()
        except Exception as exc:  # noqa: BLE001
            _debug_log(
                f"feature up: key {key!r} unreadable in {parquet_path}: {exc!r}"
            )
        return None

    def _fup_fill_match_stats(self, page, row, from_path, to_path) -> None:
        import pandas as pd

        table = getattr(page, "_fup_match_table", None)
        if table is None:
            return
        for col in range(2, 6):
            table.setItem(row, col, QTableWidgetItem(""))
        params = page._fup_params
        key_from = params.get("key_from")
        key_to = params.get("key_to")
        if not from_path or not to_path or not key_from or not key_to:
            return

        def unavailable(missing, key, reason=None):
            for col in (2, 3):
                item = QTableWidgetItem("—")
                item.setFlags(Qt.ItemFlag.ItemIsEnabled)
                item.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
                item.setToolTip(
                    reason
                    or f"Column '{key}' could not be read from the {missing} file"
                )
                table.setItem(row, col, item)

        for side, path in (("From", from_path), ("To", to_path)):
            if not Path(str(path)).is_file():
                unavailable(
                    side, "",
                    f"The {side} file is not on disk:\n{path}\n\n"
                    "Re-run the module that produced it, or select another file.",
                )
                return

        try:
            fv = self._fup_key_values(page._fup_task_id, from_path, key_from)
            if fv is None:
                unavailable("From", key_from)
                return
            tv = self._fup_key_values(page._fup_task_id, to_path, key_to)
            if tv is None:
                unavailable("To", key_to)
                return
            fv = pd.Series(fv).dropna()
            tv = pd.Series(tv).dropna()
            fu = fv.nunique()
            tu = tv.nunique()
            fset = set(fv.unique().tolist())
            tset = set(tv.unique().tolist())
            fonly = len(fset - tset)
            tonly = len(tset - fset)
            items = {
                2: (str(fu), False),
                3: (str(tu), False),
                4: (str(fonly), fonly > 0),
                5: (str(tonly), tonly > 0),
            }
            for col, (text, bad) in items.items():
                item = QTableWidgetItem(text)
                item.setFlags(Qt.ItemFlag.ItemIsEnabled)
                item.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
                if bad:
                    item.setForeground(QColor("#c0392b"))
                table.setItem(row, col, item)
        except Exception as exc:  # noqa: BLE001
            _debug_log(f"feature up match stats failed: {exc!r}")
            unavailable("selected", key_from)

    def _fup_rebuild_match_row(self, page, row) -> None:
        table = getattr(page, "_fup_match_table", None)
        if table is None:
            return
        from_files = page._fup_params.get("from_files") or []
        from_path = from_files[row] if row < len(from_files) else None
        combo = table.cellWidget(row, 1)
        to_path = combo.currentData() if combo is not None else None
        self._fup_fill_match_stats(page, row, from_path, to_path)

    def _fup_rebuild_matches(self, page) -> None:
        table = getattr(page, "_fup_match_table", None)
        if table is None:
            return
        params = page._fup_params
        from_files = params.get("from_files") or []
        to_files = params.get("to_files") or []
        enabled = not page._fup_locked
        table.blockSignals(True)
        table.setRowCount(0)
        table.setRowCount(len(from_files))
        for i, from_path in enumerate(from_files):
            from_missing = not Path(str(from_path)).is_file()
            text = self._comp_file_name(from_path, page._fup_task_id)
            if from_missing:
                text += "  (missing)"
            item = QTableWidgetItem(text)
            item.setFlags(Qt.ItemFlag.ItemIsEnabled)
            if from_missing:
                item.setForeground(QColor("#c0392b"))
                item.setToolTip(
                    "This file is no longer on disk — re-run the module that "
                    "created it, or pick another From file."
                )
            table.setItem(i, 0, item)

            combo = _NoWheelComboBox()
            combo.addItem("", None)
            for to_path in to_files:
                label = self._comp_file_name(to_path, page._fup_task_id)
                if not Path(str(to_path)).is_file():
                    label += "  (missing)"
                combo.addItem(label, to_path)
            cur = (params.get("matches") or {}).get(from_path)
            idx = combo.findData(cur)
            combo.setCurrentIndex(max(0, idx))
            combo.setEnabled(enabled)

            def on_to(value, f=from_path, ri=i):
                matches = params.setdefault("matches", {})
                if value:
                    matches[f] = value
                else:
                    matches.pop(f, None)
                self._fup_rebuild_match_row(page, ri)
                self._fup_mark_dirty(page)

            combo.currentIndexChanged.connect(
                lambda _=0, c=combo, cb=on_to: cb(c.currentData())
            )
            table.setCellWidget(i, 1, combo)
            self._fup_fill_match_stats(page, i, from_path, cur)
        table.blockSignals(False)

    def _fup_validate(self, page):
        params = page._fup_params
        if not params.get("from_files"):
            return False, "Select at least one From file."
        if not params.get("to_files"):
            return False, "Select at least one To file."
        if not params.get("key_from") or not params.get("key_to"):
            return False, "Choose a key column for both From and To files."
        features = params.get("features") or []
        if not features:
            return False, "Select at least one feature to map."
        from_common = set(self._fup_common_columns(page, "from_files"))
        to_common = set(self._fup_common_columns(page, "to_files"))
        if params.get("key_from") not in from_common:
            return False, f"Key '{params['key_from']}' is not in every From file."
        if params.get("key_to") not in to_common:
            return False, f"Key '{params['key_to']}' is not in every To file."
        for feat in features:
            if feat.get("source") not in from_common:
                return False, f"Feature '{feat.get('source')}' is not in every From file."
        names = [(feat.get("name") or "").strip() for feat in features]
        if any(not n for n in names):
            return False, "Give every mapped feature a new column name."
        if len(names) != len(set(names)):
            return False, "New column names must be unique."
        existing = self._fup_existing_columns(page)
        if any(n in existing for n in names):
            return False, "A new column name collides with an existing To-file column."
        return True, ""

    def _fup_calculate(self, page) -> None:
        ok, message = self._fup_validate(page)
        if not ok:
            QMessageBox.warning(self, "Calculate", message)
            return
        params = page._fup_params
        matches = params.get("matches") or {}
        from_files = params.get("from_files") or []
        unmatched = [f for f in from_files if not matches.get(f)]
        if unmatched:
            names = ", ".join(self._comp_file_name(f, page._fup_task_id) for f in unmatched)
            reply = QMessageBox.question(
                self, "Calculate",
                f"{len(unmatched)} From file(s) have no matched To file and "
                f"will not be processed:\n{names}\n\nContinue?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return
        outputs = params.get("outputs") or {}
        to_targets = list(dict.fromkeys(matches.values()))
        existing = [t for t in to_targets if isinstance(outputs.get(t), dict)]
        if existing:
            reply = QMessageBox.question(
                self, "Calculate",
                f"{len(existing)} file(s) already have results.\n"
                "Recalculate and overwrite them?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return

        status = getattr(page, "_fup_calc_status", None)
        if status is not None:
            status.setText("Calculating…")
        QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
        done = 0
        failed = []
        skipped = len(unmatched)
        page._fup_running = True
        page._fup_cancel = False
        try:
            for to_path in to_targets:
                if getattr(page, "_fup_cancel", False):
                    self._fup_log(page, "Calculation cancelled.")
                    break
                name = self._comp_file_name(to_path, page._fup_task_id)
                if status is not None:
                    status.setText(f"Calculating… {name}")
                QApplication.processEvents()
                try:
                    rel, columns, kind = self._fup_compute_file(page, to_path)
                except Exception as exc:  # noqa: BLE001
                    failed.append(f"{name}: {exc}")
                    self._fup_log(page, f"✗ {name}: {exc}")
                    continue
                outputs[to_path] = {
                    "path": rel,
                    "columns": columns,
                    "kind": kind,
                    "signature": self._feature_up_signature(
                        params, to_path, page._fup_task_id
                    ),
                }
                done += 1
                self._fup_log(
                    page, f"✓ {name} → {Path(rel).name} ({len(columns)} column(s))"
                )
        finally:
            QApplication.restoreOverrideCursor()
            page._fup_running = False

        for to_path in list(outputs.keys()):
            if to_path not in to_targets:
                outputs.pop(to_path, None)
        params["outputs"] = outputs
        page._fup_task_def["output"] = {"saved": bool(outputs)}
        page._fup_task_def["params"] = params
        if self.project is not None:
            self.project.save()
        page._fup_snapshot = copy.deepcopy(params)
        page._fup_dirty = False
        self._fup_update_save_btn(page)
        self._fup_rebuild_matches(page)

        summary = f"Calculated {done} file(s)."
        if skipped:
            summary += f" {skipped} skipped (no match)."
        if failed:
            summary += f" {len(failed)} failed — see the log."
        if status is not None:
            status.setText(summary)
        self._fup_log(page, summary)
        self.statusBar().showMessage(summary)
        self._module_saved(page)

    def _fup_compute_file(self, page, to_path):
        """Map features from the matched From file onto `to_path`; return (rel, columns, kind)."""
        import numpy as np
        import pandas as pd

        params = page._fup_params
        from_path = self._fup_matched_from(params, to_path)
        if not from_path:
            raise ValueError("no matched From file")
        key_from = params["key_from"]
        key_to = params["key_to"]
        features = params.get("features") or []
        sources = [f["source"] for f in features]
        names = [(f.get("name") or f["source"]).strip() for f in features]

        # Build the From lookup table (key -> feature values); the first row
        # wins when a key value repeats. Keys are read as stored (text keys
        # must not be coerced to NaN); feature values are numeric.
        from_keys = self._fup_key_values(page._fup_task_id, from_path, key_from)
        if from_keys is None:
            raise ValueError(f"'{key_from}' is missing from the From file")
        fv = self._column_data(page._fup_task_id, from_path, sources)
        from_keys = pd.Series(from_keys).astype("object")
        tmp = [f"__fup_src_{j}" for j in range(len(sources))]
        lf = pd.DataFrame({
            "__fup_key": from_keys,
            **{tmp[j]: fv[s] for j, s in enumerate(sources)},
        })
        lf = lf[lf["__fup_key"].notna()]
        dup = int(len(lf) - lf.drop_duplicates(subset="__fup_key", keep="first").shape[0])
        if dup:
            self._fup_log(
                page,
                f"{self._comp_file_name(from_path, page._fup_task_id)}: {dup} duplicate key value(s) "
                f"— kept the first row.",
            )
        lf = lf.drop_duplicates(subset="__fup_key", keep="first")

        tv = self._fup_key_values(page._fup_task_id, to_path, key_to)
        if tv is None:
            raise ValueError(f"'{key_to}' is missing from the To file")
        merged = pd.DataFrame({"__fup_key": pd.Series(tv).astype("object")}).merge(
            lf, on="__fup_key", how="left"
        )
        row_vals = {}
        for j, name in enumerate(names):
            row_vals[name] = pd.to_numeric(
                merged[tmp[j]], errors="coerce"
            ).to_numpy(dtype="float64")

        # The To file may be sampled upstream. The mapped file stays row-aligned
        # to the whole file (downstream readers expect that), so the sampled
        # rows are scattered back and the rest stays empty — those rows are
        # never read below the Subsample module.
        n_full = self._data_row_count(to_path)
        index = self._subsample_row_index(page._fup_task_id, to_path)
        if index is not None and row_vals:
            for name in list(row_vals):
                values = row_vals[name]
                if len(values) == len(index):
                    full = np.full(n_full, np.nan, dtype="float64")
                    full[index] = values[: len(index)]
                    row_vals[name] = full

        ent = self._ensure_image_index(to_path)
        is_image = ent is not None and ent.get("manifest") is not None
        stem = Path(str(to_path)).stem
        rel = f"Module/{page._fup_task_id}/{stem}_mapped.parquet"
        path = self.project.path / rel
        path.parent.mkdir(parents=True, exist_ok=True)

        if is_image:
            man = ent["manifest"]
            xmin = int(round(float(man["xmin"])))
            ymin = int(round(float(man["ymin"])))
            width = int(round(float(man["xmax"]) - float(man["xmin"]))) + 1
            height = int(round(float(man["ymax"]) - float(man["ymin"]))) + 1
            src = pd.read_parquet(to_path, columns=["x", "y"])
            xi = np.rint(src["x"].to_numpy(dtype="float64") - xmin).astype(np.int64)
            yi = np.rint(src["y"].to_numpy(dtype="float64") - ymin).astype(np.int64)
            ok = (xi >= 0) & (xi < width) & (yi >= 0) & (yi < height)
            flat = yi[ok] * width + xi[ok]
            xx = np.tile(np.arange(width, dtype=np.int32), height) + xmin
            yy = np.repeat(np.arange(height, dtype=np.int32), width) + ymin
            data = {"x": xx, "y": yy}
            for name in names:
                grid = np.full(height * width, np.nan, dtype="float64")
                grid[flat] = row_vals[name][ok]
                data[name] = grid
            pd.DataFrame(data).to_parquet(path, index=False)
            _build_image_index_files(str(path))
            kind = "image"
        else:
            pd.DataFrame(row_vals).to_parquet(path, index=False)
            kind = "table"
        return rel, names, kind

    def _fup_mark_dirty(self, page) -> None:
        page._fup_dirty = True
        self._fup_update_save_btn(page)
        self._module_set_state(page, MODULE_STATE_MODIFIED)

    def _fup_update_save_btn(self, page) -> None:
        btn = getattr(page, "_fup_save_btn", None)
        if btn is not None:
            btn.setEnabled(page._fup_dirty and not page._fup_locked)

    def _fup_save_now(self, page) -> None:
        params = page._fup_params
        page._fup_task_def["params"] = params
        if self.project is not None:
            self.project.save()
        page._fup_snapshot = copy.deepcopy(params)
        page._fup_dirty = False
        self._fup_update_save_btn(page)
        self._fup_log(page, "Settings saved")
        self.statusBar().showMessage("Feature Up settings saved")
        self._module_saved(page)

    def _fup_close(self, page) -> None:
        if getattr(page, "_fup_running", False):
            reply = QMessageBox.question(
                self, "Close Feature Up",
                "A calculation is still running.\nStop it and close the module?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return
            page._fup_cancel = True
            self._fup_log(page, "Stopping after the current file…")
            return
        if getattr(page, "_fup_dirty", False):
            reply = QMessageBox.question(
                self, "Close Feature Up",
                "There are unsaved changes.\nClose without saving? "
                "Unsaved changes will be lost.",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return
            log_lines = list(getattr(page, "_fup_log_lines", []) or [])
            page._fup_task_def["params"] = page._fup_snapshot
            page._fup_task_def["params"]["log"] = log_lines
        self._close_module_page(page)

    # ----- subset module (map) -------------------------------------------
    def _build_subset_page(self, name: str, task_def: dict, locked: bool) -> QWidget:
        """Build the Subset page: summary | data files (1) | columns (1)."""
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        bar = QFrame()
        bar.setObjectName("moduleBar")
        tl = QHBoxLayout(bar)
        tl.setContentsMargins(12, 6, 12, 6)
        tl.setSpacing(4)
        tl.addWidget(QLabel(f"<b>{self._module_display_title(task_def.get('id'), name)}</b>"))
        if locked:
            lock_icon = QLabel()
            lock_icon.setPixmap(_lock_pixmap())
            lock_icon.setFixedSize(14, 14)
            lock_icon.setToolTip("Locked — a downstream generate module has saved data")
            tl.addWidget(lock_icon)
            draft = QLabel("Draft (locked)")
            draft.setStyleSheet("color: #b58900; font-weight: bold;")
            tl.addWidget(draft)
        tl.addStretch()
        save_btn = QPushButton("Save")
        save_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        save_btn.setEnabled(not locked)
        close_btn = QPushButton("Close")
        close_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        close_btn.clicked.connect(lambda _=False: self._subset_close(page))
        tl.addWidget(save_btn)
        tl.addWidget(close_btn)
        layout.addWidget(bar)

        params = task_def.setdefault("params", {})
        params.setdefault("files", [])
        params.setdefault("columns", [])
        page._subset_task_def = task_def
        page._subset_task_id = task_def.get("id")
        page._subset_params = params
        page._subset_locked = locked
        page._subset_save_btn = save_btn
        page._subset_dirty = False
        # Edits stay in a draft until Save, so the filter changes downstream
        # only when the user commits it (the document's "Save to take effect").
        page._subset_draft_files = list(params.get("files") or [])
        page._subset_draft_columns = list(params.get("columns") or [])
        save_btn.clicked.connect(lambda _=False: self._subset_save_now(page))

        content = QWidget()
        content.setStyleSheet("background: #f5f8fb;")
        row = QVBoxLayout(content)
        row.setContentsMargins(12, 12, 12, 12)
        row.setSpacing(10)

        summary = QLabel("")
        summary.setStyleSheet("color: #3c4043; font-weight: bold;")
        row.addWidget(summary)
        page._subset_summary = summary

        splitter = QSplitter(Qt.Orientation.Horizontal)
        splitter.setChildrenCollapsible(False)
        splitter.addWidget(self._subset_files_panel(page))
        splitter.addWidget(self._subset_columns_panel(page))
        splitter.setStretchFactor(0, 1)
        splitter.setStretchFactor(1, 1)
        splitter.setSizes([440, 440])
        row.addWidget(splitter, 1)
        layout.addWidget(content, 1)

        self._subset_refresh(page)
        return page

    def _subset_files_panel(self, page) -> QWidget:
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        lay.addWidget(QLabel("<b>Data files</b>"))
        hint = QLabel(
            "Only the files kept here stay visible to downstream modules. "
            "An empty selection keeps every file."
        )
        hint.setWordWrap(True)
        hint.setStyleSheet("color: #6b7785;")
        lay.addWidget(hint)
        btn = QPushButton("Select files…")
        btn.setCursor(Qt.CursorShape.PointingHandCursor)
        btn.setEnabled(not page._subset_locked)
        lay.addWidget(btn)
        box = QListWidget()
        box.setStyleSheet(
            "QListWidget { background: #ffffff; border: 1px solid #d0d7e2; }"
        )
        lay.addWidget(box, 1)
        page._subset_files_box = box
        btn.clicked.connect(lambda _=False: self._subset_select_files(page))
        return panel

    def _subset_columns_panel(self, page) -> QWidget:
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        lay.addWidget(QLabel("<b>Columns</b>"))
        hint = QLabel(
            "Only the columns kept here stay visible to downstream modules. "
            "The list is the union of the kept files' columns. "
            "An empty selection keeps every column."
        )
        hint.setWordWrap(True)
        hint.setStyleSheet("color: #6b7785;")
        lay.addWidget(hint)
        btn = QPushButton("Select columns…")
        btn.setCursor(Qt.CursorShape.PointingHandCursor)
        btn.setEnabled(not page._subset_locked)
        lay.addWidget(btn)
        box = QListWidget()
        box.setStyleSheet(
            "QListWidget { background: #ffffff; border: 1px solid #d0d7e2; }"
        )
        lay.addWidget(box, 1)
        page._subset_columns_box = box
        btn.clicked.connect(lambda _=False: self._subset_select_columns(page))
        return panel

    def _subset_column_options(self, page) -> list:
        """Columns available for selection: union over the kept (draft) files."""
        paths = list(getattr(page, "_subset_draft_files", []) or [])
        if not paths:
            # No file filter yet, so every visible file counts as kept.
            paths = [
                rec.get("parquet")
                for rec in self._available_files(page._subset_task_id)
            ]
        columns = []
        for path in paths:
            for name in self._columns_for(path, page._subset_task_id):
                if name not in columns:
                    columns.append(name)
        return columns

    def _subset_select_files(self, page) -> None:
        records = self._available_files(page._subset_task_id)
        names = [rec.get("name", "") for rec in records]
        by_name = {rec.get("name", ""): rec.get("parquet") for rec in records}
        current = [self._comp_file_name(p, page._subset_task_id) for p in page._subset_draft_files]
        chosen = self._pick_items_dialog(
            "Select data files", names, current, "Filter files..."
        )
        if chosen is None:
            return
        page._subset_draft_files = [by_name[n] for n in chosen if n in by_name]
        # The column list follows the kept files, so drop selections that are
        # no longer offered by any of them.
        options = set(self._subset_column_options(page))
        page._subset_draft_columns = [
            c for c in page._subset_draft_columns if c in options
        ]
        self._subset_refresh(page)
        self._subset_mark_dirty(page)

    def _subset_select_columns(self, page) -> None:
        options = self._subset_column_options(page)
        if not options:
            QMessageBox.information(
                self, "Select columns", "There are no columns to choose from."
            )
            return
        chosen = self._pick_items_dialog(
            "Select columns", options, page._subset_draft_columns, "Filter columns..."
        )
        if chosen is None:
            return
        page._subset_draft_columns = list(chosen)
        self._subset_refresh(page)
        self._subset_mark_dirty(page)

    def _subset_refresh(self, page) -> None:
        files_box = getattr(page, "_subset_files_box", None)
        cols_box = getattr(page, "_subset_columns_box", None)
        files = list(getattr(page, "_subset_draft_files", []) or [])
        columns = list(getattr(page, "_subset_draft_columns", []) or [])
        if files_box is not None:
            files_box.clear()
            for path in files:
                files_box.addItem(self._comp_file_name(path, page._subset_task_id))
        if cols_box is not None:
            cols_box.clear()
            for name in columns:
                cols_box.addItem(str(name))
        summary = getattr(page, "_subset_summary", None)
        if summary is not None:
            file_text = (
                f"{len(files)} file(s) selected" if files else "All files visible"
            )
            col_text = (
                f"{len(columns)} column(s) selected"
                if columns else "All columns visible"
            )
            summary.setText(f"{file_text} · {col_text}")
        self._subset_update_save_btn(page)

    def _subset_mark_dirty(self, page) -> None:
        page._subset_dirty = True
        self._subset_update_save_btn(page)
        self._module_set_state(page, MODULE_STATE_MODIFIED)

    def _subset_update_save_btn(self, page) -> None:
        btn = getattr(page, "_subset_save_btn", None)
        if btn is not None:
            btn.setEnabled(page._subset_dirty and not page._subset_locked)

    def _subset_save_now(self, page) -> None:
        params = page._subset_params
        params["files"] = list(page._subset_draft_files)
        params["columns"] = list(page._subset_draft_columns)
        page._subset_task_def["params"] = params
        if self.project is not None:
            self.project.save()
        page._subset_dirty = False
        self._subset_update_save_btn(page)
        self.statusBar().showMessage("Subset settings saved")
        self._module_saved(page)

    def _subset_close(self, page) -> None:
        if getattr(page, "_subset_dirty", False):
            reply = QMessageBox.question(
                self, "Close Subset",
                "There are unsaved changes.\nClose without saving? "
                "Unsaved changes will be lost.",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return
        self._close_module_page(page)

    # ----- Subsample (map; row filtering) --------------------------------
    def _subsample_params_for(self, task_def) -> dict:
        """Saved params of a Subsample task (its live snapshot while open)."""
        task_id = task_def.get("id")
        reg = self._module_registry.get(task_id)
        if reg is not None and reg.get("task_type") == "subsample":
            snap = getattr(reg["page"], "_subs_snapshot", None)
            if isinstance(snap, dict):
                return snap
        return task_def.get("params") or {}

    def _subsample_tasks(self, task_id) -> list:
        """Subsample tasks above `task_id`, top-down (never the task itself)."""
        if not task_id or self.project is None:
            return []
        return [
            task for task in self._task_chain(task_id)
            if task.get("id") != task_id and task.get("type") == "subsample"
        ]

    def _subsample_sig(self, task_id, parquet_path) -> str:
        """Signature of every upstream sampling decision that affects a file."""
        path = str(parquet_path)
        parts = []
        for task in self._subsample_tasks(task_id):
            params = self._subsample_params_for(task)
            files = {str(p) for p in (params.get("files") or [])}
            if path not in files:
                continue
            parts.append({
                "task": task.get("id"),
                "basis": params.get("basis"),
                "count": params.get("count"),
                "allocation": params.get("allocation"),
                "override": (params.get("overrides") or {}).get(path),
            })
        if not parts:
            return ""
        return hashlib.sha1(
            json.dumps(parts, sort_keys=True).encode("utf-8")
        ).hexdigest()[:16]

    def _subsample_seed(self, task_id, parquet_path) -> int:
        """Stable per-(module, file) seed: same data samples the same rows.

        Derived from the ids only (never Python's `hash()`), so the selection
        does not change between sessions or when other files are added.
        """
        payload = f"smage-subsample-v1|{task_id}|{parquet_path}"
        return int(hashlib.sha1(payload.encode("utf-8")).hexdigest()[:16], 16)

    def _subsample_visible_count(self, task_id, parquet_path) -> int:
        """Rows of a file as seen at `task_id` (after upstream sampling)."""
        index = self._subsample_row_index(task_id, parquet_path)
        if index is None:
            return self._data_row_count(parquet_path)
        return int(len(index))

    def _subsample_row_index(self, task_id, parquet_path):
        """Row indices (into the full file) visible at `task_id`, or None.

        Layers the sampling of every upstream Subsample module that lists this
        file. Each module picks a fixed random permutation of its own visible
        rows, so a larger target keeps every row picked before.
        """
        import numpy as np

        if not task_id or not parquet_path or self.project is None:
            return None
        tasks = self._subsample_tasks(task_id)
        if not tasks:
            return None
        path = str(parquet_path)
        sig = self._subsample_sig(task_id, path)
        if not sig:
            return None
        cache = getattr(self, "_subsample_cache", None)
        if cache is None:
            cache = {}
            self._subsample_cache = cache
        key = (task_id, path, sig)
        if key in cache:
            return cache[key]
        index = None
        for task in tasks:
            params = self._subsample_params_for(task)
            files = [str(p) for p in (params.get("files") or [])]
            if path not in files:
                continue
            n = int(len(index)) if index is not None else self._data_row_count(path)
            if n <= 0:
                continue
            sizes = {
                p: self._subsample_visible_count(task.get("id"), p)
                for p in files
            }
            k = _subsample_allocate(params, sizes).get(path)
            if k is None or k >= n:
                continue
            if k <= 0:
                index = (index[:0] if index is not None
                         else np.zeros(0, dtype=np.int64))
                continue
            rng = np.random.default_rng(self._subsample_seed(task.get("id"), path))
            keep = np.sort(rng.permutation(n)[:k]).astype(np.int64)
            index = keep if index is None else index[keep]
        if len(cache) > 16:
            cache.clear()
        cache[key] = index
        return index

    def _subsample_coverage_dir(self, task_id):
        """Folder holding a Subsample module's saved image coverage masks."""
        if self.project is None or not task_id:
            return None
        return self.project.path / "Module" / str(task_id) / "coverage"

    def _subsample_coverage_paths(self, task, parquet_path):
        """(mask .npy path, metadata .json path) for one module + file."""
        folder = self._subsample_coverage_dir(task.get("id"))
        if folder is None:
            return None, None
        key = hashlib.sha1(str(parquet_path).encode("utf-8")).hexdigest()[:16]
        stem = f"{_feature_safe_stem(Path(str(parquet_path)).stem)}.{key}"
        return folder / f"{stem}.npy", folder / f"{stem}.json"

    def _subsample_mask_meta(self, task, parquet_path, manifest) -> dict:
        """Fingerprint of everything a coverage mask depends on."""
        params = self._subsample_params_for(task)
        path = str(parquet_path)
        try:
            st = Path(path).stat()
            stat = f"{int(st.st_size)}-{int(st.st_mtime_ns)}"
        except OSError:
            stat = ""
        return {
            "version": 1,
            "stat": stat,
            "upstream": self._subsample_sig(task.get("id"), path),
            "basis": params.get("basis"),
            "count": params.get("count"),
            "allocation": params.get("allocation"),
            "override": (params.get("overrides") or {}).get(path),
            "files": sorted(str(p) for p in (params.get("files") or [])),
            "xmin": float(manifest["xmin"]),
            "ymin": float(manifest["ymin"]),
            "xmax": float(manifest["xmax"]),
            "ymax": float(manifest["ymax"]),
        }

    def _subsample_own_mask(self, task, parquet_path, manifest):
        """Dense (H, W) mask of the pixels THIS module keeps, or None.

        None means "this module hides nothing from this file". The mask covers
        only the module's own sampling: upstream sampling is already excluded
        from the rows it sees.
        """
        import numpy as np
        import pandas as pd

        path = str(parquet_path)
        params = self._subsample_params_for(task)
        files = [str(p) for p in (params.get("files") or [])]
        if path not in files:
            return None
        sizes = {
            p: self._subsample_visible_count(task.get("id"), p) for p in files
        }
        n = sizes.get(path, 0)
        k = _subsample_allocate(params, sizes).get(path)
        if k is None or n <= 0 or k >= n:
            return None
        base = self._subsample_row_index(task.get("id"), path)
        if k <= 0:
            sel = np.zeros(0, dtype=np.int64)
        else:
            rng = np.random.default_rng(self._subsample_seed(task.get("id"), path))
            local = np.sort(rng.permutation(n)[:k]).astype(np.int64)
            sel = local if base is None else np.asarray(base)[local]
        xmin = float(manifest["xmin"])
        ymin = float(manifest["ymin"])
        width = int(round(float(manifest["xmax"]) - xmin)) + 1
        height = int(round(float(manifest["ymax"]) - ymin)) + 1
        try:
            df = pd.read_parquet(path, columns=["x", "y"])
        except Exception:  # noqa: BLE001
            return None
        xi = np.rint(df["x"].to_numpy(dtype="float64") - xmin).astype(np.int64)
        yi = np.rint(df["y"].to_numpy(dtype="float64") - ymin).astype(np.int64)
        ok = (sel >= 0) & (sel < len(xi))
        sel = sel[ok]
        mask = np.zeros((height, width), dtype=np.uint8)
        if sel.size:
            sx, sy = xi[sel], yi[sel]
            good = (sx >= 0) & (sx < width) & (sy >= 0) & (sy < height)
            mask[sy[good], sx[good]] = 1
        return mask

    def _subsample_saved_mask(self, task, parquet_path, manifest):
        """Load a module's saved coverage mask, or None when absent/stale."""
        import numpy as np

        npy, meta_path = self._subsample_coverage_paths(task, parquet_path)
        if npy is None or not npy.is_file() or not meta_path.is_file():
            return None
        try:
            meta = json.loads(meta_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return None
        if meta != self._subsample_mask_meta(task, parquet_path, manifest):
            return None
        try:
            mask = np.load(npy)
        except (OSError, ValueError):
            return None
        return mask if mask.ndim == 2 else None

    def _subsample_write_masks(self, page) -> int:
        """Persist this module's image coverage masks into its own folder.

        Called on Save, so the masks live with the module (and are removed
        with it). Returns the number of masks written.
        """
        import numpy as np

        task = page._subs_task_def
        folder = self._subsample_coverage_dir(task.get("id"))
        if folder is None:
            return 0
        wanted = set()
        written = 0
        for path in page._subs_params.get("files") or []:
            ent = self._ensure_image_index(path)
            if ent is None or ent.get("manifest") is None:
                continue  # table data needs no raster coverage mask
            manifest = ent["manifest"]
            mask = self._subsample_own_mask(task, path, manifest)
            npy, meta_path = self._subsample_coverage_paths(task, path)
            if npy is None:
                continue
            wanted.add(npy.name)
            wanted.add(meta_path.name)
            if mask is None:
                # Nothing hidden by this module: drop any stale mask.
                for p in (npy, meta_path):
                    try:
                        p.unlink(missing_ok=True)
                    except OSError:
                        pass
                continue
            try:
                folder.mkdir(parents=True, exist_ok=True)
                np.save(npy, mask)
                meta_path.write_text(
                    json.dumps(self._subsample_mask_meta(task, path, manifest)),
                    encoding="utf-8",
                )
                written += 1
            except OSError:
                continue
        # Remove masks for files that are no longer selected.
        try:
            for f in folder.iterdir():
                if f.is_file() and f.name not in wanted:
                    f.unlink(missing_ok=True)
        except OSError:
            pass
        self._subsample_mask_cache = {}
        return written

    def _subsample_module_mask(self, task, parquet_path, manifest):
        """This module's coverage mask: the saved one, else computed now."""
        cache = getattr(self, "_subsample_mask_cache", None)
        if cache is None:
            cache = {}
            self._subsample_mask_cache = cache
        key = (task.get("id"), str(parquet_path),
               self._subsample_sig(task.get("id"), parquet_path))
        if key in cache:
            return cache[key]
        mask = self._subsample_saved_mask(task, parquet_path, manifest)
        if mask is None:
            mask = self._subsample_own_mask(task, parquet_path, manifest)
        if len(cache) > 8:
            cache.clear()
        cache[key] = mask
        return mask

    def _subsample_pixel_mask(self, task_id, parquet_path, manifest):
        """Dense (H, W) mask of the pixels every upstream Subsample keeps.

        Each module stores its own mask in its folder; the visible set is the
        intersection of them (a row kept by every module on the way down).
        """
        import numpy as np

        masks = []
        for task in self._subsample_tasks(task_id):
            mask = self._subsample_module_mask(task, parquet_path, manifest)
            if mask is not None:
                masks.append(mask)
        if not masks:
            return None
        out = masks[0]
        for mask in masks[1:]:
            if mask.shape != out.shape:
                continue
            out = np.logical_and(out, mask).astype(np.uint8)
        return out

    def _subsample_cover_ent(self, task_id, parquet_path, manifest):
        """Block-level "fraction of sampled pixels" entry for the image renderer.

        Same shape as the gate-filter mask entry, so the image renderer can
        crop it with `_image_mask_crop`; the renderer keeps a block opaque
        only when that fraction is above one half.
        """
        mask = self._subsample_pixel_mask(task_id, parquet_path, manifest)
        if mask is None:
            return None
        blocks = [info["block"] for info in manifest.get("levels", [])]
        levels = _pool_mask(mask, blocks)
        if not levels:
            return None
        # `mask_2d` serves the deep-zoom path, where the renderer reads raw
        # pixels instead of a pyramid level.
        return {"levels": levels, "mask_2d": mask}

    def _subsample_cover_crop(self, task_id, parquet_path, manifest, bbox, spacing):
        """Sampled-pixel visibility over the visible bbox, shaped like the raster.

        The image renderer draws either a pyramid level (coarse/medium zoom) or
        raw pixels (deep zoom); each needs its own crop rule, otherwise the
        mask would silently drop out once the view switches to raw pixels.
        """
        import math
        import numpy as np

        ent = self._subsample_cover_ent(task_id, parquet_path, manifest)
        if ent is None:
            return None
        levels = manifest.get("levels", [])
        raw = (not levels) or (
            spacing < levels[0]["block"] and levels[0]["block"] > 1
        )
        if not raw:
            cover, _rect = self._image_mask_crop(manifest, bbox, spacing, ent)
            return cover
        mask = ent.get("mask_2d")
        if mask is None:
            return None
        x0, x1, y0, y1 = bbox
        i0 = int(math.floor(x0 - float(manifest["xmin"])))
        j0 = int(math.floor(y0 - float(manifest["ymin"])))
        nbx = max(1, int(math.ceil(x1 - x0)))
        nby = max(1, int(math.ceil(y1 - y0)))
        out = np.zeros((nby, nbx), dtype=np.float32)
        sx0, sy0 = max(0, i0), max(0, j0)
        sx1 = min(mask.shape[1], i0 + nbx)
        sy1 = min(mask.shape[0], j0 + nby)
        if sx1 > sx0 and sy1 > sy0:
            out[sy0 - j0:sy1 - j0, sx0 - i0:sx1 - i0] = mask[sy0:sy1, sx0:sx1]
        return out

    def _build_subsample_page(self, name: str, task_def: dict, locked: bool) -> QWidget:
        """Build the Subsample page: settings (1) | per-file table (1)."""
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        bar = QFrame()
        bar.setObjectName("moduleBar")
        tl = QHBoxLayout(bar)
        tl.setContentsMargins(12, 6, 12, 6)
        tl.setSpacing(4)
        tl.addWidget(QLabel(f"<b>{self._module_display_title(task_def.get('id'), name)}</b>"))
        if locked:
            lock_icon = QLabel()
            lock_icon.setPixmap(_lock_pixmap())
            lock_icon.setFixedSize(14, 14)
            lock_icon.setToolTip("Locked — a downstream generate module has saved data")
            tl.addWidget(lock_icon)
            draft = QLabel("Draft (locked)")
            draft.setStyleSheet("color: #b58900; font-weight: bold;")
            tl.addWidget(draft)
        tl.addStretch()
        save_btn = QPushButton("Save")
        save_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        save_btn.setEnabled(not locked)
        close_btn = QPushButton("Close")
        close_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        close_btn.clicked.connect(lambda _=False: self._subs_close(page))
        tl.addWidget(save_btn)
        tl.addWidget(close_btn)
        layout.addWidget(bar)

        params = task_def.setdefault("params", {})
        params.setdefault("files", [])
        params.setdefault("basis", "")
        params.setdefault("unit", "points")
        params.setdefault("count", None)
        params.setdefault("percent", None)
        params.setdefault("allocation", "uniform")
        params.setdefault("overrides", {})
        page._subs_task_def = task_def
        page._subs_task_id = task_def.get("id")
        page._subs_params = params
        page._subs_locked = locked
        page._subs_save_btn = save_btn
        page._subs_dirty = False
        page._subs_snapshot = copy.deepcopy(params)
        page._subs_updating = False
        save_btn.clicked.connect(lambda _=False: self._subs_save_now(page))

        content = QWidget()
        content.setStyleSheet("background: #f5f8fb;")
        row = QVBoxLayout(content)
        row.setContentsMargins(12, 12, 12, 12)
        row.setSpacing(10)

        splitter = QSplitter(Qt.Orientation.Horizontal)
        splitter.setChildrenCollapsible(False)
        splitter.addWidget(self._subs_settings_panel(page))
        splitter.addWidget(self._subs_table_panel(page))
        splitter.setStretchFactor(0, 1)
        splitter.setStretchFactor(1, 1)
        splitter.setSizes([400, 520])
        row.addWidget(splitter, 1)
        layout.addWidget(content, 1)

        self._subs_refresh(page)
        return page

    def _subs_settings_panel(self, page) -> QWidget:
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)

        lay.addWidget(QLabel("<b>Data files</b>"))
        hint = QLabel(
            "Selected files are sampled; the others pass through untouched. "
            "Sampling only changes what downstream modules see — no new data "
            "is written."
        )
        hint.setWordWrap(True)
        hint.setStyleSheet("color: #6b7785;")
        lay.addWidget(hint)
        files_btn = QPushButton("Select files…")
        files_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        files_btn.setEnabled(not page._subs_locked)
        lay.addWidget(files_btn)
        files_box = QListWidget()
        files_box.setFixedHeight(110)
        files_box.setStyleSheet(
            "QListWidget { background: #ffffff; border: 1px solid #d0d7e2; }"
        )
        lay.addWidget(files_box)
        page._subs_files_box = files_box

        lay.addSpacing(8)
        lay.addWidget(QLabel("<b>Sampling basis</b>"))
        basis = _NoWheelComboBox()
        basis.addItem("", None)
        basis.addItem("Per file", "per_file")
        basis.addItem("Total", "total")
        basis.setEnabled(not page._subs_locked)
        lay.addWidget(basis)
        page._subs_basis = basis

        unit_label = QLabel("Count by")
        lay.addWidget(unit_label)
        page._subs_unit_label = unit_label
        unit = _NoWheelComboBox()
        unit.addItem("Points per file", "points")
        unit.addItem("Percentage per file", "percent")
        unit.setEnabled(False)
        lay.addWidget(unit)
        page._subs_unit = unit

        count_label = QLabel("Points per file")
        lay.addWidget(count_label)
        page._subs_count_label = count_label
        count_box = _NoWheelDoubleSpinBox()
        count_box.setDecimals(0)
        count_box.setRange(1, 2_000_000_000)
        count_box.setValue(_SUBS_DEFAULT_COUNT)
        count_box.setEnabled(False)
        lay.addWidget(count_box)
        page._subs_count = count_box

        alloc_label = QLabel("Allocation")
        lay.addWidget(alloc_label)
        page._subs_alloc_label = alloc_label
        alloc = _NoWheelComboBox()
        alloc.addItem("Equal (same count per file)", "uniform")
        alloc.addItem("Weighted by file size", "weighted")
        alloc.setEnabled(False)
        lay.addWidget(alloc)
        page._subs_alloc = alloc

        lay.addStretch()

        files_btn.clicked.connect(lambda _=False: self._subs_select_files(page))
        basis.currentIndexChanged.connect(lambda _=0: self._subs_on_basis(page))
        unit.currentIndexChanged.connect(lambda _=0: self._subs_on_unit(page))
        count_box.valueChanged.connect(lambda _=0: self._subs_on_value(page))
        alloc.currentIndexChanged.connect(lambda _=0: self._subs_on_alloc(page))
        return panel

    def _subs_table_panel(self, page) -> QWidget:
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        lay.addWidget(QLabel("<b>Sampling</b>"))
        hint = QLabel(
            "The sampled count is editable — type a value to override the "
            "computed one for that file."
        )
        hint.setWordWrap(True)
        hint.setStyleSheet("color: #6b7785;")
        lay.addWidget(hint)
        table = QTableWidget()
        table.setColumnCount(3)
        table.setHorizontalHeaderLabels(["File", "Original points", "Sampled points"])
        header = table.horizontalHeader()
        header.setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
        header.setSectionResizeMode(1, QHeaderView.ResizeMode.ResizeToContents)
        header.setSectionResizeMode(2, QHeaderView.ResizeMode.ResizeToContents)
        table.verticalHeader().setVisible(False)
        table.verticalHeader().setDefaultSectionSize(26)
        table.setStyleSheet("QTableWidget { background: #ffffff; border: none; }")
        lay.addWidget(table, 1)
        page._subs_table = table
        override_hint = QLabel("* Sampled counts were adjusted manually")
        override_hint.setStyleSheet("color: #b58900;")
        override_hint.setVisible(False)
        lay.addWidget(override_hint)
        page._subs_override_hint = override_hint
        table.itemChanged.connect(lambda item: self._subs_on_cell(page, item))
        return panel

    def _subs_visible_sizes(self, page) -> dict:
        return {
            path: self._subsample_visible_count(page._subs_task_id, path)
            for path in (page._subs_params.get("files") or [])
        }

    def _subs_computed(self, page, sizes) -> dict:
        """Computed counts, ignoring manual overrides."""
        params = dict(page._subs_params)
        params["overrides"] = {}
        return _subsample_allocate(params, sizes)

    def _subs_select_files(self, page) -> None:
        records = self._available_files(page._subs_task_id)
        names = [rec.get("name", "") for rec in records]
        by_name = {rec.get("name", ""): rec.get("parquet") for rec in records}
        current = [self._comp_file_name(p, page._subs_task_id) for p in page._subs_params.get("files") or []]
        chosen = self._pick_items_dialog(
            "Select data files", names, current, "Filter files..."
        )
        if chosen is None:
            return
        page._subs_params["files"] = [by_name[n] for n in chosen if n in by_name]
        # Drop overrides for files that are no longer selected.
        files = set(page._subs_params["files"])
        page._subs_params["overrides"] = {
            p: k for p, k in (page._subs_params.get("overrides") or {}).items()
            if p in files
        }
        self._subs_refresh(page)
        self._subs_mark_dirty(page)

    def _subs_param_changed(self, page) -> None:
        """A sampling setting changed: confirm before discarding manual counts."""
        overrides = page._subs_params.get("overrides") or {}
        if overrides:
            reply = QMessageBox.question(
                self, "Subsample",
                "You adjusted some sampled counts manually.\n"
                "Recalculating with the new settings will overwrite them.\n\n"
                "Recalculate and discard the manual values?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply == QMessageBox.StandardButton.Yes:
                page._subs_params["overrides"] = {}
        self._subs_refresh(page)
        self._subs_mark_dirty(page)

    def _subs_percent_mode(self, params) -> bool:
        """True when sampling is "a percentage of each file"."""
        return (
            (params.get("basis") or "") == "per_file"
            and (params.get("unit") or "points") == "percent"
        )

    def _subs_on_basis(self, page) -> None:
        if page._subs_updating:
            return
        value = page._subs_basis.currentData()
        params = page._subs_params
        changed = value != (params.get("basis") or None)
        params["basis"] = value or ""
        if value:
            # First basis choice: seed the value the right field needs.
            if self._subs_percent_mode(params) and params.get("percent") is None:
                params["percent"] = _SUBS_DEFAULT_PERCENT
            elif params.get("count") is None:
                params["count"] = int(page._subs_count.value()) or _SUBS_DEFAULT_COUNT
        if changed:
            self._subs_param_changed(page)
        else:
            self._subs_refresh(page)

    def _subs_on_unit(self, page) -> None:
        if page._subs_updating:
            return
        params = page._subs_params
        value = page._subs_unit.currentData() or "points"
        if value == (params.get("unit") or "points"):
            return
        params["unit"] = value
        if self._subs_percent_mode(params) and params.get("percent") is None:
            params["percent"] = _SUBS_DEFAULT_PERCENT
        elif params.get("count") is None:
            params["count"] = _SUBS_DEFAULT_COUNT
        self._subs_param_changed(page)

    def _subs_on_value(self, page) -> None:
        if page._subs_updating:
            return
        params = page._subs_params
        value = float(page._subs_count.value())
        if self._subs_percent_mode(params):
            params["percent"] = value
        else:
            params["count"] = int(round(value))
        self._subs_param_changed(page)

    def _subs_on_alloc(self, page) -> None:
        if page._subs_updating:
            return
        value = page._subs_alloc.currentData() or "uniform"
        if value == (page._subs_params.get("allocation") or "uniform"):
            return
        page._subs_params["allocation"] = value
        self._subs_param_changed(page)

    def _subs_on_cell(self, page, item) -> None:
        if page._subs_updating or page._subs_locked:
            return
        if item.column() != 2:
            return
        path = item.data(Qt.ItemDataRole.UserRole)
        if not path:
            return
        sizes = self._subs_visible_sizes(page)
        if path not in sizes:
            return
        text = (item.text() or "").strip()
        if not text:
            return
        try:
            value = int(float(text))
        except ValueError:
            self._subs_refresh(page)
            return
        # A manual value never exceeds the file's own point count.
        value = max(0, min(value, sizes[path]))
        computed = self._subs_computed(page, sizes).get(path)
        if computed is not None and value == computed:
            page._subs_params.get("overrides", {}).pop(path, None)
        else:
            page._subs_params.setdefault("overrides", {})[path] = value
        self._subs_refresh(page)
        self._subs_mark_dirty(page)

    def _subs_refresh(self, page) -> None:
        params = page._subs_params
        files = list(params.get("files") or [])
        sizes = self._subs_visible_sizes(page)
        counts = _subsample_allocate(params, sizes)

        page._subs_updating = True
        try:
            page._subs_basis.blockSignals(True)
            idx = page._subs_basis.findData(params.get("basis") or None)
            page._subs_basis.setCurrentIndex(max(0, idx))
            page._subs_basis.blockSignals(False)
            has_basis = bool(params.get("basis"))
            total = params.get("basis") == "total"
            per_file = params.get("basis") == "per_file"
            percent_mode = self._subs_percent_mode(params)

            page._subs_unit.blockSignals(True)
            page._subs_unit.setCurrentIndex(
                max(0, page._subs_unit.findData(params.get("unit") or "points"))
            )
            page._subs_unit.setEnabled(per_file and not page._subs_locked)
            page._subs_unit.blockSignals(False)
            page._subs_unit_label.setVisible(per_file)
            page._subs_unit.setVisible(per_file)

            box = page._subs_count
            box.blockSignals(True)
            if percent_mode:
                box.setDecimals(1)
                box.setRange(0.1, 100.0)
                box.setSuffix(" %")
                if params.get("percent"):
                    box.setValue(float(params["percent"]))
            else:
                box.setDecimals(0)
                box.setRange(1, 2_000_000_000)
                box.setSuffix("")
                if params.get("count"):
                    box.setValue(int(params["count"]))
            box.setEnabled(has_basis and not page._subs_locked)
            box.blockSignals(False)
            page._subs_count_label.setText(
                "Percentage per file" if percent_mode
                else ("Total points" if total else "Points per file")
            )
            page._subs_alloc.blockSignals(True)
            page._subs_alloc.setCurrentIndex(
                max(0, page._subs_alloc.findData(params.get("allocation") or "uniform"))
            )
            page._subs_alloc.setEnabled(total and not page._subs_locked)
            page._subs_alloc.blockSignals(False)
            page._subs_alloc_label.setVisible(total)

            page._subs_files_box.clear()
            for path in files:
                page._subs_files_box.addItem(self._comp_file_name(path, page._subs_task_id))

            table = page._subs_table
            table.blockSignals(True)
            table.setRowCount(len(files))
            for i, path in enumerate(files):
                name_item = QTableWidgetItem(self._comp_file_name(path, page._subs_task_id))
                name_item.setFlags(Qt.ItemFlag.ItemIsEnabled)
                table.setItem(i, 0, name_item)
                orig_item = QTableWidgetItem(str(sizes.get(path, 0)))
                orig_item.setFlags(Qt.ItemFlag.ItemIsEnabled)
                orig_item.setTextAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
                table.setItem(i, 1, orig_item)
                k = counts.get(path)
                sampled = QTableWidgetItem("" if k is None else str(k))
                sampled.setData(Qt.ItemDataRole.UserRole, path)
                flags = Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable
                if not page._subs_locked:
                    flags |= Qt.ItemFlag.ItemIsEditable
                sampled.setFlags(flags)
                sampled.setTextAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
                table.setItem(i, 2, sampled)
            table.blockSignals(False)
        finally:
            page._subs_updating = False
        page._subs_override_hint.setVisible(
            bool(page._subs_params.get("overrides"))
        )
        self._subs_update_save_btn(page)

    def _subs_mark_dirty(self, page) -> None:
        page._subs_dirty = True
        self._subs_update_save_btn(page)
        self._module_set_state(page, MODULE_STATE_MODIFIED)

    def _subs_update_save_btn(self, page) -> None:
        btn = getattr(page, "_subs_save_btn", None)
        if btn is not None:
            btn.setEnabled(page._subs_dirty and not page._subs_locked)

    def _subs_save_now(self, page) -> None:
        params = page._subs_params
        page._subs_task_def["params"] = params
        # Commit the settings first: the mask builders read the saved snapshot.
        page._subs_snapshot = copy.deepcopy(params)
        page._subs_dirty = False
        if self.project is not None:
            self.project.save()
        # Image files get a coverage mask saved next to the module, so the
        # figure can mask unsampled pixels without recomputing every render.
        count = 0
        try:
            QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
            QApplication.processEvents()
            count = self._subsample_write_masks(page)
        finally:
            QApplication.restoreOverrideCursor()
        self._subsample_cache = {}
        self._subsample_mask_cache = {}
        self._subs_update_save_btn(page)
        message = "Subsample settings saved"
        if count:
            message += f" ({count} image mask(s))"
        self.statusBar().showMessage(message)
        self._module_saved(page)

    def _subs_close(self, page) -> None:
        if getattr(page, "_subs_dirty", False):
            reply = QMessageBox.question(
                self, "Close Subsample",
                "There are unsaved changes.\nClose without saving? "
                "Unsaved changes will be lost.",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return
            page._subs_task_def["params"] = page._subs_snapshot
        self._close_module_page(page)

    # ----- rename module (map; name transforms) --------------------------
    def _build_rename_page(self, name: str, task_def: dict, locked: bool) -> QWidget:
        """Build the Rename page: mode toggle | file/column rename table."""
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        bar = QFrame()
        bar.setObjectName("moduleBar")
        tl = QHBoxLayout(bar)
        tl.setContentsMargins(12, 6, 12, 6)
        tl.setSpacing(4)
        tl.addWidget(QLabel(f"<b>{self._module_display_title(task_def.get('id'), name)}</b>"))
        if locked:
            lock_icon = QLabel()
            lock_icon.setPixmap(_lock_pixmap())
            lock_icon.setFixedSize(14, 14)
            lock_icon.setToolTip("Locked — a downstream generate module has saved data")
            tl.addWidget(lock_icon)
            draft = QLabel("Draft (locked)")
            draft.setStyleSheet("color: #b58900; font-weight: bold;")
            tl.addWidget(draft)
        tl.addStretch()
        save_btn = QPushButton("Save")
        save_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        save_btn.setEnabled(not locked)
        close_btn = QPushButton("Close")
        close_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        close_btn.clicked.connect(lambda _=False: self._rename_close(page))
        tl.addWidget(save_btn)
        tl.addWidget(close_btn)
        layout.addWidget(bar)

        params = task_def.setdefault("params", {})
        params.setdefault("mode", "file")
        params.setdefault("file", {"files": [], "rows": [], "rename": {}})
        params.setdefault("column", {"files": [], "rows": [], "rename": {}})
        page._rename_task_def = task_def
        page._rename_task_id = task_def.get("id")
        page._rename_params = params
        page._rename_locked = locked
        page._rename_save_btn = save_btn
        page._rename_dirty = False
        save_btn.clicked.connect(lambda _=False: self._rename_save_now(page))

        content = QWidget()
        content.setStyleSheet("background: #f5f8fb;")
        row = QVBoxLayout(content)
        row.setContentsMargins(12, 12, 12, 12)
        row.setSpacing(8)

        mode_row = QHBoxLayout()
        mode_row.addWidget(QLabel("<b>Rename</b>"))
        mode = _NoWheelComboBox()
        mode.addItem("Data files", "file")
        mode.addItem("Variables", "column")
        mode.setEnabled(not locked)
        mode_row.addWidget(mode)
        mode_row.addStretch()
        row.addLayout(mode_row)
        page._rename_mode = mode

        stack = QStackedWidget()
        stack.addWidget(self._rename_file_panel(page))
        stack.addWidget(self._rename_column_panel(page))
        row.addWidget(stack, 1)
        page._rename_stack = stack
        layout.addWidget(content, 1)

        mode.currentIndexChanged.connect(lambda _=0: self._rename_on_mode(page))
        self._rename_refresh(page)
        return page

    def _rename_file_panel(self, page) -> QWidget:
        panel = QWidget()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(8)
        top = QHBoxLayout()
        sel = QPushButton("Select files…")
        sel.setCursor(Qt.CursorShape.PointingHandCursor)
        sel.clicked.connect(lambda _=False: self._rename_select_files(page))
        top.addWidget(sel)
        top.addStretch()
        lay.addLayout(top)
        hint = QLabel(
            "Rename the display name of selected files. The internal file "
            "identity is unchanged; only downstream modules see the new name."
        )
        hint.setWordWrap(True)
        hint.setStyleSheet("color: #6b7785;")
        lay.addWidget(hint)
        lay.addWidget(self._rename_table(page, "file"), 1)
        lay.addLayout(self._rename_copy_paste(page))
        return panel

    def _rename_column_panel(self, page) -> QWidget:
        panel = QWidget()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(8)
        splitter = QSplitter(Qt.Orientation.Horizontal)
        splitter.setChildrenCollapsible(False)

        left = self._build_panel_frame()
        ll = QVBoxLayout(left)
        ll.setContentsMargins(10, 10, 10, 10)
        ll.setSpacing(6)
        ll.addWidget(QLabel("<b>Data files</b>"))
        hint_files = QLabel(
            "Renaming applies only to the selected files; the same variable in "
            "an unselected file keeps its old name."
        )
        hint_files.setWordWrap(True)
        hint_files.setStyleSheet("color: #6b7785;")
        ll.addWidget(hint_files)
        files_btn = QPushButton("Select files…")
        files_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        files_btn.clicked.connect(lambda _=False: self._rename_select_files(page))
        ll.addWidget(files_btn)
        files_box = QListWidget()
        files_box.setStyleSheet(
            "QListWidget { background: #ffffff; border: 1px solid #d0d7e2; }"
        )
        ll.addWidget(files_box, 1)
        page._rename_column_files_box = files_box

        right = self._build_panel_frame()
        rl = QVBoxLayout(right)
        rl.setContentsMargins(10, 10, 10, 10)
        rl.setSpacing(6)
        rl.addWidget(QLabel("<b>Variables</b>"))
        hint_vars = QLabel(
            "Variables shared by the selected files (their union)."
        )
        hint_vars.setWordWrap(True)
        hint_vars.setStyleSheet("color: #6b7785;")
        rl.addWidget(hint_vars)
        vars_btn = QPushButton("Select variables…")
        vars_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        vars_btn.clicked.connect(lambda _=False: self._rename_select_vars(page))
        rl.addWidget(vars_btn)
        vars_box = QListWidget()
        vars_box.setStyleSheet(
            "QListWidget { background: #ffffff; border: 1px solid #d0d7e2; }"
        )
        rl.addWidget(vars_box, 1)
        page._rename_column_vars_box = vars_box

        splitter.addWidget(left)
        splitter.addWidget(right)
        splitter.setStretchFactor(0, 1)
        splitter.setStretchFactor(1, 1)
        lay.addWidget(splitter, 3)
        lay.addWidget(self._rename_table(page, "column"), 4)
        lay.addLayout(self._rename_copy_paste(page))
        return panel

    def _rename_table(self, page, mode) -> QWidget:
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        table = QTableWidget()
        table.setColumnCount(3)
        table.setHorizontalHeaderLabels(["original name", "new name", ""])
        header = table.horizontalHeader()
        header.setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
        header.setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
        header.setSectionResizeMode(2, QHeaderView.ResizeMode.ResizeToContents)
        table.verticalHeader().setVisible(False)
        table.verticalHeader().setDefaultSectionSize(30)
        table.setStyleSheet("QTableWidget { background: #ffffff; border: none; }")
        lay.addWidget(table, 1)
        attr = "_rename_file_table" if mode == "file" else "_rename_column_table"
        setattr(page, attr, table)
        table.itemChanged.connect(
            lambda item, m=mode: self._rename_on_cell(page, item, m)
        )
        return panel

    def _rename_copy_paste(self, page) -> QHBoxLayout:
        btns = QHBoxLayout()
        copy_btn = QPushButton("Copy")
        copy_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        paste_btn = QPushButton("Paste")
        paste_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        copy_btn.clicked.connect(lambda _=False: self._rename_copy(page))
        paste_btn.clicked.connect(lambda _=False: self._rename_paste(page))
        btns.addWidget(copy_btn)
        btns.addWidget(paste_btn)
        btns.addStretch()
        return btns

    def _rename_on_mode(self, page) -> None:
        if getattr(page, "_rename_updating", False):
            return
        mode = page._rename_mode.currentData() or "file"
        if mode != page._rename_params.get("mode"):
            page._rename_params["mode"] = mode
            self._rename_mark_dirty(page)
        page._rename_stack.setCurrentIndex(0 if mode == "file" else 1)
        self._rename_refresh(page)

    def _rename_cfg(self, page, mode=None):
        params = page._rename_params
        mode = mode or params.get("mode", "file")
        return params.setdefault(mode, {"files": [], "rows": [], "rename": {}})

    def _rename_select_files(self, page) -> None:
        records = self._available_files(page._rename_task_id)
        names = [rec.get("name", "") for rec in records]
        by_name = {rec.get("name", ""): rec.get("parquet") for rec in records}
        mode = page._rename_params.get("mode", "file")
        cfg = self._rename_cfg(page, mode)
        current = [
            self._comp_file_name(p, page._rename_task_id) for p in cfg.get("files") or []
        ]
        chosen = self._pick_items_dialog(
            "Select data files", names, current, "Filter files..."
        )
        if chosen is None:
            return
        paths = [by_name[n] for n in chosen if n in by_name]
        cfg["files"] = paths
        if mode == "file":
            # File mode: the table is one row per selected file.
            existing = {r["original"]: r for r in cfg.get("rows") or []}
            rows = []
            for path in paths:
                if path in existing:
                    rows.append(existing[path])
                else:
                    rows.append({
                        "original": path,
                        "new": self._comp_file_name(path, page._rename_task_id),
                    })
            cfg["rows"] = rows
        else:
            # Column mode: files only set the scope; the variable rows are
            # picked separately. Drop rows whose column is no longer offered.
            union = set(self._rename_column_union(page))
            cfg["rows"] = [
                r for r in (cfg.get("rows") or [])
                if r.get("original") in union
            ]
        self._rename_refresh(page)
        self._rename_mark_dirty(page)

    def _rename_column_union(self, page) -> list:
        cfg = self._rename_cfg(page, "column")
        paths = list(cfg.get("files") or [])
        columns = []
        for path in paths:
            for name in self._columns_for(path, page._rename_task_id):
                if name not in columns:
                    columns.append(name)
        return columns

    def _rename_select_vars(self, page) -> None:
        options = self._rename_column_union(page)
        if not options:
            QMessageBox.information(
                self, "Select variables", "Select data files first."
            )
            return
        cfg = self._rename_cfg(page, "column")
        existing = [r["original"] for r in cfg.get("rows") or []]
        chosen = self._pick_items_dialog(
            "Select variables", options, existing, "Filter variables..."
        )
        if chosen is None:
            return
        kept = {r["original"]: r for r in cfg.get("rows") or []}
        rows = []
        for name in chosen:
            if name in kept:
                rows.append(kept[name])
            else:
                rows.append({"original": name, "new": name})
        cfg["rows"] = rows
        self._rename_refresh(page)
        self._rename_mark_dirty(page)

    def _rename_file_status(self, page, path, new_name, taken) -> tuple:
        new_name = (new_name or "").strip()
        if not new_name:
            return "Empty name", "error"
        if any(c in '\\/:*?"<>|' for c in new_name):
            return "Invalid characters", "error"
        if new_name in taken:
            return "Duplicate name", "error"
        return "", "ok"

    def _rename_column_status(self, page, old, new_name, existing) -> tuple:
        new_name = (new_name or "").strip()
        if not new_name:
            return "Empty name", "error"
        if any(c in '\\/:*?"<>|' for c in new_name):
            return "Invalid characters", "error"
        others = {c for c in existing if c != old}
        if new_name in others:
            return "Duplicate name", "warning"
        return "", "ok"

    def _rename_refresh(self, page) -> None:
        page._rename_updating = True
        try:
            mode = page._rename_params.get("mode", "file")
            page._rename_mode.blockSignals(True)
            page._rename_mode.setCurrentIndex(
                max(0, page._rename_mode.findData(mode))
            )
            page._rename_mode.blockSignals(False)
            page._rename_stack.setCurrentIndex(0 if mode == "file" else 1)
            if mode == "file":
                self._rename_refresh_file(page)
            else:
                self._rename_refresh_column(page)
        finally:
            page._rename_updating = False
        self._rename_update_save_btn(page)

    def _rename_refresh_file(self, page) -> None:
        cfg = self._rename_cfg(page, "file")
        rows = cfg.get("rows") or []

        table = page._rename_file_table
        table.blockSignals(True)
        table.setRowCount(len(rows))
        for i, r in enumerate(rows):
            orig_item = QTableWidgetItem(
                self._comp_file_name(r["original"], page._rename_task_id)
            )
            orig_item.setFlags(Qt.ItemFlag.ItemIsEnabled)
            table.setItem(i, 0, orig_item)
            new_item = QTableWidgetItem(r.get("new", ""))
            table.setItem(i, 1, new_item)
        table.blockSignals(False)
        self._rename_statuses_file(page)

    def _rename_statuses_file(self, page) -> None:
        cfg = self._rename_cfg(page, "file")
        records = self._available_files(page._rename_task_id)
        selected = set(cfg.get("files") or [])
        rows = cfg.get("rows") or []
        taken = set()
        for r in rows:
            n = (r.get("new") or "").strip()
            if n:
                taken.add(n)
        for rec in records:
            if rec.get("parquet") not in selected:
                taken.add(rec.get("name", ""))
        table = page._rename_file_table
        table.blockSignals(True)
        for i, r in enumerate(rows):
            status, sev = self._rename_file_status(
                page, r["original"], r.get("new"),
                taken - {(r.get("new") or "").strip()},
            )
            table.setItem(i, 2, self._rename_status_item(status, sev))
        table.blockSignals(False)

    def _rename_refresh_column(self, page) -> None:
        cfg = self._rename_cfg(page, "column")
        rows = cfg.get("rows") or []

        files_box = page._rename_column_files_box
        files_box.clear()
        for path in cfg.get("files") or []:
            files_box.addItem(self._comp_file_name(path, page._rename_task_id))
        vars_box = page._rename_column_vars_box
        vars_box.clear()
        for r in rows:
            vars_box.addItem(str(r.get("original", "")))

        table = page._rename_column_table
        table.blockSignals(True)
        table.setRowCount(len(rows))
        for i, r in enumerate(rows):
            orig_item = QTableWidgetItem(str(r.get("original", "")))
            orig_item.setFlags(Qt.ItemFlag.ItemIsEnabled)
            table.setItem(i, 0, orig_item)
            new_item = QTableWidgetItem(r.get("new", ""))
            table.setItem(i, 1, new_item)
        table.blockSignals(False)
        self._rename_statuses_column(page)

    def _rename_statuses_column(self, page) -> None:
        cfg = self._rename_cfg(page, "column")
        union = set(self._rename_column_union(page))
        rows = cfg.get("rows") or []
        table = page._rename_column_table
        table.blockSignals(True)
        for i, r in enumerate(rows):
            status, sev = self._rename_column_status(
                page, r["original"], r.get("new"), union
            )
            table.setItem(i, 2, self._rename_status_item(status, sev))
        table.blockSignals(False)

    def _rename_status_item(self, status, severity):
        item = QTableWidgetItem(status)
        item.setFlags(Qt.ItemFlag.ItemIsEnabled)
        if severity == "error":
            item.setForeground(QColor("#c0392b"))
        elif severity == "warning":
            item.setForeground(QColor("#b58900"))
        return item

    def _rename_on_cell(self, page, item, mode) -> None:
        if getattr(page, "_rename_updating", False) or page._rename_locked:
            return
        if item.column() != 1:
            return
        cfg = self._rename_cfg(page, mode)
        rows = cfg.get("rows") or []
        if item.row() >= len(rows):
            return
        rows[item.row()]["new"] = item.text()
        self._rename_mark_dirty(page)
        # Only the validation column changes; rebuild just that, so the editor
        # keeps focus while the user types.
        if mode == "file":
            self._rename_statuses_file(page)
        else:
            self._rename_statuses_column(page)

    def _rename_table_rows(self, page, mode) -> list:
        cfg = self._rename_cfg(page, mode)
        table = (
            page._rename_file_table if mode == "file" else page._rename_column_table
        )
        rows = cfg.get("rows") or []
        out = []
        for i, r in enumerate(rows):
            item = table.item(i, 1)
            new = item.text().strip() if item is not None else r.get("new", "")
            out.append({"original": r["original"], "new": new})
        return out

    def _rename_copy(self, page) -> None:
        mode = page._rename_params.get("mode", "file")
        rows = self._rename_table_rows(page, mode)
        lines = ["original name\tnew name"]
        for r in rows:
            original = (
                self._comp_file_name(r["original"], page._rename_task_id)
                if mode == "file" else str(r["original"])
            )
            lines.append(f"{original}\t{r['new']}")
        QApplication.clipboard().setText("\n".join(lines))

    def _rename_paste(self, page) -> None:
        mode = page._rename_params.get("mode", "file")
        text = QApplication.clipboard().text()
        lines = [ln.rstrip("\r") for ln in text.split("\n") if ln.strip()]
        if not lines:
            return
        header = lines[0].split("\t")
        if header != ["original name", "new name"]:
            QMessageBox.warning(
                self, "Paste",
                "The pasted table must start with the header "
                "'original name\\tnew name' (copy the table first).",
            )
            return
        pasted = [ln.split("\t") for ln in lines[1:]]
        cfg = self._rename_cfg(page, mode)
        rows = cfg.get("rows") or []
        current_originals = [
            self._comp_file_name(r["original"], page._rename_task_id)
            if mode == "file" else str(r["original"])
            for r in rows
        ]
        if len(pasted) != len(current_originals):
            QMessageBox.warning(
                self, "Paste",
                "The pasted row count does not match the current table.",
            )
            return
        for idx, (expected, row) in enumerate(zip(current_originals, pasted)):
            if len(row) < 1 or row[0] != expected:
                QMessageBox.warning(
                    self, "Paste",
                    f"Row {idx + 1}: the original name does not match.",
                )
                return
        for r, row in zip(rows, pasted):
            r["new"] = (row[1] if len(row) > 1 else "").strip()
        self._rename_refresh(page)
        self._rename_mark_dirty(page)

    def _rename_apply(self, page) -> None:
        """Store the valid-only rename map for the current mode."""
        mode = page._rename_params.get("mode", "file")
        cfg = self._rename_cfg(page, mode)
        rows = cfg.get("rows") or []
        applied = {}
        for r in rows:
            original = r["original"]
            new = (r.get("new") or "").strip()
            if not new:
                continue
            if mode == "file":
                taken = set()
                for other in rows:
                    if other is r:
                        continue
                    n = (other.get("new") or "").strip()
                    if n:
                        taken.add(n)
                for rec in self._available_files(page._rename_task_id):
                    if rec.get("parquet") not in (cfg.get("files") or []):
                        taken.add(rec.get("name", ""))
                status, _sev = self._rename_file_status(page, original, new, taken)
                if status:
                    continue
            else:
                status, _sev = self._rename_column_status(
                    page, original, new, set(self._rename_column_union(page))
                )
                if status == "Empty name" or status == "Invalid characters":
                    continue
            applied[str(original)] = new
        cfg["rename"] = applied

    def _rename_mark_dirty(self, page) -> None:
        page._rename_dirty = True
        self._rename_update_save_btn(page)
        self._module_set_state(page, MODULE_STATE_MODIFIED)

    def _rename_update_save_btn(self, page) -> None:
        btn = getattr(page, "_rename_save_btn", None)
        if btn is not None:
            btn.setEnabled(page._rename_dirty and not page._rename_locked)

    def _rename_save_now(self, page) -> None:
        self._rename_apply(page)
        page._rename_task_def["params"] = page._rename_params
        if self.project is not None:
            self.project.save()
        page._rename_dirty = False
        self._rename_update_save_btn(page)
        self.statusBar().showMessage("Rename settings saved")
        self._module_saved(page)

    def _rename_close(self, page) -> None:
        if getattr(page, "_rename_dirty", False):
            reply = QMessageBox.question(
                self, "Close Rename",
                "There are unsaved changes.\nClose without saving? "
                "Unsaved changes will be lost.",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return
        self._close_module_page(page)

    # ----- dimension reduction module (generate) -------------------------
    _DIMRED_SEED = 42
    _DIMRED_PCA_DIMS = 50

    def _build_dimred_page(self, name: str, task_def: dict, locked: bool) -> QWidget:
        """Build the Dimension Reduction page: method/files | variables | params | log."""
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        bar = QFrame()
        bar.setObjectName("moduleBar")
        tl = QHBoxLayout(bar)
        tl.setContentsMargins(12, 6, 12, 6)
        tl.setSpacing(4)
        tl.addWidget(QLabel(f"<b>{self._module_display_title(task_def.get('id'), name)}</b>"))
        if locked:
            lock_icon = QLabel()
            lock_icon.setPixmap(_lock_pixmap())
            lock_icon.setFixedSize(14, 14)
            lock_icon.setToolTip("Locked — a downstream generate module has saved data")
            tl.addWidget(lock_icon)
            draft = QLabel("Draft (locked)")
            draft.setStyleSheet("color: #b58900; font-weight: bold;")
            tl.addWidget(draft)
        tl.addStretch()
        save_btn = QPushButton("Save")
        save_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        save_btn.setEnabled(not locked)
        close_btn = QPushButton("Close")
        close_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        close_btn.clicked.connect(lambda _=False: self._dimred_close(page))
        tl.addWidget(save_btn)
        tl.addWidget(close_btn)
        layout.addWidget(bar)

        params = task_def.setdefault("params", {})
        params.setdefault("method", "umap")
        params.setdefault("files", [])
        params.setdefault("columns", [])
        params.setdefault("normalize", True)
        params.setdefault("pca", True)
        params.setdefault("parallel", True)
        params.setdefault("tsne_backend", "sklearn")
        params.setdefault("max_events", 5000)
        params.setdefault("umap", {"n_neighbors": 15, "min_dist": 0.1})
        params.setdefault("tsne", {"perplexity": 30, "n_iter": 1000})
        params.setdefault("names", ["umap_1", "umap_2"])
        params.setdefault("outputs", {})
        params.setdefault("log", [])
        page._dimred_task_def = task_def
        page._dimred_task_id = task_def.get("id")
        page._dimred_params = params
        page._dimred_locked = locked
        page._dimred_save_btn = save_btn
        page._dimred_dirty = False
        page._dimred_snapshot = copy.deepcopy(params)
        page._dimred_log_lines = list(params.get("log") or [])
        page._dimred_running = False
        page._dimred_cancel = False
        page._dimred_updating = False
        save_btn.clicked.connect(lambda _=False: self._dimred_save_now(page))

        content = QWidget()
        content.setStyleSheet("background: #f5f8fb;")
        row = QVBoxLayout(content)
        row.setContentsMargins(12, 12, 12, 12)
        row.setSpacing(10)

        splitter = QSplitter(Qt.Orientation.Horizontal)
        splitter.setChildrenCollapsible(False)
        splitter.addWidget(self._dimred_left_panel(page))
        splitter.addWidget(self._dimred_center_panel(page))
        splitter.addWidget(self._dimred_right_panel(page))
        splitter.setStretchFactor(0, 1)
        splitter.setStretchFactor(1, 1)
        splitter.setStretchFactor(2, 1)
        splitter.setSizes([320, 320, 420])
        row.addWidget(splitter, 1)

        row.addWidget(self._dimred_log_panel(page))
        layout.addWidget(content, 1)

        self._dimred_refresh(page)
        self._dimred_warm_umap()
        return page

    def _dimred_warm_umap(self) -> None:
        """Pre-compile UMAP's numba kernels in the background.

        UMAP's first fit_transform in a process spends ~30 s on numba JIT
        compilation (the "cold" run). Warming it up while the user configures
        the module hides that one-time cost from their first Calculate.
        """
        if getattr(self, "_umap_warmed", False):
            return
        self._umap_warmed = True

        def _warm():
            import numpy as np
            import umap

            try:
                umap.UMAP(
                    n_neighbors=15, min_dist=0.1, n_components=2, random_state=42
                ).fit_transform(
                    np.random.default_rng(0).normal(0, 1, (300, 4))
                )
            except Exception:  # noqa: BLE001
                pass

        threading.Thread(target=_warm, daemon=True).start()

    def _dimred_warm_opentsne(self) -> None:
        """Pre-compile openTSNE's numba kernels the first time it is chosen."""
        if getattr(self, "_opentsne_warmed", False):
            return
        self._opentsne_warmed = True

        def _warm():
            import numpy as np

            try:
                from openTSNE import TSNE

                TSNE(
                    n_components=2, perplexity=30, n_iter=50, random_state=42
                ).fit(np.random.default_rng(0).normal(0, 1, (300, 4)))
            except Exception:  # noqa: BLE001
                pass

        threading.Thread(target=_warm, daemon=True).start()

    def _dimred_log_panel(self, page) -> QWidget:
        panel = self._build_panel_frame()
        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        lay.addWidget(QLabel("<b>Log</b>"))
        log = QPlainTextEdit()
        log.setReadOnly(True)
        log.setPlaceholderText("Calculation output appears here…")
        log.setStyleSheet(
            "background: #1e1e1e; color: #d4d4d4; "
            "font-family: Consolas, monospace; font-size: 9pt;"
        )
        log.setFixedHeight(130)
        for line in getattr(page, "_dimred_log_lines", []):
            log.appendPlainText(line)
        lay.addWidget(log)
        page._dimred_log = log
        return panel

    def _dimred_log(self, page, text) -> None:
        ts = datetime.now().strftime("%H:%M:%S")
        lines = getattr(page, "_dimred_log_lines", None)
        if lines is None:
            lines = []
            page._dimred_log_lines = lines
        for line in str(text).splitlines():
            if line.strip():
                lines.append(f"[{ts}] {line}")
        if len(lines) > _FEATURE_LOG_LIMIT:
            del lines[:-_FEATURE_LOG_LIMIT]
        if getattr(page, "_dimred_params", None) is not None:
            page._dimred_params["log"] = list(lines)
        box = getattr(page, "_dimred_log", None)
        if box is not None:
            for line in str(text).splitlines():
                if line.strip():
                    box.appendPlainText(f"[{ts}] {line}")

